// Fundraise was momentum-cost + seat-based cash yield (5 escalating
// tiers per tick). Replaced in 20260728 with a sector-popularity
// positioning system (1 use per tick, no cash, themed events from
// the fundraiser_events catalog). Use-count is still tracked via
// campaign_actions so the per-tick gate survives reload.
let _fundraiseUseCount = 0; // loaded from DB on init, not just session state
let _noConfidenceCooldownTicks = 0; // ticks remaining before another vonc can be filed against the current PM party
let _noConfidencePending = false;   // there's already a pending no_confidence bill in this nation
// Form Minority Government — gate state. Loaded once during panel init so the
// LEADER_ACTIONS render can lock/unlock the action without per-frame fetches.
// Server re-validates everything; this is just the UI hint. metaLine is the
// red sub-title under the action card name: shows the last-election date +
// when the deadlock breaker becomes available, or "Active Coalition" when a
// government is already seated.
let _minorityGate = { eligible: false, lockReason: 'Loading...', metaLine: '' };

async function loadFundraiseCount() {
    if (!_supabase || !_state?.faction?.id || !_state?.shard?.current_tick) return;
    const { count, error } = await _supabase.from('campaign_actions')
        .select('id', { count: 'exact', head: true })
        .eq('party_id', _state.faction.id)
        .eq('action_type', 'fundraise')
        .eq('tick_performed', _state.shard.current_tick);
    _fundraiseUseCount = (!error && count != null) ? count : 0;
}

// Pulls the per-targeted-PM-party cooldown for vote of no confidence + checks
// for an already-pending motion in this nation. Both feed the lock state on the
// "Vote of No Confidence" leader action so the button reflects reality.
async function loadNoConfidenceState() {
    _noConfidenceCooldownTicks = 0;
    _noConfidencePending = false;
    if (!_supabase || !_state?.nation?.id || !_state?.shard?.current_tick) return;
    const tick   = _state.shard.current_tick;
    const pmId   = _administration?.pm_party_id;
    try {
        // Pending motion (committee or floor)?
        const { data: pendBills } = await _supabase.from('bills')
            .select('id')
            .eq('nation_id', _state.nation.id)
            .eq('bill_type', 'no_confidence')
            .in('status', ['committee', 'floor'])
            .limit(1);
        _noConfidencePending = !!(pendBills && pendBills.length);

        // Cooldown against the current PM party (not the filing party).
        if (pmId) {
            const { data: lastFiled } = await _supabase.from('campaign_actions')
                .select('tick_performed')
                .eq('nation_id', _state.nation.id)
                .eq('action_type', 'no_confidence_filed')
                .eq('target_id', pmId)
                .order('tick_performed', { ascending: false })
                .limit(1)
                .maybeSingle();
            if (lastFiled) {
                const elapsed = tick - Number(lastFiled.tick_performed || 0);
                const cooldown = (typeof GAME_CONFIG !== 'undefined' && GAME_CONFIG.NO_CONFIDENCE_COOLDOWN_TICKS) || 12;
                _noConfidenceCooldownTicks = Math.max(0, cooldown - elapsed);
            }
        }
    } catch (e) {
        // Non-fatal: action defaults to unlocked if we can't determine state.
        console.warn('[PartyActions] loadNoConfidenceState failed:', e?.message || e);
    }
}

// Resolves the eligibility + lock-reason for the Form Minority Government
// action. Mirrors the server-side gates in form_minority_government RPC
// (sql/migrations/20261003_form_minority_government_rpc.sql) — kept in sync
// so the UI lock copy matches what the RPC would have rejected with.
async function loadMinorityGovState() {
    _minorityGate = { eligible: false, lockReason: 'Loading...', metaLine: '' };
    if (!_supabase || !_state?.nation?.id || !_state?.faction?.id) return;
    const nation = _state.nation;
    const faction = _state.faction;
    const tick = Number(_state?.shard?.current_tick) || 0;

    const govType = (nation.government_type || '').toLowerCase();
    if (govType.includes('absolute monarchy') || govType.includes('absolute_monarchy')) {
        _minorityGate = { eligible: false, lockReason: 'Only available in parliamentary systems.', metaLine: '' };
        return;
    }

    if ((faction.seats || 0) <= 0) {
        _minorityGate = { eligible: false, lockReason: 'Your party has no parliamentary seats.', metaLine: '' };
        return;
    }

    // Already-formed government blocks the action.
    if (_activeCoalition && (_activeCoalition.status === 'formed' || _activeCoalition.status === 'caretaker')) {
        const isMinority = _activeCoalition.formation_type === 'emergency_minority';
        _minorityGate = {
            eligible: false,
            lockReason: isMinority ? 'A minority government is already in place.' : 'A government is already in place.',
            metaLine: 'Active Coalition',
        };
        return;
    }

    // Need a completed election. Use the same query shape as the RPC — latest
    // election with results. fetchActiveCoalition already filters on this so
    // we duplicate the lookup minimally.
    const { data: latestElection } = await _supabase.from('elections')
        .select('id, election_tick')
        .eq('nation_id', nation.id)
        .eq('status', 'completed')
        .not('results', 'is', null)
        .order('election_tick', { ascending: false })
        .limit(1)
        .maybeSingle();
    if (!latestElection) {
        _minorityGate = { eligible: false, lockReason: 'No completed election to form a government from.', metaLine: 'No election yet' };
        return;
    }

    const electionTick = Number(latestElection.election_tick || 0);
    const formationDeadline = (typeof FORMATION_DEADLINE_TICKS === 'number') ? FORMATION_DEADLINE_TICKS : 3;
    const availableTick = electionTick + formationDeadline;
    const ticksSinceElection = tick - electionTick;
    const metaLine = `Last election: ${tickToDate(electionTick)} · Becomes available ${tickToDate(availableTick)}`;

    if (ticksSinceElection < formationDeadline) {
        const remaining = formationDeadline - ticksSinceElection;
        _minorityGate = {
            eligible: false,
            lockReason: `Coalition window still open: ${remaining} tick${remaining !== 1 ? 's' : ''} remaining.`,
            metaLine,
        };
        return;
    }

    // Reject if any party has outright majority — they should form normally.
    const totalSeats = Number(nation.total_seats) || 100;
    const majority = Math.floor(totalSeats / 2) + 1;
    const { data: allPartiesData, error: pErr } = await _supabase.from('factions')
        .select('id, faction_name, seats, last_seen_tick')
        .eq('nation_id', nation.id)
        .eq('faction_type', 'party');
    if (pErr) {
        _minorityGate = { eligible: false, lockReason: 'Could not load party state.', metaLine };
        return;
    }
    const allParties = allPartiesData || [];
    const hasMajorityParty = allParties.some(p => (p.seats || 0) >= majority);
    if (hasMajorityParty) {
        _minorityGate = {
            eligible: false,
            lockReason: 'A party already holds an outright majority — form a normal government instead.',
            metaLine,
        };
        return;
    }

    // Caller must be the largest active party (last_seen_tick within 4 ticks,
    // mirroring INACTIVITY_TICKS in coalition-formation.js). Tiebreak: id ASC,
    // matching the server.
    const INACTIVITY_TICKS = 4;
    const activeParties = allParties
        .filter(p => (p.seats || 0) > 0 && (Number(p.last_seen_tick) || 0) >= tick - INACTIVITY_TICKS)
        .sort((a, b) => (b.seats || 0) - (a.seats || 0) || (a.id < b.id ? -1 : 1));
    const largest = activeParties[0];
    if (!largest) {
        _minorityGate = { eligible: false, lockReason: 'No active parties qualify to form a government.', metaLine };
        return;
    }
    // Admin override skips the largest-active gate. Server-side
    // form_minority_government has its own is_admin() bypass that
    // anchors the formation to v_largest_active regardless of the
    // inspected faction (20261011), so the RPC will install CPP
    // even though the UI is viewing a different party.
    if (largest.id !== faction.id && !getAdminFactionOverride()) {
        _minorityGate = {
            eligible: false,
            lockReason: `Only the largest active party (${largest.faction_name || 'unknown'}) may form a minority government.`,
            metaLine,
        };
        return;
    }

    _minorityGate = { eligible: true, lockReason: '', metaLine };
}

