function listHeldMinistryKeys(faction) {
    const keys = [];
    const hog = classifyHeadOfGovernment(faction);
    if (hog.isPM) keys.push('prime_minister');
    if (hog.isPresident && hasElectedPresident(_state?.nation)) keys.push('president');
    for (const m of getHeldCabinetMinistries(faction)) keys.push(m.ministry_key);
    return keys;
}

function renderCabinetMinistriesPanel(faction) {
    const keys = listHeldMinistryKeys(faction);
    // Spec: "If you have none, it'll stay empty."
    if (keys.length === 0) return '';
    const cards = keys.map(k => {
        const r = ministryRoleDescriptor(k, faction);
        const isActive = _selectedRole === r.roleId;
        const actionCount = (r.actions || []).length;
        return `
            <div class="pa-leader-card pa-leader-card--ministry ${isActive ? 'active' : ''}"
                 data-role="${esc(r.roleId)}"
                 style="${isActive ? `border-left-color:#c8a832;` : ''}">
                <div class="pa-leader-top">
                    <div class="pa-leader-avatar" style="color:#c8a832;background:#c8a83215;border-color:#c8a83233;">${esc(r.chip)}</div>
                    <div class="pa-leader-info">
                        <div class="pa-leader-role">
                            <span class="pa-leader-role-label" style="color:#c8a832;">${esc(r.shortRole.toUpperCase())}</span>
                            ${actionCount > 0 ? `<span class="pa-leader-role-count">${actionCount} action${actionCount === 1 ? '' : 's'}</span>` : ''}
                        </div>
                        <div class="pa-leader-name">${esc(r.personName)}</div>
                    </div>
                </div>
            </div>
        `;
    }).join('');
    return `
        <div class="pa-cabinet-header">
            <span class="pa-cabinet-header__title">Cabinet Ministries</span>
            <span class="pa-cabinet-header__count">${keys.length} held</span>
        </div>
        ${cards}
    `;
}

function ministryActionLockReason(actionId, faction, roleDescriptor) {
    const nation = _state?.nation;
    // SOE placeholder is greyed out + not clickable until the backend
    // exists. The .locked class on the rendered card both styles the
    // greyed state and makes the panel-level click handler skip it.
    if (actionId === 'stateOwnedEnterprise') {
        return 'Coming soon — backend not yet wired.';
    }
    if (actionId === 'debt_payment') {
        const balance = Number(roleDescriptor?.discretionaryBalance ?? 0);
        if (balance < 3_000_000) {
            return 'Finance Ministry discretionary budget is below $3 — need at least $2 fee + $1 minimum payment.';
        }
        const debtRaw = Number(_state?.nation?.debt ?? 0);
        if (debtRaw <= 0) {
            return 'No national debt to pay down.';
        }
    }
    if (actionId === 'allocate_funds') {
        const balance = Number(roleDescriptor?.discretionaryBalance ?? 0);
        if (balance < 1_000_000) {
            return 'Defense Ministry discretionary budget is $0 — pass a funding bill first.';
        }
    }
    if (actionId === 'press_claim') {
        const balance = Number(roleDescriptor?.discretionaryBalance ?? 0);
        if (balance < 3_000_000) {
            return 'Foreign Ministry discretionary budget is below $3 — pass a funding bill first.';
        }
    }
    if (actionId === 'cb_lower_rate' || actionId === 'cb_raise_rate') {
        if (Number(nation?.central_bank_discretionary ?? 0) < 1_000_000) {
            return 'The Central Bank lending pool is empty — $1 is required to move the rate. Fund it with a funding bill.';
        }
    }
    if (actionId === 'invest_in_sports_culture') {
        // Cheapest tier (Low = $2M). If the discretionary budget can't
        // cover even that, lock the card so the player sees why.
        const balance = Number(roleDescriptor?.discretionaryBalance ?? 0);
        if (balance < 2_000_000) {
            return 'Sports Ministry discretionary budget is below $2M — pass a funding bill first.';
        }
    }
    if (actionId === 'expand_infrastructure') {
        // Cheapest tier (small = $2M post fee). The post-RPC also
        // enforces a one-open-or-active cap, but we can't see that
        // without a query — fall through and let the modal surface
        // the existing contract.
        const balance = Number(roleDescriptor?.discretionaryBalance ?? 0);
        if (balance < 2_000_000) {
            return 'Interior Ministry discretionary budget is below $2 — pass a funding bill first.';
        }
    }
    // Ministry survey actions (see SURVEY_CONFIG): lock state is owned
    // by patchSurveyCard, which reads the live server cost + cooldown
    // after render. Returning '' here means the card paints unlocked
    // first; the patch downgrades it to locked if needed.
    if (actionId === 'call_early_elections' || actionId === 'resign_as_pm') {
        // Reachable only inside the PM detail panel (renderMinistryDetail
        // is gated on classifyHeadOfGovernment.isPM), so the PM-only /
        // parliamentary checks are implicit. The two states that still
        // require a lock are absolute monarchy and a caretaker coalition.
        if (isAbsoluteMonarchy(nation)) {
            return actionId === 'call_early_elections'
                ? 'Elections are not held under absolute monarchy.'
                : 'PM serves at the Monarch’s pleasure; only the Monarch can replace them.';
        }
        if (nation?.__coalition_status === 'caretaker') {
            return 'Government already in caretaker mode.';
        }
    }
    return '';
}

function renderMinistryDetail(faction, partyColor) {
    const key = _selectedRole.startsWith('ministry:') ? _selectedRole.slice('ministry:'.length) : null;
    if (!key) return '';
    const r = ministryRoleDescriptor(key, faction);
    const ageStr = r.personAge != null ? `, Age ${r.personAge}` : '';
    // PM and President roles aren't tied to a ministries row — they
    // don't carry a discretionary balance. Show it only for keys that
    // have a real cabinet seat.
    const isGovernor = key === 'central_bank_governor';
    const showBalance = !isGovernor && key !== 'prime_minister' && key !== 'president' && r.ministryId;

    // Central Bank readout: current policy rate + display-only lending
    // capital (each $1 of the discretionary pool backs $100M). Shown in
    // the detail header in place of a ministry discretionary balance.
    let governorReadout = '';
    if (isGovernor) {
        const n = _state?.nation || {};
        const rate = Number(n.central_bank_interest_rate ?? 5);
        const poolAbstract = cbPoolAbstract(n.central_bank_discretionary);
        const lendingM = poolAbstract * 100;  // each $1 ($1M) backs $100M
        const lendingFmt = lendingM >= 1000
            ? `$${(lendingM / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 })}B`
            : `$${lendingM.toLocaleString()}M`;
        const termEnd = Number(n.central_bank_governor_term_end_tick ?? 0);
        const ticksLeft = Math.max(0, termEnd - Number(_state?.shard?.current_tick ?? 0));
        governorReadout = `
            <div style="text-align:right;font-family:var(--font-mono);flex-shrink:0;">
                <div style="font-size:9px;letter-spacing:0.14em;color:var(--text-dim);text-transform:uppercase;">Policy Rate</div>
                <div style="font-size:18px;font-weight:700;color:#c8a832;margin-top:2px;">${rate.toFixed(2)}%</div>
                <div style="font-size:8px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;margin-top:6px;">Lending Capital</div>
                <div style="font-size:12px;font-weight:700;color:var(--green);">${lendingFmt}</div>
                <div style="font-size:8px;color:var(--text-dim);margin-top:4px;">Term: ${ticksLeft} ticks left · pool $${poolAbstract.toLocaleString()}</div>
            </div>`;
    }

    // Matches the structure in renderActionsPanel's leader action loop
    // so the existing pa-action-item / pa-action-top / pa-action-right
    // styles apply without new CSS.
    const actionsHtml = (r.actions || []).map(a => {
        const lockReason = ministryActionLockReason(a.id, faction, r);
        const isDisabled = !!lockReason;
        // Dynamic costs (e.g. ministry survey actions whose cost escalates
        // per use) paint their action-def value first, then get patched
        // in-place by a post-render fetch (patchSurveyCard). The static
        // value is a placeholder until the patch lands.
        const displayCost = a.cost || '';
        const tagsHtml = (a.tags || []).map(t =>
            `<span class="pa-action-tag" style="color:${TAG_COLORS[t] || 'var(--text-dim)'};">${esc(t)}</span>`
        ).join('');
        return `
            <div class="pa-action-item ${isDisabled ? 'locked' : ''}" data-action-id="${esc(a.id)}">
                <div class="pa-action-top">
                    <div style="display:flex;align-items:center;gap:8px;">
                        <span class="pa-action-name">${esc(a.name)}</span>
                        <div class="pa-action-tags">${tagsHtml}</div>
                    </div>
                    <div class="pa-action-right">
                        <span class="pa-action-cost" style="color:${a.costColor || 'var(--text-dim)'};">${esc(displayCost)}</span>
                    </div>
                </div>
                <div class="pa-action-desc">${esc(a.desc)}</div>
                ${isDisabled && lockReason ? `<div style="margin-top:4px;font-family:var(--font-mono);font-size:7px;color:var(--orange);display:flex;align-items:center;gap:4px;"><span>&#8856;</span><span>${esc(lockReason)}</span></div>` : ''}
            </div>
        `;
    }).join('');

    return `
        <div class="pa-detail-header" style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px;">
            <div class="pa-detail-left">
                <div class="pa-detail-avatar" style="color:#c8a832;background:#c8a83215;border-color:#c8a83233;">${esc(r.chip)}</div>
                <div>
                    <div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;">
                        <span style="font-family:var(--font-mono);font-size:20px;font-weight:700;color:#c8a832;">${esc(r.fullTitle.toUpperCase())}</span>
                        <span class="pa-detail-name">${esc(r.personName)}</span>
                    </div>
                    <div class="pa-detail-meta">
                        ${esc(r.shortRole)} &middot; ${esc(faction.faction_name)}${esc(ageStr)}
                        <span style="color:#c8a832;font-weight:700;"> &middot; ${esc(r.domain)}</span>
                    </div>
                </div>
            </div>
            ${showBalance ? `
                <div style="text-align:right;font-family:var(--font-mono);flex-shrink:0;">
                    <div style="font-size:9px;letter-spacing:0.14em;color:var(--text-dim);text-transform:uppercase;">Discretionary Budget</div>
                    <div style="font-size:14px;font-weight:700;color:${r.discretionaryBalance > 0 ? 'var(--green)' : 'var(--red)'};margin-top:2px;">${fmtDiscretionaryBalance(r.discretionaryBalance)}</div>
                </div>
            ` : ''}
            ${governorReadout}
        </div>
        ${isGovernor ? '<div id="cb-loan-requests" style="margin-bottom:14px;"></div>' : ''}
        <div class="pa-actions-list">
            ${(r.actions && r.actions.length > 0)
                ? actionsHtml
                : `<div class="pa-vacant-msg"><div><div class="pa-vacant-title">${esc(r.fullTitle)} — No actions yet</div><div class="pa-vacant-sub">Per-ministry actions land here as they ship.</div></div></div>`
            }
        </div>
    `;
}

// Friendly text for a loan-decision RPC failure reason.
function cbDecideError(reason) {
    return ({
        not_governor: 'You no longer hold the Governor seat.',
        term_expired: 'Your term has expired.',
        not_pending: 'This request was already decided.',
        loan_not_found: 'Request not found.',
        insufficient_capacity: 'Not enough lending capital to issue this loan.',
        not_authenticated: 'Not signed in.',
    })[reason] || (reason ? String(reason) : 'Action failed.');
}

// Fill the Governor's pending-loan-request panel (placeholder #cb-loan-requests,
// present only on the Governor detail). Each request shows corp, amount, the
// corp's existing debt and the entrepreneur's reputation, with Issue / Reject.
// Re-fills after a decision so the decided card disappears. Buttons are wired
// on fresh DOM each fill, so listeners can't stack.
async function mountCbLoanRequests(faction) {
    const host = document.getElementById('cb-loan-requests');
    if (!host) return;                                   // not the Governor view
    const nationId = _state?.nation?.id;
    if (!_supabase || !nationId || !isCentralBankGovernor(faction)) { host.innerHTML = ''; return; }

    const { data: loans, error } = await _supabase
        .from('central_bank_loans')
        .select('id, principal, term_ticks, borrower_corp_id, corp:entrepreneur_corps!borrower_corp_id(name, owner_faction_id)')
        .eq('nation_id', nationId).eq('status', 'pending')
        .order('created_at', { ascending: true });
    if (error) { console.warn('[party-actions] CB loan requests load failed:', error.message); host.innerHTML = ''; return; }
    if (!loans || !loans.length) { host.innerHTML = ''; return; }

    // Reputation per owner (batch) + existing debt per corp (the one-source RPC).
    const ownerIds = [...new Set(loans.map(l => l.corp?.owner_faction_id).filter(Boolean))];
    const repByOwner = {};
    if (ownerIds.length) {
        const { data: facs } = await _supabase.from('factions').select('id, corp_reputation').in('id', ownerIds);
        for (const f of (facs || [])) repByOwner[f.id] = Number(f.corp_reputation);
    }
    const debts = await Promise.all(loans.map(l =>
        _supabase.rpc('entrepreneur_corp_outstanding_debt', { p_corp_id: l.borrower_corp_id })
            .then(r => Number(r.data) || 0).catch(() => 0)));
    const cbAmt = (raw) => '$' + cbPoolAbstract(raw).toLocaleString();

    host.innerHTML = `
        <div style="font-family:var(--font-mono);font-size:10px;letter-spacing:0.14em;text-transform:uppercase;color:#c8a832;margin-bottom:8px;">New Loan Request${loans.length > 1 ? 's' : ''}</div>
        ${loans.map((l, i) => {
            const corp = l.corp || {};
            const rep = repByOwner[corp.owner_faction_id];
            return `
            <div class="cb-lr-card" data-loan-id="${esc(l.id)}" style="border:0.5px solid #c8a83244;background:#c8a8320c;border-radius:6px;padding:12px 14px;margin-bottom:8px;">
                <div style="font-size:13px;font-weight:700;color:var(--text-bright);margin-bottom:8px;">${esc(corp.name || 'Unknown corp')}</div>
                <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;font-family:var(--font-mono);">
                    <div><div style="font-size:8px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;">Loan Amount</div><div style="font-size:13px;font-weight:600;color:var(--text-bright);margin-top:2px;">${cbAmt(l.principal)}</div></div>
                    <div><div style="font-size:8px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;">Existing Debt</div><div style="font-size:13px;font-weight:600;color:var(--text-primary);margin-top:2px;">${cbAmt(debts[i])}</div></div>
                    <div><div style="font-size:8px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;">Reputation</div><div style="font-size:13px;font-weight:600;color:var(--text-primary);margin-top:2px;">${Number.isFinite(rep) ? rep.toFixed(1) + '/10' : '—'}</div></div>
                    <div><div style="font-size:8px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;">Term</div><div style="font-size:13px;font-weight:600;color:var(--text-primary);margin-top:2px;">${Number(l.term_ticks)} ticks</div></div>
                </div>
                <div class="cb-lr-err" hidden style="margin-top:8px;font-family:var(--font-mono);font-size:10px;color:var(--red);"></div>
                <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px;">
                    <button data-cb-decide="reject" data-loan-id="${esc(l.id)}" style="font-family:var(--font-mono);font-size:11px;font-weight:700;letter-spacing:0.06em;padding:7px 14px;border-radius:3px;cursor:pointer;background:none;border:1px solid var(--red);color:var(--red);">Reject</button>
                    <button data-cb-decide="issue" data-loan-id="${esc(l.id)}" style="font-family:var(--font-mono);font-size:11px;font-weight:700;letter-spacing:0.06em;padding:7px 14px;border-radius:3px;cursor:pointer;background:#c8a832;border:1px solid #c8a832;color:#1a1a17;">Issue Loan</button>
                </div>
            </div>`;
        }).join('')}`;

    host.querySelectorAll('[data-cb-decide]').forEach(btn => {
        btn.addEventListener('click', async () => {
            const card = btn.closest('.cb-lr-card');
            const errEl = card?.querySelector('.cb-lr-err');
            card?.querySelectorAll('[data-cb-decide]').forEach(b => { b.disabled = true; b.style.opacity = '0.5'; });
            if (errEl) { errEl.hidden = true; errEl.textContent = ''; }
            try {
                const fn = btn.dataset.cbDecide === 'issue' ? 'issue_central_bank_loan' : 'reject_central_bank_loan';
                const { data, error: rpcErr } = await _supabase.rpc(fn, { p_loan_id: btn.dataset.loanId });
                if (rpcErr || (data && data.success === false)) {
                    if (errEl) { errEl.textContent = cbDecideError((data && data.reason) || rpcErr?.message); errEl.hidden = false; }
                    card?.querySelectorAll('[data-cb-decide]').forEach(b => { b.disabled = false; b.style.opacity = '1'; });
                } else {
                    await mountCbLoanRequests(faction);   // decided card disappears
                }
            } catch (ex) {
                if (errEl) { errEl.textContent = ex?.message || 'Action failed.'; errEl.hidden = false; }
                card?.querySelectorAll('[data-cb-decide]').forEach(b => { b.disabled = false; b.style.opacity = '1'; });
            }
        });
    });
}

function renderActionsPanel(leaderName, partyColor, faction) {
    // Cabinet / PM / President cards use synthetic roles
    // ("ministry:<key>"); branch out to their own detail renderer.
    if (typeof _selectedRole === 'string' && _selectedRole.startsWith('ministry:')) {
        return renderMinistryDetail(faction, partyColor);
    }
    const _isMonarchy = isAbsoluteMonarchy(_state.nation);
    const _isMonarch = _isMonarchy && _state.nation?.monarch_faction_id === faction?.id;
    const role = ROLES.find(r => r.id === _selectedRole);
    if (!role) return '';

    const isLeader = _selectedRole === 'leader';
    const isAgitator = _selectedRole === 'agitator';
    const isCampaign = _selectedRole === 'campaign';
    const isDeputy = _selectedRole === 'deputy';
    const isVacant = !isLeader && !isAgitator && !isCampaign && !isDeputy;

    if (isVacant) {
        return `
            <div class="pa-vacant-msg">
                <div>
                    <div class="pa-vacant-title">${esc(role.fullTitle)} — Vacant</div>
                    <div class="pa-vacant-sub">This position has not been filled. Recruitment coming in a future update.</div>
                </div>
            </div>
        `;
    }

    // Agitator: blocked if in government
    if (isAgitator && !_isOpposition) {
        return `
            <div class="pa-vacant-msg" style="opacity:0.4;">
                <div style="text-align:center;">
                    <div style="font-size:2rem;margin-bottom:12px;opacity:0.3;">🚫</div>
                    <div class="pa-vacant-title">Agitator Unavailable</div>
                    <div class="pa-vacant-sub" style="max-width:400px;margin:8px auto;">
                        Your party is in government. The Agitator role is only available to opposition parties.
                    </div>
                </div>
            </div>
        `;
    }

    // Agitator: not hired → show hire prompt
    if (isAgitator && !_agitator) {
        return `
            <div class="pa-vacant-msg" style="cursor:pointer;" id="pa-hire-agitator-panel">
                <div style="text-align:center;">
                    <div style="font-size:2rem;margin-bottom:12px;opacity:0.4;">&#9760;</div>
                    <div class="pa-vacant-title">Hire an Opposition Coordinator</div>
                    <div class="pa-vacant-sub" style="max-width:400px;margin:8px auto 16px;">
                        The Agitator leads your opposition strategy — filing lawsuits, organizing protests, and applying legal and political pressure against the government.
                    </div>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-hire-agitator-btn" style="background:#d44a4a;">Search Candidates</button>
                </div>
            </div>
        `;
    }

    // Agitator: hired → show their actions
    if (isAgitator && _agitator) {
        return renderAgitatorActionsPanel(role);
    }

    // Deputy: not hired → show hire prompt; hired → show Rally action
    if (isDeputy && !_deputy) {
        return `
            <div class="pa-vacant-msg" style="cursor:pointer;" id="pa-hire-deputy-panel">
                <div style="text-align:center;">
                    <div style="font-size:2rem;margin-bottom:12px;opacity:0.4;">🤝</div>
                    <div class="pa-vacant-title">Hire a Deputy Party Leader</div>
                    <div class="pa-vacant-sub" style="max-width:400px;margin:8px auto 16px;">
                        The Deputy supports your party leader — organizing rallies, boosting momentum, and energizing the base.
                    </div>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-hire-deputy-btn" style="background:#8b9a6b;">Search Candidates</button>
                </div>
            </div>
        `;
    }
    if (isDeputy && _deputy) {
        return renderDeputyActionsPanel(role);
    }

    // Campaign Manager: show rebrand action
    if (isCampaign) {
        return renderCampaignManagerPanel(role, faction);
    }

    const portrait = initials(faction.leader_first_name, faction.leader_last_name);
    const age = faction.leader_age ? `, Age ${faction.leader_age}` : '';

    const seats = faction.seats || 0;
    const momentum = faction.momentum ?? 0;

    // Use monarch-specific actions if this is the monarch in a monarchy
    const __isMonarchyForActions = isAbsoluteMonarchy(_state.nation);
    const __isMonarchForActions = __isMonarchyForActions && _state.nation?.monarch_faction_id === faction.id;
    const actionsList = __isMonarchForActions ? MONARCH_ACTIONS : LEADER_ACTIONS;

    const actionsHtml = actionsList.map(action => {
        const tagsHtml = action.tags.map(t =>
            `<span class="pa-action-tag" style="color:${TAG_COLORS[t] || 'var(--text-dim)'};">${t}</span>`
        ).join('');

        // Fundraise: show dynamic cost/yield info
        let extraInfo = '';
        let costDisplay = action.cost;
        let costColor = action.costColor;
        let isDisabled = action.locked;
        // Vote of No Confidence — gated on three things:
        //   1. We must be opposition (PM party can't file against itself)
        //   2. No motion already pending in this nation
        //   3. 12-tick per-PM-party cooldown (loaded into _noConfidenceCooldownTicks)
        if (action.id === 'no_confidence') {
            const isMonarchyNation = isAbsoluteMonarchy(_state.nation);
            const isPMParty = !!_administration && _administration.pm_party_id === faction.id;
            if (isMonarchyNation) {
                // Parliament has no authority to remove the Monarch's PM.
                // Dismissal is a royal prerogative — the Monarch replaces
                // the PM via the Appoint Prime Minister royal action above.
                // Defense in depth: fileNoConfidenceMotion also rejects
                // monarchy nations server-side.
                isDisabled = true;
                action.lockReason = 'Parliament cannot remove the Monarch’s Prime Minister. Only the Monarch can dismiss the PM.';
            } else if (isPMParty) {
                isDisabled = true;
                action.lockReason = 'Your party is the Prime Minister — file from another party.';
            } else if (_noConfidencePending) {
                isDisabled = true;
                action.lockReason = 'A motion of no confidence is already pending in Parliament.';
            } else if (_noConfidenceCooldownTicks > 0) {
                isDisabled = true;
                const t = _noConfidenceCooldownTicks;
                action.lockReason = `Cooldown: ${t} tick${t !== 1 ? 's' : ''} remaining before another motion can be filed against this PM party.`;
            } else if (!_administration || !_administration.pm_party_id) {
                isDisabled = true;
                action.lockReason = 'No active Prime Minister to file against.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'form_coalition') {
            // Greyed when an active coalition is already in place
            // (status formed/active/caretaker — i.e. anything fetchActiveCoalition
            // returned non-null). Available whenever there's a vacancy.
            // Parliamentary-only; presidential and semi-presidential
            // systems install via election / presidential nomination.
            const nation = _state.nation;
            const govType = (nation?.government_type || '').toLowerCase();
            const isAM        = govType.includes('absolute monarchy');
            const isPres      = govType.includes('presidential') && !govType.includes('semi');
            const isSemiPres  = isSemiPresidential(nation);
            // Semi-presidential explicitly excluded — its PM comes from
            // a presidential nomination, not coalition negotiation.
            // Leaving it in isParliamentaryLike was the bug that let
            // players click Form Coalition and bounce to the Election
            // subtab's "No coalition formation required" dead-end.
            const isParliamentaryLike = !isAM && !isPres && !isSemiPres
                && (govType.includes('parliamentary') || nation?.hos_election_method === 'hereditary');
            const hasCoalitionRow = !!_activeCoalition;
            const hasSeatedPm = !!_hogActive;
            const coalitionPartyIds = Array.isArray(_activeCoalition?.party_ids) ? _activeCoalition.party_ids : [];
            const inCoalition = coalitionPartyIds.includes(faction.id);
            const noSeats = !faction.seats || faction.seats <= 0;

            if (isSemiPres) {
                isDisabled = true;
                action.lockReason = 'Coalition formation does not apply in semi-presidential systems — the President nominates the Prime Minister directly.';
            } else if (!isParliamentaryLike) {
                isDisabled = true;
                action.lockReason = 'Coalition formation only applies to parliamentary systems.';
            } else if (hasCoalitionRow && hasSeatedPm) {
                // Exception: an emergency_minority government's PM party
                // can use Form Coalition to attempt promotion into a real
                // majority coalition. finalize_government_formation
                // (20260910:127) dissolves the prior formation atomically
                // when the new coalition is finalized, so the server side
                // needs no special-casing.
                const isEmergencyMinority = _activeCoalition?.formation_type === 'emergency_minority';
                if (isEmergencyMinority && inCoalition) {
                    action.lockReason = '';
                } else {
                    isDisabled = true;
                    action.lockReason = isEmergencyMinority
                        ? 'A minority government is in place. Only its PM party can promote it to a coalition.'
                        : 'A government is already in place.';
                }
            } else if (hasCoalitionRow && !hasSeatedPm) {
                isDisabled = true;
                action.lockReason = inCoalition
                    ? 'A coalition exists but the Prime Minister is vacant — use Leadership Challenge instead.'
                    : 'A coalition exists but the Prime Minister is vacant; only coalition members can claim it.';
            } else if (noSeats) {
                isDisabled = true;
                action.lockReason = 'Your party has no parliamentary seats.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'form_minority_government') {
            // Eligibility loaded by loadMinorityGovState during panel init —
            // mirrors the server-side gates in form_minority_government RPC.
            if (!_minorityGate.eligible) {
                isDisabled = true;
                action.lockReason = _minorityGate.lockReason || 'Not currently available.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'leadership_challenge') {
            // Parliamentary (incl. constitutional monarchy) only; coalition
            // member; HOG seat vacant; haven't already claimed this round.
            const nation = _state.nation;
            const govType = (nation?.government_type || '').toLowerCase();
            const isAM   = govType.includes('absolute monarchy');
            const isPres = govType.includes('presidential') && !govType.includes('semi');
            const isSemi = govType.includes('semi-presidential') || govType.includes('semi_presidential');
            const isParliamentary = !isAM && !isPres && !isSemi
                && (govType.includes('parliamentary') || nation?.hos_election_method === 'hereditary');
            const coalitionPartyIds = Array.isArray(_activeCoalition?.party_ids) ? _activeCoalition.party_ids : [];
            const inCoalition = coalitionPartyIds.includes(faction.id);
            const seatVacant = !_hogActive;
            const isOwnFactionPM = !!_hogActive && _hogActive.faction_id === faction.id;
            const noLeader  = !faction.leader_first_name;
            const noSeats   = !faction.seats || faction.seats <= 0;

            if (!isParliamentary) {
                isDisabled = true;
                action.lockReason = 'Only available in parliamentary systems.';
            } else if (isOwnFactionPM) {
                isDisabled = true;
                action.lockReason = 'You are already the Prime Minister.';
            } else if (!inCoalition) {
                isDisabled = true;
                action.lockReason = 'You must be in the governing coalition.';
            } else if (!seatVacant) {
                isDisabled = true;
                action.lockReason = 'A Prime Minister is already serving.';
            } else if (noLeader) {
                isDisabled = true;
                action.lockReason = 'Your party has no leader to install.';
            } else if (noSeats) {
                isDisabled = true;
                action.lockReason = 'Your party has no parliamentary seats.';
            } else if (_leadershipChallengeClaimed) {
                isDisabled = true;
                action.lockReason = 'Challenge submitted — resolves next tick.';
                costDisplay = 'PENDING';
                costColor = 'var(--text-dim)';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'leave_coalition') {
            // Parliamentary-only gate + opposition gate + PM-party gate.
            // Server RPC mirrors these, so a client-side bypass still fails.
            const nation = _state.nation;
            const isParliamentaryPM = hasParliamentaryPM(nation);
            const coalitionPartyIds = Array.isArray(_activeCoalition?.party_ids) ? _activeCoalition.party_ids : [];
            const inActiveCoalition = coalitionPartyIds.includes(faction.id);
            const isPMParty = !!_hogActive && _hogActive.faction_id === faction.id;
            if (!isParliamentaryPM) {
                isDisabled = true;
                action.lockReason = 'Only available in parliamentary systems.';
            } else if (!_activeCoalition) {
                isDisabled = true;
                action.lockReason = 'No active coalition to leave.';
            } else if (!inActiveCoalition || _isOpposition) {
                isDisabled = true;
                action.lockReason = 'You are in opposition.';
            } else if (isPMParty) {
                isDisabled = true;
                action.lockReason = 'Prime Minister’s party cannot leave — resign first.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'disband_party') {
            // Head-of-Government guard mirrors the server RPC. PM / elected
            // President / Monarch must step down first so coalition rows
            // don't dangle with a dead party_id.
            const hog = classifyHeadOfGovernment(faction);
            if (hog.isPM) {
                isDisabled = true;
                action.lockReason = 'You are Prime Minister — resign before disbanding.';
            } else if (hog.isPresident) {
                isDisabled = true;
                action.lockReason = 'You are the sitting President — step down before disbanding.';
            } else if (hog.isMonarchActing) {
                isDisabled = true;
                action.lockReason = 'The reigning monarch cannot disband the royal house.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'fundraise') {
            costDisplay = 'ACTION';
            costColor = '#c8a832';
            extraInfo = `<div style="margin-top:4px;font-family:var(--font-mono);font-size:8px;color:var(--text-dim);display:flex;gap:12px;">
                <span>Themed event · positions you with a voter bloc</span>
                ${_fundraiseUseCount > 0 ? `<span style="color:var(--orange);">Used this tick</span>` : ''}
            </div>`;
            if (_fundraiseUseCount >= 1) {
                isDisabled = true;
                extraInfo += `<div style="margin-top:3px;font-family:var(--font-mono);font-size:9px;color:var(--red);">Already hosted a fundraiser this tick.</div>`;
            }
        }

        const minorityMetaHtml = (action.id === 'form_minority_government' && _minorityGate.metaLine)
            ? `<div class="pa-action-meta-minority" style="margin-top:3px;font-family:var(--font-mono);font-size:9px;color:var(--red);font-weight:600;letter-spacing:0.3px;">${esc(_minorityGate.metaLine)}</div>`
            : '';

        return `
            <div class="pa-action-item ${isDisabled ? 'locked' : ''}" data-action-id="${action.id}">
                <div class="pa-action-top">
                    <div style="display:flex;align-items:center;gap:8px;">
                        <span class="pa-action-name">${esc(action.name)}</span>
                        <div class="pa-action-tags">${tagsHtml}</div>
                    </div>
                    <div class="pa-action-right">
                        <span class="pa-action-cost" style="color:${costColor};">${costDisplay}</span>
                    </div>
                </div>
                ${minorityMetaHtml}
                <div class="pa-action-desc">${esc(action.desc)}</div>
                ${extraInfo}
                ${isDisabled && action.lockReason ? `<div style="margin-top:4px;font-family:var(--font-mono);font-size:7px;color:var(--orange);display:flex;align-items:center;gap:4px;"><span>\u2298</span><span>${esc(action.lockReason)}</span></div>` : ''}
            </div>
        `;
    }).join('');

    return `
        <div class="pa-detail-header">
            <div class="pa-detail-left">
                <div class="pa-detail-avatar" style="color:${role.color};background:${role.color}15;border-color:${role.color}33;">${portrait}</div>
                <div>
                    <div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;">
                        <span style="font-family:var(--font-mono);font-size:20px;font-weight:700;color:${role.color};">${_isMonarch ? (_state.nation?.monarch_title || 'KING').toUpperCase() : role.title}</span>
                        <span class="pa-detail-name">${esc(leaderName)}</span>
                        ${_isMonarchy && _state.nation?.dynasty_name ? `<span style="font-family:var(--font-mono);font-size:12px;color:var(--text-dim);font-style:italic;">House ${esc(_state.nation.dynasty_name)}</span>` : ''}
                        ${renderBlocTag(partyColor)}
                    </div>
                    <div class="pa-detail-meta">${_isMonarch ? esc((_state.nation?.monarch_title || 'King') + ' of ' + (_state.nation?.name || '')) : esc(role.fullTitle) + ' &middot; ' + esc(faction.faction_name)}${age}${(() => {
                        if (_isMonarch) return ' <span style="color:#c8a832;font-weight:700;"> &middot; ' + (_state.nation?.monarch_title || 'MONARCH').toUpperCase() + '</span>';
                        if (_isMonarchy) return ' <span style="color:#8b9a6b;font-weight:700;"> &middot; NOBLE HOUSE</span>';
                        const isPM = _administration?.pm_party_id === faction.id;
                        const isPresident = _state.nation?.hos_election_method === 'elected' && _administration?.president_party_id === faction.id;
                        if (isPM) return ' <span style="color:#5cc55c;font-weight:700;"> &middot; PRIME MINISTER</span>';
                        if (isPresident) return ' <span style="color:#5cc55c;font-weight:700;"> &middot; PRESIDENT</span>';
                        if (!_isOpposition) return ' <span style="color:#8b9a6b;font-weight:700;"> &middot; GOVERNING</span>';
                        return ' <span style="color:#c84;font-weight:700;"> &middot; OPPOSITION</span>';
                    })()}</div>
                </div>
            </div>
        </div>
        ${renderBlocInvitationsPanel(partyColor)}
        ${renderBlocBanner(partyColor)}
        <div class="pa-actions-list">
            ${actionsHtml}
        </div>
        <div class="pa-skill-footer">
            <span style="color:${role.color};font-weight:700;">${role.title}</span> actions are executed by the party leader. Effectiveness depends on party approval and momentum.
        </div>
    `;
}

// ════════════════════════ DEPUTY LEADER PANEL ════════════════════════

const DEPUTY_ACTIONS = [
    {
        id: 'rally',
        name: 'Hold a Rally',
        desc: 'Pick a voter sector and spend party funds on a rally. Roll 1d6 plus a spend bonus — the result raises your popularity in that sector by +0.2 to +1.0. Never backfires.',
        cost: '$50k-$500k',
        costColor: '#8b9a6b',
        tags: ['CAMPAIGN'],
        locked: false,
    },
    {
        id: 'create_bloc',
        name: 'Create Bloc',
        desc: 'Found a pre-coalition alliance with other parties. Pick a name and invite any parties in your nation that aren\'t already in a bloc. Phase 1 is formation only — shared momentum, vote discipline, and coalition binding arrive in later phases.',
        cost: '$100k',
        costColor: '#c8a832',
        moneyCost: 100000,
        tags: ['STRATEGIC', 'ALLIANCE'],
        locked: false,
    },
    {
        id: 'leave_bloc',
        name: 'Leave Bloc',
        desc: 'Exit your current bloc. If you are the bloc leader, leaving dissolves the whole bloc and all pending invitations are withdrawn. Greyed out when you are not in a bloc.',
        cost: '$0',
        costColor: 'var(--text-dim)',
        moneyCost: 0,
        tags: ['ALLIANCE'],
        locked: false,
    },
    {
        id: 'invite_to_bloc',
        name: 'Invite Party to Bloc',
        desc: 'Send a bloc invitation to an additional party. Leader-only. Eligible parties are in your nation, not already in a bloc, and not currently in government.',
        cost: '$0',
        costColor: 'var(--text-dim)',
        moneyCost: 0,
        tags: ['ALLIANCE'],
        locked: false,
    },
    {
        id: 'impeach_president',
        name: 'Impeach President',
        desc: 'File articles of impeachment against the sitting President on charges of Abuse of Power, Gross Incompetence, or Constitutional Violation. Triggers a committee debate, then a floor vote requiring an absolute majority. If the motion passes, a 2/3 supermajority conviction vote follows. Presidential and Semi-Presidential systems only.',
        cost: 'FREE',
        costColor: 'var(--text-dim)',
        moneyCost: 0,
        tags: ['LEGISLATIVE', 'OPPOSITION'],
        locked: false,
    },
];

// Spend tiers mirror the hold_rally() RPC (20270150). The roll, the gain
// and the outcome are computed only in that RPC — the single source of
// truth; these constants exist solely to render the picker pre-commit.
const RALLY_TIERS = [
    { spend: 50000,  bonus: 0, label: '$50k' },
    { spend: 100000, bonus: 1, label: '$100k' },
    { spend: 150000, bonus: 2, label: '$150k' },
    { spend: 250000, bonus: 3, label: '$250k' },
    { spend: 500000, bonus: 4, label: '$500k' },
];

function renderDeputyActionsPanel(role) {
    const faction = _state.faction;
    const partyColor = faction?.color || role.color;

    const actionsHtml = DEPUTY_ACTIONS.map(action => {
        const tagsHtml = action.tags.map(t =>
            `<span class="pa-action-tag" style="color:${TAG_COLORS[t] || 'var(--text-dim)'};">${t}</span>`
        ).join('');

        // Bloc action gating mirrors the server-side checks in create_bloc.
        let isDisabled = action.locked;
        let lockReason = '';
        if (action.id === 'create_bloc') {
            const hog = classifyHeadOfGovernment(faction);
            if (_myBloc) {
                isDisabled = true;
                lockReason = `Already in the ${_myBloc.name} bloc.`;
            } else if (hog.isPM || hog.isPresident || hog.isMonarchActing) {
                isDisabled = true;
                lockReason = 'Head of Government cannot form blocs — you already lead the coalition.';
            } else if ((faction.party_funds || 0) < 100000) {
                isDisabled = true;
                lockReason = 'Needs $100k party funds.';
            }
        } else if (action.id === 'leave_bloc') {
            if (!_myBloc) {
                isDisabled = true;
                lockReason = 'You are not in a bloc.';
            } else if (_myBlocIsLeader) {
                lockReason = `Leaving dissolves ${_myBloc.name} — all members will be removed.`;
            }
        } else if (action.id === 'invite_to_bloc') {
            if (!_myBloc) {
                isDisabled = true;
                lockReason = 'You are not in a bloc.';
            } else if (!_myBlocIsLeader) {
                isDisabled = true;
                lockReason = 'Only the bloc leader can send invitations.';
            }
        } else if (action.id === 'impeach_president') {
            const govType = (_state.nation?.government_type || '').toLowerCase();
            const isPres = govType.includes('presidential');
            const currentTick = Number(_state.shard?.current_tick) || 0;
            const cooldownTick = Number(_state.nation?.impeachment_cooldown_until_tick) || 0;
            if (!isPres) {
                isDisabled = true;
                lockReason = 'Presidential and Semi-Presidential systems only.';
            } else if (!_activePresident) {
                isDisabled = true;
                lockReason = 'No sitting President to impeach.';
            } else if (_activePresident.faction_id === faction.id) {
                isDisabled = true;
                lockReason = "Your party holds the Presidency — you cannot impeach yourself.";
            } else if ((faction.seats || 0) < 1) {
                isDisabled = true;
                lockReason = 'Need at least 1 seat in the legislature.';
            } else if (cooldownTick > currentTick) {
                isDisabled = true;
                lockReason = `Impeachment cooldown: ${cooldownTick - currentTick} tick(s) remaining.`;
            }
        }

        return `
            <div class="pa-action-item ${isDisabled ? 'locked' : ''}" data-action-id="${action.id}">
                <div class="pa-action-top">
                    <div style="display:flex;align-items:center;gap:8px;">
                        <span class="pa-action-name">${esc(action.name)}</span>
                        <div class="pa-action-tags">${tagsHtml}</div>
                    </div>
                    <div class="pa-action-right">
                        <span class="pa-action-cost" style="color:${action.costColor};">${action.cost}</span>
                    </div>
                </div>
                <div class="pa-action-desc">${esc(action.desc)}</div>
                ${lockReason ? `<div style="margin-top:4px;font-family:var(--font-mono);font-size:7px;color:var(--orange);display:flex;align-items:center;gap:4px;"><span>⊘</span><span>${esc(lockReason)}</span></div>` : ''}
            </div>
        `;
    }).join('');

    const sk = getSkillLabel(_deputy.skill);
    return `
        <div class="pa-detail-header">
            <div class="pa-detail-left">
                <div class="pa-detail-avatar" style="color:${role.color};background:${role.color}15;border-color:${role.color}33;">${initials(_deputy.first_name, _deputy.last_name)}</div>
                <div>
                    <div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;">
                        <span style="font-family:var(--font-mono);font-size:20px;font-weight:700;color:${role.color};">${role.title}</span>
                        <span class="pa-detail-name">${esc(_deputy.first_name)} ${esc(_deputy.last_name)}</span>
                        ${renderBlocTag(partyColor)}
                    </div>
                    <div class="pa-detail-meta">${esc(role.fullTitle)} &middot; Age ${_deputy.age} &middot; Skill: <span style="color:${sk.color};font-weight:700;">${_deputy.skill}</span></div>
                </div>
            </div>
        </div>
        ${renderBlocInvitationsPanel(partyColor)}
        ${renderBlocBanner(partyColor)}
        <div class="pa-actions-list" id="pa-actions-panel">${actionsHtml}</div>
    `;
}

// ════════════════════════ HIRE DEPUTY MODAL ════════════════════════

function generateDeputyCandidates(nationName) {
    const names = getNationNames(nationName);
    const firstNames = names.firstNames || [];
    const lastNames = names.lastNames || [];
    if (firstNames.length === 0 || lastNames.length === 0) return [];

    const count = 5 + Math.floor(Math.random() * 3); // 5-7
    const usedNames = new Set();
    const candidates = [];

    for (let i = 0; i < count; i++) {
        let fn, ln, full;
        let attempts = 0;
        do {
            fn = firstNames[Math.floor(Math.random() * firstNames.length)];
            ln = lastNames[Math.floor(Math.random() * lastNames.length)];
            full = fn + ' ' + ln;
            attempts++;
        } while (usedNames.has(full) && attempts < 20);
        usedNames.add(full);

        const skill = 20 + Math.floor(Math.random() * 66); // 20-85
        const age = 28 + Math.floor(Math.random() * 30); // 28-57
        // Cost: $125k (skill 20) to $650k (skill 85), linear
        const t = Math.max(0, (skill - 20)) / 65;
        const cost = Math.round((125000 + t * 525000) / 25000) * 25000; // round to $25k

        candidates.push({ first_name: fn, last_name: ln, age, skill, hire_cost: cost });
    }

    return candidates.sort((a, b) => b.skill - a.skill);
}

async function openHireDeputyModal(root) {
    const overlay = document.getElementById('pa-deputy-modal');
    if (!overlay) return;

    const nationName = _state.nation?.name;
    const candidates = generateDeputyCandidates(nationName);
    let selectedIdx = null;

    function render() {
        const selected = selectedIdx != null ? candidates[selectedIdx] : null;
        const selSkill = selected ? getSkillLabel(selected.skill) : null;

        const listHtml = candidates.map((c, i) => {
            const isSel = selectedIdx === i;
            const sk = getSkillLabel(c.skill);
            return `<div class="pa-hire-row ${isSel ? 'selected' : ''}" data-idx="${i}">
                <div style="width:32px;height:32px;border-radius:50%;background:#8b9a6b15;border:1px solid #8b9a6b33;display:flex;align-items:center;justify-content:center;font-family:var(--font-mono);font-size:10px;font-weight:700;color:#8b9a6b;flex-shrink:0;">${initials(c.first_name, c.last_name)}</div>
                <div style="flex:1;min-width:0;">
                    <div style="font-size:11px;font-weight:600;color:${isSel ? 'var(--text-bright)' : 'var(--text-secondary)'};">${esc(c.first_name)} ${esc(c.last_name)}</div>
                    <div style="display:flex;align-items:center;gap:3px;margin-top:2px;">
                        <div style="flex:1;height:2px;background:var(--border-mid);max-width:60px;"><div style="height:100%;width:${c.skill}%;background:${sk.color};"></div></div>
                        <span style="font-family:var(--font-mono);font-size:8px;color:${sk.color};">${c.skill}</span>
                    </div>
                </div>
                <div style="text-align:right;">
                    <div style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">Age ${c.age}</div>
                    <div style="font-family:var(--font-mono);font-size:8px;color:var(--accent);">$${Math.round(c.hire_cost / 1000)}k</div>
                </div>
            </div>`;
        }).join('');

        let detailHtml;
        if (!selected) {
            detailHtml = `<div style="flex:1;display:flex;align-items:center;justify-content:center;padding:40px;"><div style="text-align:center;">
                <div style="font-family:var(--font-mono);font-size:24px;color:var(--border-mid);margin-bottom:8px;">\u2190</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim);">Select a candidate to review</div>
            </div></div>`;
        } else {
            detailHtml = `
                <div style="padding:16px 20px;">
                    <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">
                        <div style="width:48px;height:48px;border-radius:50%;background:#8b9a6b15;border:1px solid #8b9a6b33;display:flex;align-items:center;justify-content:center;font-family:var(--font-mono);font-size:16px;font-weight:700;color:#8b9a6b;">${initials(selected.first_name, selected.last_name)}</div>
                        <div>
                            <div style="font-size:16px;font-weight:700;color:var(--text-bright);">${esc(selected.first_name)} ${esc(selected.last_name)}</div>
                            <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:1px;">Age ${selected.age} &middot; Deputy Leader Candidate</div>
                        </div>
                    </div>
                    <div style="display:flex;gap:12px;margin-bottom:14px;">
                        <div style="flex:1;padding:8px 10px;background:var(--bg-card);border:1px solid var(--border-main);">
                            <div style="font-family:var(--font-mono);font-size:7px;color:var(--text-dim);letter-spacing:0.06em;margin-bottom:3px;">SKILL</div>
                            <div style="display:flex;align-items:center;gap:6px;">
                                <div style="flex:1;height:3px;background:var(--border-mid);"><div style="height:100%;width:${selected.skill}%;background:${selSkill.color};"></div></div>
                                <span style="font-family:var(--font-mono);font-size:14px;font-weight:700;color:${selSkill.color};">${selected.skill}</span>
                            </div>
                            <div style="font-family:var(--font-mono);font-size:8px;color:${selSkill.color};margin-top:3px;font-weight:700;">${selSkill.label}</div>
                        </div>
                        <div style="flex:1;padding:8px 10px;background:var(--bg-card);border:1px solid var(--border-main);">
                            <div style="font-family:var(--font-mono);font-size:7px;color:var(--text-dim);letter-spacing:0.06em;margin-bottom:3px;">HIRE COST</div>
                            <div style="font-family:var(--font-mono);font-size:14px;font-weight:700;color:var(--accent);">$${Math.round(selected.hire_cost / 1000)}k</div>
                            <div style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);margin-top:3px;">From party funds</div>
                        </div>
                    </div>
                    <div style="padding:8px 10px;background:rgba(139,154,107,0.04);border:1px solid rgba(139,154,107,0.12);">
                        <div style="font-family:var(--font-mono);font-size:7px;color:#8b9a6b;letter-spacing:0.06em;margin-bottom:3px;">ROLE: DEPUTY PARTY LEADER</div>
                        <div style="font-size:9px;color:var(--text-dim);line-height:1.5;">Organizes rallies, boosts momentum, and energizes the party base. Higher skill improves rally outcomes.</div>
                    </div>
                </div>
                <div style="padding:10px 20px;border-top:1px solid var(--border-main);background:var(--bg-card);display:flex;justify-content:flex-end;align-items:center;">
                    <span style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-right:auto;">Cost: <span style="color:var(--accent);font-weight:700;">$${Math.round(selected.hire_cost / 1000)}k</span></span>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-dep-hire-confirm" style="background:#8b9a6b;"${(_state.faction?.party_funds || 0) < selected.hire_cost ? ' disabled title="Not enough funds"' : ''}>Hire ${esc(selected.first_name)}</button>
                </div>
            `;
        }

        overlay.innerHTML = `
            <div style="width:100%;max-width:700px;background:var(--bg-panel);border:1px solid var(--border-mid);box-shadow:0 20px 60px rgba(0,0,0,0.5);display:flex;flex-direction:column;max-height:80vh;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#8b9a6b;"></div>
                        <span class="pa-modal-title">Hire Deputy Leader</span>
                        <span style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);margin-left:8px;">${candidates.length} candidates</span>
                    </div>
                    <button class="pa-modal-close" id="pa-dep-close">&times;</button>
                </div>
                <div style="display:flex;flex:1;min-height:0;overflow:hidden;">
                    <div style="width:240px;border-right:1px solid var(--border-main);overflow-y:auto;" id="pa-dep-list">${listHtml}</div>
                    <div style="flex:1;overflow-y:auto;">${detailHtml}</div>
                </div>
            </div>
        `;

        const close = () => overlay.classList.remove('active');
        document.getElementById('pa-dep-close')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };
        document.getElementById('pa-dep-list')?.addEventListener('click', (e) => {
            const row = e.target.closest('.pa-hire-row');
            if (!row) return;
            selectedIdx = parseInt(row.dataset.idx, 10);
            render();
        });
        document.getElementById('pa-dep-hire-confirm')?.addEventListener('click', async () => {
            if (selectedIdx == null) return;
            const c = candidates[selectedIdx];
            const funds = _state.faction?.party_funds || 0;
            if (funds < c.hire_cost) { alert('Not enough funds.'); return; }

            const btn = document.getElementById('pa-dep-hire-confirm');
            if (btn) { btn.disabled = true; btn.textContent = 'Hiring...'; }

            try {
                const newFunds = funds - c.hire_cost;
                const tick = _state.shard?.current_tick || 0;

                // Insert deputy
                const { data, error } = await _supabase.from('faction_deputies').insert({
                    faction_id: _state.faction.id,
                    first_name: c.first_name,
                    last_name: c.last_name,
                    age: c.age,
                    skill: c.skill,
                    status: 'active',
                    hired_at_tick: tick,
                }).select('*').single();

                if (error) { alert('Failed: ' + error.message); return; }

                // Deduct funds
                await _supabase.from('factions').update({ party_funds: newFunds }).eq('id', _state.faction.id);
                _state.faction.party_funds = newFunds;
                _deputy = data;
                _selectedRole = 'deputy';
                close();
                renderPage(root);
            } catch (err) {
                console.error('[Deputy] Hire error:', err);
            } finally {
                if (btn) { btn.disabled = false; }
            }
        });
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ RALLY MODAL ════════════════════════

async function openRallyModal(root) {
    const overlay = document.getElementById('pa-rally-modal');
    if (!overlay) return;
    if (!_deputy) return;

    const faction = _state.faction;
    let selectedSectorId = null;
    let selectedTier = null;
    let result = null;
    let submitting = false;

    // Distinct messages per RPC gate. Previously no_faction / no_nation /
    // no_shard all mapped to the same generic "Rally is unavailable right
    // now." which made the failures undiagnosable — each now points at
    // the specific gate so a reproduction surfaces the actual cause.
    const REASON_MSG = {
        not_authenticated:         'You are not signed in.',
        no_sector:                 'Pick a sector to rally.',
        invalid_sector:            'That sector is not available.',
        invalid_spend:             'Invalid spend amount.',
        no_faction:                'Rally unavailable: no party faction is linked to this account (or the 20270151 hold_rally migration is not deployed).',
        no_nation:                 'Rally unavailable: your party faction has no assigned nation.',
        no_shard:                  'Rally unavailable: game shard not found — contact admin.',
        already_rallied_this_tick: 'You already held a rally this tick.',
    };

    overlay.classList.add('active');
    overlay.innerHTML = `<div class="pa-modal" style="width:520px;"><div class="pa-modal-body" style="padding:24px;font-family:var(--font-mono);font-size:11px;color:var(--text-dim);">Loading sectors…</div></div>`;

    // Active sectors + this faction's current popularity (stored in tenths).
    const [secRes, popRes] = await Promise.all([
        _supabase.from('sectors').select('id, name').eq('nation_id', _state.nation?.id).eq('is_active', true).order('name'),
        _supabase.from('faction_sector_popularity').select('sector_id, popularity').eq('faction_id', faction.id),
    ]);
    if (secRes.error) console.warn('[Rally] sector load failed:', secRes.error.message);
    if (popRes.error) console.warn('[Rally] popularity load failed:', popRes.error.message);
    const popBySector = new Map((popRes.data || []).map(r => [r.sector_id, Number(r.popularity) || 0]));
    const sectors = (secRes.data || []).map(s => ({ id: s.id, name: s.name, pop: popBySector.get(s.id) || 0 }));

    function render() {
        const funds = faction.party_funds || 0;

        const sectorsHtml = sectors.length === 0
            ? `<div style="padding:10px;font-family:var(--font-mono);font-size:10px;color:#c55;">This nation has no voter sectors yet.</div>`
            : sectors.map(s => {
                const isSel = selectedSectorId === s.id;
                return `<div class="pa-action-item ${isSel ? 'selected' : ''}" data-sector="${s.id}" style="cursor:pointer;${isSel ? 'border-color:#8b9a6b;background:rgba(139,154,107,0.06);' : ''}">
                    <div class="pa-action-top">
                        <span style="font-size:12px;font-weight:700;color:${isSel ? '#8b9a6b' : 'var(--text-bright)'};">${esc(s.name)}</span>
                        <span style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim);">Pop ${(s.pop / 10).toFixed(1)}</span>
                    </div>
                </div>`;
            }).join('');

        const tiersHtml = RALLY_TIERS.map((t, i) => {
            const canAfford = funds >= t.spend;
            const isSel = selectedTier === i;
            return `<div class="pa-action-item ${isSel ? 'selected' : ''} ${!canAfford ? 'locked' : ''}" data-tier="${i}" style="cursor:${canAfford ? 'pointer' : 'not-allowed'};${isSel ? 'border-color:#8b9a6b;background:rgba(139,154,107,0.06);' : ''}">
                <div class="pa-action-top">
                    <span style="font-size:13px;font-weight:700;color:${isSel ? '#8b9a6b' : 'var(--text-bright)'};">${t.label} Investment</span>
                    <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#8b9a6b;">+${t.bonus} Roll Bonus</span>
                </div>
                <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">Roll 1d6 + ${t.bonus} = range ${1 + t.bonus} to ${6 + t.bonus}</div>
            </div>`;
        }).join('');

        let resultHtml = '';
        if (result) {
            resultHtml = `
                <div style="padding:16px;background:#5cc55c08;border:1px solid #5cc55c22;margin-top:12px;">
                    <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#5cc55c;margin-bottom:4px;">${esc(result.outcomeName || 'Rally held')}</div>
                    <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);margin-bottom:6px;">
                        Roll <strong>${result.roll}</strong> + bonus <strong>${result.bonus}</strong> = <strong>${result.total}</strong> &middot; ${esc(result.sectorName || '')}
                    </div>
                    <div style="font-family:var(--font-mono);font-size:16px;font-weight:700;color:#5cc55c;">
                        +${Number(result.popularityGain).toFixed(1)} Popularity
                    </div>
                </div>
            `;
        }

        const submitDisabled = submitting || selectedSectorId == null || selectedTier == null;
        overlay.innerHTML = `
            <div class="pa-modal" style="width:520px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#8b9a6b;"></div>
                        <span class="pa-modal-title">Hold a Rally</span>
                    </div>
                    <button class="pa-modal-close" id="rally-close">&times;</button>
                </div>
                <div style="padding:8px 16px;border-bottom:1px solid var(--border-main);display:flex;align-items:center;gap:8px;">
                    <span style="font-family:var(--font-mono);font-size:9px;color:var(--text-secondary);">Organized by:</span>
                    <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;color:#8b9a6b;">${esc(_deputy.first_name)} ${esc(_deputy.last_name)}</span>
                    <span style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">&middot; Skill ${_deputy.skill}</span>
                </div>
                <div class="pa-modal-body" style="gap:6px;">
                    <div class="pa-modal-step-label">Choose a Sector</div>
                    <div id="rally-sectors">${sectorsHtml}</div>

                    <div class="pa-modal-step-label" style="margin-top:8px;">Choose Investment Level</div>
                    <div id="rally-tiers">${tiersHtml}</div>

                    <div style="margin-top:8px;padding:8px 10px;background:var(--bg-card);border:1px solid var(--border-main);font-family:var(--font-mono);font-size:9px;color:var(--text-dim);line-height:1.6;">
                        <strong>Outcome:</strong> Roll 1d6 + spend bonus &rarr; popularity gain<br>
                        &le;2 = <span style="color:#ca5;">+0.2</span> &middot;
                        3-4 = <span style="color:#8b9a6b;">+0.4</span> &middot;
                        5-6 = <span style="color:#8b9a6b;">+0.6</span> &middot;
                        7-8 = <span style="color:#5cc55c;">+0.8</span> &middot;
                        &ge;9 = <span style="color:#5cc55c;">+1.0</span>
                    </div>

                    ${resultHtml}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="rally-cancel">${result ? 'Close' : 'Cancel'}</button>
                    ${!result ? `<button class="pa-modal-btn pa-modal-btn--submit" id="rally-submit" style="background:#8b9a6b;" ${submitDisabled ? 'disabled' : ''}>${submitting ? 'Rolling…' : 'Hold Rally'}</button>` : ''}
                </div>
            </div>
        `;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('rally-close')?.addEventListener('click', close);
        document.getElementById('rally-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        document.getElementById('rally-sectors')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-sector]');
            if (!item) return;
            selectedSectorId = item.dataset.sector;
            render();
        });

        document.getElementById('rally-tiers')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-tier]');
            if (!item || item.classList.contains('locked')) return;
            selectedTier = parseInt(item.dataset.tier, 10);
            render();
        });

        document.getElementById('rally-submit')?.addEventListener('click', async () => {
            if (submitting || result || selectedSectorId == null || selectedTier == null) return;
            const tier = RALLY_TIERS[selectedTier];
            submitting = true;
            render();
            try {
                const { data, error } = await _supabase.rpc('hold_rally', {
                    p_sector_id: selectedSectorId,
                    p_spend: tier.spend,
                });
                if (error) {
                    console.error('[Rally] hold_rally RPC failed:', error.message);
                    submitting = false;
                    alert('Rally failed. Please try again.');
                    render();
                    return;
                }
                if (!data || data.success !== true) {
                    submitting = false;
                    const msg = data?.reason === 'insufficient_funds' && data?.need != null
                        ? `Not enough party funds. Need $${Number(data.need).toLocaleString()}.`
                        : (REASON_MSG[data?.reason] || 'Rally failed.');
                    alert(msg);
                    render();
                    return;
                }
                if (data.newFunds != null) _state.faction.party_funds = data.newFunds;
                sessionStorage.removeItem('nationhood_state'); // bust stale cache
                submitting = false;
                result = data;
                render();
            } catch (err) {
                console.error('[Rally] error:', err);
                submitting = false;
                alert('Rally failed.');
                render();
            }
        });
    }

    render();
}

// ════════════════════════ INVEST IN NATIONAL SPORTS CULTURE ════════════════════════

async function openVolaInvestmentModal(root, faction) {
    const overlay = document.getElementById('pa-vola-invest-modal');
    if (!overlay) return;

    // Refresh discretionary balance before showing — funding bills can
    // top it up between renders, so re-fetch instead of trusting a
    // cached descriptor.
    const { data: mRow } = await _supabase.from('ministries')
        .select('id, party_id, discretionary_balance')
        .eq('nation_id', _state.nation.id)
        .eq('ministry_key', 'sports')
        .eq('is_active', true)
        .maybeSingle();
    const balance = Number(mRow?.discretionary_balance) || 0;

    let submitting = false;
    let result = null; // populated after success: { level, gain, cost, newCulture, newBalance }

    function render() {
        const tiers = ['low', 'moderate', 'high'].map(k => ({
            key: k,
            cfg: VOLA_INVESTMENT_LEVELS[k],
        }));
        const tiersHtml = tiers.map(t => {
            const canAfford = balance >= t.cfg.cost;
            const costLabel = '$' + (t.cfg.cost / 1_000_000);
            return `<div class="pa-action-item ${!canAfford || submitting ? 'locked' : ''}" data-tier="${t.key}" style="cursor:${canAfford && !submitting ? 'pointer' : 'not-allowed'};">
                <div class="pa-action-top">
                    <span style="font-size:13px;font-weight:700;color:var(--text-bright);">${t.cfg.label}</span>
                    <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;">+${t.cfg.gain} National Sports Culture</span>
                </div>
                <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">Cost: ${costLabel} from discretionary budget</div>
                ${!canAfford ? `<div style="font-family:var(--font-mono);font-size:8px;color:var(--red);margin-top:4px;">Insufficient budget — need ${costLabel}</div>` : ''}
            </div>`;
        }).join('');

        const resultHtml = result ? `
            <div style="padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.22);margin-top:12px;">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;margin-bottom:4px;">Investment applied</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);">
                    +${result.gain} National Sports Culture · new total <strong>${Number(result.newCulture).toFixed(1)}</strong><br>
                    $${(result.cost / 1_000_000).toFixed(0)} deducted · remaining discretionary <strong>${fmtDiscretionaryBalance(result.newBalance)}</strong>
                </div>
            </div>
        ` : '';

        overlay.innerHTML = `
            <div class="pa-modal" style="width:480px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Invest in National Sports Culture</span>
                    </div>
                    <button class="pa-modal-close" id="vola-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    Fund local Vola leagues, training academies, and marketing. Pulls from the
                    Sports Ministry's discretionary budget — <strong style="color:${balance > 0 ? 'var(--green)' : 'var(--red)'};">${fmtDiscretionaryBalance(balance)}</strong> available.
                    Top it up via a funding article on a passed bill. 1 tick cooldown.
                </div>
                <div class="pa-modal-body" style="gap:6px;">
                    <div class="pa-modal-step-label">Choose Investment Level</div>
                    <div id="vola-tiers">${tiersHtml}</div>
                    ${resultHtml}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="vola-cancel">${result ? 'Close' : 'Cancel'}</button>
                </div>
            </div>
        `;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('vola-close')?.addEventListener('click', close);
        document.getElementById('vola-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        document.getElementById('vola-tiers')?.addEventListener('click', async (e) => {
            const item = e.target.closest('[data-tier]');
            if (!item || item.classList.contains('locked')) return;
            if (submitting || result) return;
            const level = item.dataset.tier;
            submitting = true;
            render();
            try {
                const { data: shard } = await _supabase.from('shard').select('current_tick').eq('name', 'Alpha Shard').single();
                const currentTick = Number(shard?.current_tick) || 0;
                const r = await investInVolaCulture(_supabase, _state.nation, faction.id, level, currentTick);
                if (r?.success) {
                    result = r;
                } else {
                    alert('Could not invest: ' + (r?.reason || 'unknown error'));
                }
            } catch (err) {
                alert('Investment failed: ' + (err?.message || err));
            } finally {
                submitting = false;
                render();
            }
        });
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ DEBT PAYMENT (Finance) ════════════════════════
// Pulls cash from the Finance Ministry's discretionary balance and applies
// it to nation.debt. $2 flat transaction fee + variable principal. Server
// (pay_down_national_debt RPC) re-validates everything; this modal is just
// the data-entry surface.

async function openDebtPaymentModal(root, faction) {
    const overlay = document.getElementById('pa-debt-payment-modal');
    if (!overlay) return;

    // Raw dollars → unified $1 = $1M abstract scale, used for display
    // and bounds. Math.floor (not round) so we never promise a payment
    // the discretionary balance can't actually cover.
    const toAbstract = (raw) => Math.floor((Number(raw) || 0) / 1_000_000);
    const FEE_ABSTRACT = 2;

    // Re-fetch ministry + nation rows so the modal reflects current
    // discretionary balance and debt rather than a cached descriptor —
    // funding bills / tick effects can move both between renders.
    let loadError = '';
    const [mResp, nResp] = await Promise.all([
        _supabase.from('ministries')
            .select('id, party_id, discretionary_balance')
            .eq('nation_id', _state.nation.id)
            .eq('ministry_key', 'finance')
            .eq('is_active', true)
            .maybeSingle(),
        _supabase.from('nations')
            .select('debt')
            .eq('id', _state.nation.id)
            .maybeSingle(),
    ]);
    if (mResp.error || nResp.error) {
        loadError = (mResp.error || nResp.error).message || 'Could not load ministry / nation data.';
    }
    const balanceAbstract = toAbstract(mResp.data?.discretionary_balance);
    const debtAbstract    = toAbstract(nResp.data?.debt);
    const maxPayment = Math.max(0, balanceAbstract - FEE_ABSTRACT);

    let submitting = false;
    let result = null;    // populated on success: { payment, fee, newBalance, newDebt }
    let inputValue = '';  // controlled input as string so empty / partial entries render cleanly
    let errorMsg = loadError;

    function parseInput() {
        const n = parseInt(inputValue, 10);
        if (!Number.isFinite(n)) return null;
        return n;
    }
    function isValid() {
        const n = parseInput();
        return n != null && n >= 1 && n <= maxPayment;
    }

    function render() {
        const payment = parseInput();
        const totalCost = (payment != null && payment >= 1) ? (payment + FEE_ABSTRACT) : null;
        const projectedBalance = totalCost != null ? balanceAbstract - totalCost : balanceAbstract;
        const projectedDebt    = (payment != null && payment >= 1) ? Math.max(0, debtAbstract - payment) : debtAbstract;
        const valid = isValid();

        const resultHtml = result ? `
            <div style="padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.22);margin-top:12px;">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;margin-bottom:4px;">Payment applied</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);">
                    $${result.payment} paid against debt · $${result.fee} transaction fee<br>
                    Discretionary: <strong>$${toAbstract(result.newBalance)}</strong> · Debt: <strong>$${toAbstract(result.newDebt)}</strong>
                </div>
            </div>
        ` : '';

        const errorHtml = errorMsg ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--red);margin-top:6px;">${esc(errorMsg)}</div>` : '';

        overlay.innerHTML = `
            <div class="pa-modal" style="width:480px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Debt Payment</span>
                    </div>
                    <button class="pa-modal-close" id="pa-dp-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    Pay down the national debt from the Finance Ministry's discretionary budget.
                    $${FEE_ABSTRACT} transaction fee + the principal you choose. 1 tick cooldown.
                </div>
                <div class="pa-modal-body" style="gap:10px;">
                    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
                        <div>
                            <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">DISCRETIONARY</div>
                            <div style="font-family:var(--font-mono);font-size:15px;font-weight:700;color:${balanceAbstract > 0 ? 'var(--green)' : 'var(--red)'};">$${balanceAbstract}</div>
                        </div>
                        <div>
                            <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">NATIONAL DEBT</div>
                            <div style="font-family:var(--font-mono);font-size:15px;font-weight:700;color:var(--text-bright);">$${debtAbstract}</div>
                        </div>
                    </div>

                    <div class="pa-modal-step-label">Payment Amount (whole dollars, 1 – ${maxPayment})</div>
                    <input id="pa-dp-input" class="pa-modal-input" type="number" min="1" max="${maxPayment}" step="1" placeholder="0" value="${esc(inputValue)}" ${result || submitting ? 'disabled' : ''} style="font-family:var(--font-mono);font-size:14px;">

                    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding-top:4px;">
                        <div>
                            <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">AFTER · DISCRETIONARY</div>
                            <div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:${projectedBalance >= 0 ? 'var(--text-bright)' : 'var(--red)'};">$${projectedBalance}</div>
                        </div>
                        <div>
                            <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">AFTER · DEBT</div>
                            <div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:var(--text-bright);">$${projectedDebt}</div>
                        </div>
                    </div>
                    ${errorHtml}
                    ${resultHtml}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-dp-cancel">${result ? 'Close' : 'Cancel'}</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-dp-pay" ${!valid || submitting || result || loadError ? 'disabled' : ''}>${submitting ? 'Paying…' : 'Pay'}</button>
                </div>
            </div>
        `;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('pa-dp-close')?.addEventListener('click', close);
        document.getElementById('pa-dp-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        const input = document.getElementById('pa-dp-input');
        if (input) {
            input.addEventListener('input', (e) => {
                // Strip anything that isn't an integer so paste-from-spreadsheet
                // junk doesn't break the parser.
                inputValue = (e.target.value || '').replace(/[^0-9]/g, '');
                // Reset to loadError (not empty) so a persistent fetch failure
                // stays visible across keystrokes. Validation errors clear naturally.
                errorMsg = loadError;
                render();
                const refocus = document.getElementById('pa-dp-input');
                if (refocus) {
                    refocus.focus();
                    refocus.setSelectionRange(refocus.value.length, refocus.value.length);
                }
            });
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && isValid() && !submitting && !result && !loadError) {
                    e.preventDefault();
                    submit();
                }
            });
        }

        document.getElementById('pa-dp-pay')?.addEventListener('click', submit);
    }

    async function submit() {
        if (submitting || result || loadError) return;
        const payment = parseInput();
        if (!isValid()) {
            errorMsg = `Enter an integer between 1 and ${maxPayment}.`;
            render();
            return;
        }
        submitting = true;
        errorMsg = '';
        render();
        try {
            const { data, error } = await _supabase.rpc('pay_down_national_debt', { p_payment: payment });
            if (error) {
                errorMsg = error.message || 'Payment failed.';
            } else if (!data?.success) {
                errorMsg = humanizeReason(data?.reason) || 'Payment failed.';
            } else {
                result = data;
            }
        } catch (e) {
            errorMsg = e?.message || 'Network error.';
        } finally {
            submitting = false;
            render();
        }
    }

    function humanizeReason(reason) {
        switch (reason) {
            case 'invalid_payment':       return 'Enter an integer of at least $1.';
            case 'not_minister':          return 'Only the Finance Minister can fire this action.';
            case 'no_shard':              return 'Shard not initialized.';
            case 'cooldown':              return 'Already used this tick. Try again next tick.';
            case 'insufficient_balance':  return 'Not enough discretionary budget for fee + payment.';
            case 'no_debt':               return 'There is no national debt to pay down.';
            default:                      return reason || '';
        }
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ PRESS CLAIM (Foreign Ministry) ════════════════════════
// Starter modifiers for a fresh territorial dispute, built from the engine's
// MODIFIERS table (one source) so the issue ticks identically to one spawned by
// admin or the auto-spawner. Passed to the press_claim RPC, which inserts them.
function buildTerritorialStarterModifiers() {
    const keys = ISSUE_TYPES.territorial_ownership?.starter_modifiers || [];
    return keys.map(key => {
        const def = MODIFIERS[key] || {};
        return {
            modifier_key: key,
            category: def.category || 'structural',
            applies_to: def.applies_to || 'both',
            stat_effects: def.stat_effects || [],
            duration_remaining: def.duration ?? null,
            is_periodic: def.is_periodic || false,
            periodic_interval: def.periodic_interval ?? null,
            periodic_duration: def.periodic_duration ?? null,
        };
    });
}

async function openPressClaimModal(root, faction) {
    const overlay = document.getElementById('pa-press-claim-modal');
    if (!overlay) return;
    const myNationId = _state?.nation?.id;

    // Load the FM discretionary balance + bordering (proximity 0) nations, minus
    // any we already have an active territorial dispute with. discretionary_balance
    // is raw dollars; the UI shows the $1 = $1M abstract scale.
    const COST = 3;                     // displayed cost ($3)
    const COST_RAW = 3_000_000;         // affordability threshold (raw dollars)
    const toAbstract = (raw) => Math.floor((Number(raw) || 0) / 1_000_000);
    let loadError = '';
    let balance = 0;
    let neighbours = [];   // { id, name, disputed }
    try {
        const [mResp, relResp, issResp] = await Promise.all([
            _supabase.from('ministries').select('discretionary_balance')
                .eq('nation_id', myNationId).eq('ministry_key', 'foreign').eq('is_active', true).maybeSingle(),
            _supabase.from('diplomatic_relations').select('nation_a_id, nation_b_id, proximity')
                .or(`nation_a_id.eq.${myNationId},nation_b_id.eq.${myNationId}`).eq('proximity', 0),
            _supabase.from('bilateral_issues').select('nation_a_id, nation_b_id')
                .eq('issue_type', 'territorial_ownership').in('status', ['active', 'partial'])
                .or(`nation_a_id.eq.${myNationId},nation_b_id.eq.${myNationId}`),
        ]);
        if (mResp.error || relResp.error) throw (mResp.error || relResp.error);
        balance = Number(mResp.data?.discretionary_balance || 0);
        const ids = (relResp.data || []).map(r => r.nation_a_id === myNationId ? r.nation_b_id : r.nation_a_id);
        const disputed = new Set((issResp.data || []).map(i => i.nation_a_id === myNationId ? i.nation_b_id : i.nation_a_id));
        if (ids.length) {
            const { data: nats } = await _supabase.from('nations').select('id, name').in('id', ids);
            neighbours = (nats || []).map(n => ({ id: n.id, name: n.name, disputed: disputed.has(n.id) }))
                .sort((a, b) => String(a.name).localeCompare(String(b.name)));
        }
    } catch (e) {
        loadError = e?.message || 'Could not load bordering nations.';
    }

    let submitting = false;
    let result = null;   // { issue_id, stake_resource, stake_quantity }
    let errorMsg = loadError;
    let selectedId = neighbours.find(n => !n.disputed)?.id || '';
    const RESOURCE_LABEL = { farmland: 'Farmland', minerals: 'Minerals', energy: 'Energy' };

    function render() {
        const affordable = balance >= COST_RAW;
        const hasTarget = !!selectedId;

        const optionsHtml = neighbours.map(n =>
            `<option value="${esc(n.id)}"${n.id === selectedId ? ' selected' : ''}${n.disputed ? ' disabled' : ''}>${esc(n.name)}${n.disputed ? ' — dispute active' : ''}</option>`
        ).join('');

        const resultHtml = result ? `
            <div style="padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.22);margin-top:12px;">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;margin-bottom:4px;">Claim pressed</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);">
                    A territorial dispute has opened. What's at stake: <strong>${result.stake_quantity} ${esc(RESOURCE_LABEL[result.stake_resource] || result.stake_resource || '')}</strong>.<br>
                    Track it under World &rarr; Diplomacy &rarr; Issues, or the Conflicts board.
                </div>
            </div>` : '';
        const errorHtml = errorMsg ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--red);margin-top:6px;">${esc(errorMsg)}</div>` : '';

        const bodyHtml = (neighbours.length === 0 && !loadError)
            ? `<div style="font-family:var(--font-mono);font-size:11px;color:var(--text-secondary);">No bordering nations to press a claim against. Territorial claims can only be pressed against a nation you share a border with.</div>`
            : `
                <div style="display:flex;justify-content:space-between;align-items:center;">
                    <div>
                        <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">DISCRETIONARY</div>
                        <div style="font-family:var(--font-mono);font-size:15px;font-weight:700;color:${affordable ? 'var(--green)' : 'var(--red)'};">$${toAbstract(balance)}</div>
                    </div>
                    <div style="text-align:right;">
                        <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">COST</div>
                        <div style="font-family:var(--font-mono);font-size:15px;font-weight:700;color:#c8a832;">$${COST}</div>
                    </div>
                </div>
                <div class="pa-modal-step-label">Select a Nation</div>
                <select id="pa-pc-nation" class="pa-modal-input" ${result || submitting ? 'disabled' : ''} style="font-family:var(--font-ui);font-size:12px;">${optionsHtml}</select>
                <div class="pa-modal-step-label">Select a Claim</div>
                <select class="pa-modal-input" disabled style="font-family:var(--font-ui);font-size:12px;"><option>Territorial Dispute</option></select>
                ${errorHtml}
                ${resultHtml}
            `;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:460px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Press Claim</span>
                    </div>
                    <button class="pa-modal-close" id="pa-pc-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    Your nation will press a claim that is important to it, though this may bring you into active armed conflict if tensions escalate too high. Costs $${COST} from the Foreign Ministry discretionary budget.
                </div>
                <div class="pa-modal-body" style="gap:10px;">${bodyHtml}</div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-pc-cancel">${result ? 'Close' : 'Cancel'}</button>
                    ${result ? '' : `<button class="pa-modal-btn pa-modal-btn--submit" id="pa-pc-press" ${(!hasTarget || !affordable || submitting || loadError || neighbours.length === 0) ? 'disabled' : ''}>${submitting ? 'Pressing…' : 'Press'}</button>`}
                </div>
            </div>`;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('pa-pc-close')?.addEventListener('click', close);
        document.getElementById('pa-pc-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };
        const sel = document.getElementById('pa-pc-nation');
        if (sel) sel.addEventListener('change', (e) => { selectedId = e.target.value; });
        document.getElementById('pa-pc-press')?.addEventListener('click', submit);
    }

    async function submit() {
        if (submitting || result || !selectedId) return;
        submitting = true; errorMsg = ''; render();
        try {
            const { data, error } = await _supabase.rpc('press_claim', {
                p_target_nation_id: selectedId,
                p_modifiers: buildTerritorialStarterModifiers(),
                p_region_name: null,
                p_stake_resource: null,
                p_stake_quantity: null,
            });
            if (error) errorMsg = error.message || 'Could not press the claim.';
            else if (!data?.ok) errorMsg = data?.message || 'Could not press the claim.';
            else {
                result = data;
                // World news. Awaited to match the codebase's event_log insert
                // pattern (elections.js, impeachment.js, budget.js, …); the
                // helper swallows its own errors so this can't break the flow.
                const myName = _state?.nation?.name || 'A nation';
                const targetName = neighbours.find(n => n.id === selectedId)?.name || 'another nation';
                await broadcastWorldEvent(_supabase, {
                    eventName: 'Territorial Claim Pressed',
                    triggerKey: 'dispute_press_claim',
                    description: `${myName} has pressed a territorial claim against ${targetName}.`,
                    category: 'diplomacy',
                    currentTick: _state?.shard?.current_tick,
                });
            }
        } catch (e) {
            errorMsg = e?.message || 'Network error.';
        } finally {
            submitting = false; render();
        }
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ DECLARE WAR (Prime Minister / President) ════════════════════════
// Pick a bordering nation + a casus belli, then file a declare_war bill
// (supermajority). Press-claim path needs a pressed claim at tension 10;
// Our Honor needs none but is paid on filing. Server (declare_war RPC) is the
// authority — this modal just scopes the choices to what's plausibly valid.
// Request Ceasefire — a belligerent's Foreign Minister sues for white peace. The
// enemy's head of government accepts/rejects in their War Room (respond_ceasefire).
async function openRequestCeasefireModal(root, faction) {
    const overlay = document.getElementById('pa-ceasefire-modal');
    if (!overlay) return;
    const myNationId = _state?.nation?.id;

    let loadError = '';
    let enemies = [];   // { id, name, offered }
    try {
        const { data: rels, error: relErr } = await _supabase
            .from('diplomatic_relations')
            .select('nation_a_id, nation_b_id, relation_type, ceasefire_offer_nation_id')
            .or(`nation_a_id.eq.${myNationId},nation_b_id.eq.${myNationId}`).eq('relation_type', 'war');
        if (relErr) throw relErr;
        const ids = (rels || []).map(r => r.nation_a_id === myNationId ? r.nation_b_id : r.nation_a_id);
        const offeredByMe = new Set((rels || [])
            .filter(r => r.ceasefire_offer_nation_id === myNationId)
            .map(r => r.nation_a_id === myNationId ? r.nation_b_id : r.nation_a_id));
        if (ids.length) {
            const { data: nats } = await _supabase.from('nations').select('id, name').in('id', ids);
            enemies = (nats || []).map(n => ({ id: n.id, name: n.name, offered: offeredByMe.has(n.id) }))
                .sort((a, b) => String(a.name).localeCompare(String(b.name)));
        }
    } catch (e) {
        loadError = e?.message || 'Could not load your wars.';
    }

    let submitting = false;
    let result = null;
    let errorMsg = loadError;
    let selectedId = enemies[0]?.id || '';
    const selected = () => enemies.find(n => n.id === selectedId) || null;

    function render() {
        const sel = selected();
        const canSubmit = !!sel && !submitting && !result;

        const optionsHtml = enemies.map(n =>
            `<option value="${esc(n.id)}"${n.id === selectedId ? ' selected' : ''}>${esc(n.name)}${n.offered ? ' — already requested' : ''}</option>`
        ).join('');

        const resultHtml = result ? `
            <div style="padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.25);margin-top:12px;">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:var(--amber,#c8a832);margin-bottom:4px;">Ceasefire requested</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);line-height:1.5;">
                    The enemy's head of government must accept it in their War Room. Until they do, the war continues.
                </div>
            </div>` : '';
        const errorHtml = errorMsg ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--red);margin-top:6px;">${esc(errorMsg)}</div>` : '';

        const bodyHtml = (enemies.length === 0 && !loadError)
            ? `<div style="font-family:var(--font-mono);font-size:11px;color:var(--text-secondary);">You are not at war with anyone. A ceasefire can only be requested during an active war.</div>`
            : `
                <div class="pa-modal-step-label">Select a War</div>
                <select id="pa-cf-nation" class="pa-modal-input" ${result || submitting ? 'disabled' : ''} style="font-family:var(--font-ui);font-size:12px;">${optionsHtml}</select>
                <div style="margin-top:10px;padding:10px 12px;border:1px solid rgba(200,168,50,0.3);border-radius:3px;background:rgba(200,168,50,0.06);font-family:var(--font-mono);font-size:9px;color:var(--text-dim);line-height:1.5;">
                    <span style="color:var(--amber,#c8a832);font-weight:700;">White peace.</span> The fighting stops and the front line <strong>freezes where it stands</strong> — each side keeps the ground it currently holds, and the dispute ends. The other nation's head of government must accept — you cannot end the war alone.
                </div>
                ${errorHtml}
                ${resultHtml}
            `;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:460px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:var(--amber,#c8a832);"></div>
                        <span class="pa-modal-title">Request Ceasefire</span>
                    </div>
                    <button class="pa-modal-close" id="pa-cf-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    Sue for peace. The enemy's head of government decides whether to accept.
                </div>
                <div class="pa-modal-body" style="gap:10px;">${bodyHtml}</div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-cf-cancel">${result ? 'Close' : 'Cancel'}</button>
                    ${result ? '' : `<button class="pa-modal-btn pa-modal-btn--submit" id="pa-cf-send" ${canSubmit ? '' : 'disabled'}>${submitting ? 'Requesting…' : 'Request Ceasefire'}</button>`}
                </div>
            </div>`;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('pa-cf-close')?.addEventListener('click', close);
        document.getElementById('pa-cf-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };
        const natSel = document.getElementById('pa-cf-nation');
        if (natSel) natSel.addEventListener('change', (e) => { selectedId = e.target.value; render(); });
        document.getElementById('pa-cf-send')?.addEventListener('click', cfSubmit);
    }

    async function cfSubmit() {
        const sel = selected();
        if (submitting || result || !sel) return;
        submitting = true; errorMsg = ''; render();
        try {
            const { data, error } = await _supabase.rpc('request_ceasefire', { p_target_nation_id: selectedId });
            if (error) errorMsg = error.message || 'Could not request ceasefire.';
            else if (!data?.ok) errorMsg = data?.message || 'Could not request ceasefire.';
            else result = data;
        } catch (e) {
            errorMsg = e?.message || 'Network error.';
        } finally {
            submitting = false; render();
        }
    }

    overlay.classList.add('active');
    render();
}

async function openDeclareWarModal(root, faction) {
    const overlay = document.getElementById('pa-declare-war-modal');
    if (!overlay) return;
    const myNationId = _state?.nation?.id;

    let loadError = '';
    let neighbours = [];          // { id, name, atWar }
    try {
        const { data: rels, error: relErr } = await _supabase
            .from('diplomatic_relations').select('nation_a_id, nation_b_id, relation_type')
            .or(`nation_a_id.eq.${myNationId},nation_b_id.eq.${myNationId}`).eq('proximity', 0);
        if (relErr) throw relErr;
        const ids = (rels || []).map(r => r.nation_a_id === myNationId ? r.nation_b_id : r.nation_a_id);
        const atWar = new Set((rels || []).filter(r => r.relation_type === 'war').map(r => r.nation_a_id === myNationId ? r.nation_b_id : r.nation_a_id));
        if (ids.length) {
            const { data: nats } = await _supabase.from('nations').select('id, name').in('id', ids);
            neighbours = (nats || []).map(n => ({ id: n.id, name: n.name, atWar: atWar.has(n.id) }))
                .sort((a, b) => String(a.name).localeCompare(String(b.name)));
        }
    } catch (e) {
        loadError = e?.message || 'Could not load bordering nations.';
    }

    let submitting = false;
    let result = null;
    let errorMsg = loadError;
    let selectedId = neighbours.find(n => !n.atWar)?.id || '';
    const selected = () => neighbours.find(n => n.id === selectedId) || null;

    function render() {
        const sel = selected();
        const canSubmit = !!sel && !sel.atWar && !submitting && !result;

        const optionsHtml = neighbours.map(n =>
            `<option value="${esc(n.id)}"${n.id === selectedId ? ' selected' : ''}${n.atWar ? ' disabled' : ''}>${esc(n.name)}${n.atWar ? ' — already at war' : ''}</option>`
        ).join('');

        const resultHtml = result ? `
            <div style="padding:12px;background:rgba(200,60,60,0.08);border:1px solid rgba(200,60,60,0.22);margin-top:12px;">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:var(--red);margin-bottom:4px;">Declaration filed</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);line-height:1.5;">
                    The motion is now before parliament and requires a <strong>supermajority</strong> to pass. If it carries, the two nations enter a state of war and the fronts between them activate.
                </div>
            </div>` : '';
        const errorHtml = errorMsg ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--red);margin-top:6px;">${esc(errorMsg)}</div>` : '';

        const bodyHtml = (neighbours.length === 0 && !loadError)
            ? `<div style="font-family:var(--font-mono);font-size:11px;color:var(--text-secondary);">No bordering nations to declare war on. War can only be declared against a nation you share a border with.</div>`
            : `
                <div class="pa-modal-step-label">Select a Nation</div>
                <select id="pa-dw-nation" class="pa-modal-input" ${result || submitting ? 'disabled' : ''} style="font-family:var(--font-ui);font-size:12px;">${optionsHtml}</select>
                <div style="margin-top:10px;padding:10px 12px;border:1px solid rgba(200,60,60,0.3);border-radius:3px;background:rgba(200,60,60,0.06);font-family:var(--font-mono);font-size:9px;color:var(--text-dim);line-height:1.5;">
                    <span style="color:var(--red);font-weight:700;">Casus Belli — Our Honor.</span> An unprovoked war, paid on filing: <strong>−10 Public Approval</strong> and <strong>−3.0 popularity</strong> with your party in every sector. (Territorial wars start automatically when a dispute hits maximum tension — no declaration needed.)
                </div>
                ${errorHtml}
                ${resultHtml}
            `;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:460px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:var(--red);"></div>
                        <span class="pa-modal-title">Declare War</span>
                    </div>
                    <button class="pa-modal-close" id="pa-dw-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    File a declaration of war before parliament. Passage requires a supermajority. Until it passes, your nations are not at war.
                </div>
                <div class="pa-modal-body" style="gap:10px;">${bodyHtml}</div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-dw-cancel">${result ? 'Close' : 'Cancel'}</button>
                    ${result ? '' : `<button class="pa-modal-btn pa-modal-btn--submit" id="pa-dw-file" ${canSubmit ? '' : 'disabled'}>${submitting ? 'Filing…' : 'Declare'}</button>`}
                </div>
            </div>`;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('pa-dw-close')?.addEventListener('click', close);
        document.getElementById('pa-dw-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };
        const natSel = document.getElementById('pa-dw-nation');
        if (natSel) natSel.addEventListener('change', (e) => { selectedId = e.target.value; render(); });
        document.getElementById('pa-dw-file')?.addEventListener('click', submit);
    }

    async function submit() {
        const sel = selected();
        if (submitting || result || !sel || sel.atWar) return;
        submitting = true; errorMsg = ''; render();
        try {
            const { data, error } = await _supabase.rpc('declare_war', {
                p_target_nation_id: selectedId,
            });
            if (error) errorMsg = error.message || 'Could not declare war.';
            else if (!data?.success) errorMsg = data?.error || 'Could not declare war.';
            else result = data;
        } catch (e) {
            errorMsg = e?.message || 'Network error.';
        } finally {
            submitting = false; render();
        }
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ ALLOCATE FUNDS (Minister of Defense) ════════════════════════

async function openAllocateFundsModal(root) {
    const overlay = document.getElementById('pa-allocate-funds-modal');
    if (!overlay) return;

    // Raw dollars → unified $1 = $1M abstract scale (same convention as
    // the debt modal / fmtDiscretionaryBalance / allocate_defense_funds).
    const toAbstract = (raw) => Math.floor((Number(raw) || 0) / 1_000_000);
    const nationName = _state?.nation?.name || 'the Nation';

    // Fresh ministry + army-faction rows so the modal reflects current
    // balances rather than a cached descriptor.
    let loadError = '';
    const [mResp, aResp] = await Promise.all([
        _supabase.from('ministries')
            .select('discretionary_balance')
            .eq('nation_id', _state.nation.id)
            .eq('ministry_key', 'defense')
            .eq('is_active', true)
            .maybeSingle(),
        _supabase.from('factions')
            .select('party_funds')
            .eq('nation_id', _state.nation.id)
            .eq('faction_type', 'military')
            .eq('branch', 'army')
            .is('abandoned_at', null)
            .or('is_banned.is.null,is_banned.eq.false')
            .order('created_at', { ascending: true })
            .limit(1)
            .maybeSingle(),
    ]);
    if (mResp.error) loadError = mResp.error.message || 'Could not load ministry data.';
    // aResp "no rows" is a valid state (no army established), not an error;
    // only a real query failure counts.
    if (aResp.error && aResp.error.code !== 'PGRST116') {
        loadError = loadError || aResp.error.message || 'Could not load army faction.';
    }

    const balanceAbstract = toAbstract(mResp.data?.discretionary_balance);
    const armyRow         = aResp.data || null;
    const armyExists      = !!armyRow;
    const armyBudget      = toAbstract(armyRow?.party_funds);
    const maxAlloc        = Math.max(0, balanceAbstract);

    let submitting = false;
    let result = null;     // { allocated, newBalance, newArmyFunds }
    let inputValue = '';
    let errorMsg = loadError;

    function parseInput() {
        const n = parseInt(inputValue, 10);
        return Number.isFinite(n) ? n : null;
    }
    function isValid() {
        const n = parseInput();
        return armyExists && n != null && n >= 1 && n <= maxAlloc;
    }

    function branchBlock(label, opts) {
        // opts: { enabled, brigades, budget, note }
        const dim = opts.enabled ? '' : 'opacity:0.45;';
        return `
            <div style="border:1px solid var(--border-main);padding:10px 12px;${dim}">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:var(--text-bright);letter-spacing:0.04em;">${esc(label)}</div>
                ${opts.note
                    ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim);margin-top:4px;">${esc(opts.note)}</div>`
                    : `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px;">
                        <div><div style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);letter-spacing:0.06em;">CURRENT BRIGADES</div><div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:var(--text-secondary);">${opts.brigades}</div></div>
                        <div><div style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);letter-spacing:0.06em;">CURRENT BUDGET</div><div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:var(--text-bright);">$${opts.budget}</div></div>
                    </div>`}
            </div>`;
    }

    function render() {
        const amt = parseInput();
        const valid = isValid();
        const projBalance = (amt != null && amt >= 1) ? balanceAbstract - amt : balanceAbstract;
        const projArmy    = (amt != null && amt >= 1) ? armyBudget + amt : armyBudget;

        const resultHtml = result ? `
            <div style="padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.22);margin-top:12px;">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;margin-bottom:4px;">Funds allocated</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);">
                    $${result.allocated} → Army of ${esc(nationName)}<br>
                    Discretionary: <strong>$${toAbstract(result.newBalance)}</strong> · Army budget: <strong>$${toAbstract(result.newArmyFunds)}</strong>
                </div>
            </div>` : '';
        const errorHtml = errorMsg ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--red);margin-top:6px;">${esc(errorMsg)}</div>` : '';

        overlay.innerHTML = `
            <div class="pa-modal" style="width:500px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Allocate Funds</span>
                    </div>
                    <button class="pa-modal-close" id="pa-af-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    Distribute the Defense Ministry's discretionary budget to a military branch. Funds move 1:1 into that branch's treasury.
                </div>
                <div class="pa-modal-body" style="gap:10px;">
                    <div>
                        <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">YOUR MINISTRY'S DISCRETIONARY FUNDS</div>
                        <div style="font-family:var(--font-mono);font-size:18px;font-weight:700;color:${balanceAbstract > 0 ? 'var(--green)' : 'var(--red)'};">$${balanceAbstract}</div>
                    </div>

                    ${branchBlock(`Army of ${nationName}`, armyExists
                        ? { enabled: true, brigades: 0, budget: armyBudget }
                        : { enabled: false, note: 'No army established.' })}

                    ${armyExists ? `
                        <div class="pa-modal-step-label">Allocate to Army (whole dollars, 1 – ${maxAlloc})</div>
                        <input id="pa-af-input" class="pa-modal-input" type="number" min="1" max="${maxAlloc}" step="1" placeholder="0" value="${esc(inputValue)}" ${result || submitting ? 'disabled' : ''} style="font-family:var(--font-mono);font-size:14px;">
                        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding-top:4px;">
                            <div><div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">AFTER · DISCRETIONARY</div><div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:${projBalance >= 0 ? 'var(--text-bright)' : 'var(--red)'};">$${projBalance}</div></div>
                            <div><div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">AFTER · ARMY BUDGET</div><div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:var(--text-bright);">$${projArmy}</div></div>
                        </div>
                    ` : ''}

                    ${branchBlock(`Navy of ${nationName}`,      { enabled: false, note: 'Not yet established.' })}
                    ${branchBlock(`Air Force of ${nationName}`, { enabled: false, note: 'Not yet established.' })}
                    ${errorHtml}
                    ${resultHtml}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-af-cancel">${result ? 'Close' : 'Cancel'}</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-af-submit" ${!valid || submitting || result || loadError ? 'disabled' : ''}>${submitting ? 'Allocating…' : 'Allocate'}</button>
                </div>
            </div>
        `;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('pa-af-close')?.addEventListener('click', close);
        document.getElementById('pa-af-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        const input = document.getElementById('pa-af-input');
        if (input) {
            input.addEventListener('input', (e) => {
                inputValue = (e.target.value || '').replace(/[^0-9]/g, '');
                errorMsg = loadError;
                render();
                const refocus = document.getElementById('pa-af-input');
                if (refocus) { refocus.focus(); refocus.setSelectionRange(refocus.value.length, refocus.value.length); }
            });
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && isValid() && !submitting && !result && !loadError) {
                    e.preventDefault();
                    submit();
                }
            });
        }
        document.getElementById('pa-af-submit')?.addEventListener('click', submit);
    }

    async function submit() {
        if (submitting || result || loadError) return;
        if (!isValid()) {
            errorMsg = `Enter an integer between 1 and ${maxAlloc}.`;
            render();
            return;
        }
        const amount = parseInput();
        submitting = true;
        errorMsg = '';
        render();
        try {
            const { data, error } = await _supabase.rpc('allocate_defense_funds', { p_branch: 'army', p_amount: amount });
            if (error) {
                errorMsg = error.message || 'Allocation failed.';
            } else if (!data?.success) {
                errorMsg = humanizeReason(data?.reason) || 'Allocation failed.';
            } else {
                result = data;
            }
        } catch (e) {
            errorMsg = e?.message || 'Network error.';
        } finally {
            submitting = false;
            render();
        }
    }

    function humanizeReason(reason) {
        switch (reason) {
            case 'not_authenticated':  return 'You are not signed in.';
            case 'branch_unavailable': return 'Only the Army can receive funds right now.';
            case 'invalid_amount':     return 'Enter an integer of at least $1.';
            case 'not_minister':       return 'Only the Minister of Defense can allocate funds.';
            case 'insufficient_funds': return 'Not enough discretionary budget for that allocation.';
            case 'no_army_faction':    return 'No army has been established for this nation yet.';
            default:                   return reason || '';
        }
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ CENTRAL BANK — RATE MOVE ════════════════════════
// Governor of the Central Bank moves the policy rate by up to 3% for $1.
async function openCbRateModal(root, direction) {
    const overlay = document.getElementById('pa-cb-rate-modal');
    if (!overlay) return;
    const isLower = direction === 'lower';
    const verb = isLower ? 'Lower' : 'Raise';
    let pct = 3;
    let submitting = false;
    let result = null;
    let errorMsg = '';

    function render() {
        const n = _state?.nation || {};
        const rate = Number(n.central_bank_interest_rate ?? 5);
        const disc = Number(n.central_bank_discretionary ?? 0);
        const signed = isLower ? -pct : pct;
        const projected = Math.max(0, Math.min(20, rate + signed));
        const gdpNote = isLower ? `+${3 * pct} GDP growth` : `−${5 * pct} GDP growth`;

        const pctBtns = [1, 2, 3].map(v =>
            `<button class="pa-modal-btn ${v === pct ? 'pa-modal-btn--submit' : ''}" data-pct="${v}" ${result || submitting ? 'disabled' : ''} style="${v === pct ? 'background:#c8a832;' : 'background:transparent;border:1px solid var(--border-main);color:var(--text-secondary);'}padding:6px 14px;font-size:12px;">${v}%</button>`
        ).join('');

        const resultHtml = result ? `
            <div style="margin-top:12px;padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.22);">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;margin-bottom:4px;">Rate updated</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);">New policy rate <strong>${Number(result.rate).toFixed(2)}%</strong> · lending pool <strong>$${cbPoolAbstract(result.discretionary).toLocaleString()}</strong></div>
            </div>` : '';
        const errorHtml = errorMsg ? `<div style="font-family:var(--font-mono);font-size:10px;color:var(--red);margin-top:8px;">${esc(errorMsg)}</div>` : '';

        overlay.innerHTML = `
            <div class="pa-modal" style="width:460px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">${verb} Interest</span>
                    </div>
                    <button class="pa-modal-close" id="pa-cb-close">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    Costs <strong style="color:#c8a832;">$1</strong> from the lending pool ($${cbPoolAbstract(disc).toLocaleString()} available). ${isLower ? 'Stimulus — raises GDP growth.' : 'Tightening — lowers GDP growth.'} Rate clamps 0–20%.
                </div>
                <div class="pa-modal-body" style="gap:12px;">
                    <div>
                        <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">CURRENT RATE</div>
                        <div style="font-family:var(--font-mono);font-size:20px;font-weight:700;color:#c8a832;">${rate.toFixed(2)}%</div>
                    </div>
                    <div class="pa-modal-step-label">${verb} by</div>
                    <div style="display:flex;gap:8px;">${pctBtns}</div>
                    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding-top:4px;">
                        <div><div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">PROJECTED RATE</div><div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:var(--text-bright);">${projected.toFixed(2)}%</div></div>
                        <div><div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);letter-spacing:0.04em;">GDP EFFECT</div><div style="font-family:var(--font-mono);font-size:13px;font-weight:700;color:${isLower ? 'var(--green)' : 'var(--red)'};">${gdpNote}</div></div>
                    </div>
                    ${errorHtml}
                    ${resultHtml}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-cb-cancel">${result ? 'Close' : 'Cancel'}</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-cb-submit" ${submitting || result ? 'disabled' : ''}>${submitting ? 'Working…' : verb}</button>
                </div>
            </div>`;

        const close = () => { overlay.classList.remove('active'); if (result) renderPage(root); };
        document.getElementById('pa-cb-close')?.addEventListener('click', close);
        document.getElementById('pa-cb-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };
        overlay.querySelectorAll('[data-pct]').forEach(btn => btn.addEventListener('click', () => {
            pct = parseInt(btn.dataset.pct, 10); errorMsg = ''; render();
        }));
        document.getElementById('pa-cb-submit')?.addEventListener('click', submit);
    }

    async function submit() {
        if (submitting || result) return;
        submitting = true; errorMsg = ''; render();
        try {
            const { data, error } = await _supabase.rpc('central_bank_set_rate', { p_direction: direction, p_pct: pct });
            if (error) {
                errorMsg = error.message || 'Rate change failed.';
            } else if (!data?.success) {
                errorMsg = humanizeCbReason(data?.reason);
            } else {
                result = data;
                // Patch cached nation so the re-render shows fresh values.
                _state.nation.central_bank_interest_rate = data.rate;
                _state.nation.central_bank_discretionary = data.discretionary;
                if (data.gdpGrowth != null) _state.nation.gdp_growth = data.gdpGrowth;
            }
        } catch (e) {
            errorMsg = e?.message || 'Network error.';
        } finally {
            submitting = false; render();
        }
    }

    overlay.classList.add('active');
    render();
}

function humanizeCbReason(reason) {
    switch (reason) {
        case 'not_authenticated':          return 'You are not signed in.';
        case 'not_governor':               return 'Only the Governor of the Central Bank can move the rate.';
        case 'term_expired':               return 'The Governor\'s term has ended — a successor must be appointed.';
        case 'insufficient_discretionary': return 'The lending pool is empty — $1 is required.';
        case 'rate_at_limit':              return 'The rate is already at its limit (0% or 20%).';
        case 'invalid_direction':
        case 'invalid_pct':                return 'Invalid rate change.';
        default:                           return reason || 'Action failed.';
    }
}

// ════════════════════════ EXPAND STADIUM INFRASTRUCTURE ════════════════════════

async function openVolaStadiumModal(root, faction) {
    const overlay = document.getElementById('pa-vola-stadium-modal');
    if (!overlay) return;

    let stadiumName = '';
    let teamName    = '';
    let selectedSize = null;
    let submitting = false;
    let bidsContract = null;        // { id, name, description, ... } current open contract for this nation
    let bids = [];                  // pending bids on the open contract
    let lastError = null;

    async function refreshState() {
        const { data: mRow } = await _supabase.from('ministries')
            .select('id, party_id, discretionary_balance')
            .eq('nation_id', _state.nation.id)
            .eq('ministry_key', 'sports').eq('is_active', true).maybeSingle();
        const balance = Number(mRow?.discretionary_balance) || 0;

        const { data: open } = await _supabase.from('corp_contracts')
            .select('id, name, description, spec_category, expires_at_tick, created_at_tick')
            .eq('issuer_nation_id', _state.nation.id)
            .eq('project_subtype', 'Vola Stadium').eq('status', 'open')
            .order('created_at_tick', { ascending: false }).limit(1).maybeSingle();
        bidsContract = open || null;

        bids = [];
        if (bidsContract) {
            const { data: bidRows } = await _supabase.from('corp_contract_bids')
                .select('id, faction_id, bid_amount, quoted_timeline_months, status, created_at_tick, factions:faction_id(id, faction_name, nation_id, nations:nation_id(name))')
                .eq('contract_id', bidsContract.id)
                .eq('status', 'pending')
                .order('created_at_tick', { ascending: true });
            bids = bidRows || [];
        }

        return { balance, hasMinister: !!mRow, isMinister: mRow?.party_id === faction.id };
    }

    async function render() {
        const { balance, hasMinister, isMinister } = await refreshState();

        const tiers = ['small', 'modest', 'extravagant'].map(k => ({ key: k, cfg: VOLA_STADIUM_TIERS[k] }));
        const balanceColor = balance > 0 ? 'var(--green)' : 'var(--red)';

        let bodyHtml = '';

        if (bidsContract) {
            // Existing-contract view: show bids list + cancel.
            const tierFloor = bidsContract.spec_category === 'Light Infrastructure' ? 2
                            : bidsContract.spec_category === 'Heavy Infrastructure' ? 4
                            : bidsContract.spec_category === 'Megaproject'          ? 9 : 0;
            const teamLabel = (bidsContract.description || '').replace(/^Home of:\s*/i, '').trim();

            bodyHtml += `
                <div class="pa-modal-step-label">Open Stadium Contract</div>
                <div class="pa-action-item" style="cursor:default;">
                    <div class="pa-action-top">
                        <span style="font-size:13px;font-weight:700;color:var(--text-bright);">${esc(bidsContract.name)}</span>
                        <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;">Floor +${tierFloor}</span>
                    </div>
                    <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">
                        ${teamLabel ? 'Home of ' + esc(teamLabel) + ' · ' : ''}${esc(bidsContract.spec_category)}
                    </div>
                </div>
            `;

            bodyHtml += `<div class="pa-modal-step-label" style="margin-top:14px;">Submitted Stadium Bids ${bids.length ? '· ' + bids.length : ''}</div>`;
            if (bids.length === 0) {
                bodyHtml += `<div style="padding:14px;font-family:var(--font-mono);font-size:10px;color:var(--text-dim);font-style:italic;text-align:center;">Awaiting corporate bids…</div>`;
            } else {
                const tickToDate = (t) => {
                    if (t == null) return '—';
                    const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
                    const y = 2000 + Math.floor(t / 12);
                    return `${MONTHS[t % 12]}, ${y}`;
                };
                bodyHtml += bids.map(b => {
                    const corpName = b.factions?.faction_name || 'Unknown Corp';
                    const hqNation = b.factions?.nations?.name || '—';
                    const price    = Number(b.bid_amount || 0);
                    const priceLabel = price >= 1e9 ? '$' + (price / 1e9).toFixed(2) + 'B'
                                     : price >= 1e6 ? '$' + (price / 1e6).toFixed(1) + 'M'
                                     : '$' + Math.round(price).toLocaleString();
                    const timeline = Number(b.quoted_timeline_months || 0);
                    const finishTick = Number(b.created_at_tick || 0) + timeline;
                    return `<div class="pa-action-item" style="cursor:default;" data-bid-id="${esc(b.id)}">
                        <div class="pa-action-top">
                            <div>
                                <div style="font-size:13px;font-weight:700;color:var(--text-bright);">${esc(corpName)}</div>
                                <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">
                                    HQ ${esc(hqNation)} · Price ${priceLabel} · Timeline ${timeline} ticks · Finished ${tickToDate(finishTick)}
                                </div>
                            </div>
                            <div style="display:flex;gap:6px;">
                                <button class="pa-modal-btn pa-modal-btn--submit" data-action="accept" data-bid-id="${esc(b.id)}" ${submitting ? 'disabled' : ''} style="padding:4px 10px;font-size:9px;background:#5cc55c;border-color:#5cc55c;">Accept</button>
                                <button class="pa-modal-btn pa-modal-btn--cancel" data-action="reject" data-bid-id="${esc(b.id)}" ${submitting ? 'disabled' : ''} style="padding:4px 10px;font-size:9px;">Reject</button>
                            </div>
                        </div>
                    </div>`;
                }).join('');
            }
        } else {
            // Posting view: show tiers + name/team inputs.
            const tiersHtml = tiers.map(t => {
                const canAfford = balance >= t.cfg.postingCost;
                const isSel = selectedSize === t.key;
                const costLabel = '$' + (t.cfg.postingCost / 1_000_000);
                const budgetLabel = '$' + (t.cfg.budgetTarget / 1_000_000) + 'M';
                return `<div class="pa-action-item ${!canAfford || submitting ? 'locked' : ''} ${isSel ? 'selected' : ''}" data-size="${t.key}" style="cursor:${canAfford && !submitting ? 'pointer' : 'not-allowed'};${isSel ? 'border-color:#c8a832;background:rgba(200,168,50,0.06);' : ''}">
                    <div class="pa-action-top">
                        <span style="font-size:13px;font-weight:700;color:${isSel ? '#c8a832' : 'var(--text-bright)'};">${t.cfg.label}</span>
                        <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;">Floor +${t.cfg.floorContribution}</span>
                    </div>
                    <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">
                        Discretionary ${costLabel} · Contract budget ${budgetLabel} · Timeline ~${t.cfg.timelineMonths} ticks · ${t.cfg.crewsRequired} crew${t.cfg.crewsRequired === 1 ? '' : 's'} required
                    </div>
                    ${!canAfford ? `<div style="font-family:var(--font-mono);font-size:8px;color:var(--red);margin-top:4px;">Insufficient discretionary — need ${costLabel}</div>` : ''}
                </div>`;
            }).join('');

            bodyHtml = `
                <div class="pa-modal-step-label">Stadium Name</div>
                <input id="vola-stadium-name" type="text" maxlength="60"
                       placeholder="e.g. Coastal Vola Park"
                       value="${esc(stadiumName)}"
                       style="width:100%;padding:8px 10px;background:var(--bg-card);border:1px solid var(--border-main);color:var(--text-bright);font-family:var(--font-mono);font-size:12px;">

                <div class="pa-modal-step-label" style="margin-top:14px;">Home Of</div>
                <input id="vola-stadium-team" type="text" maxlength="60"
                       placeholder="e.g. F.C. Drevlak / Sporting San Maria / Real Avelia"
                       value="${esc(teamName)}"
                       style="width:100%;padding:8px 10px;background:var(--bg-card);border:1px solid var(--border-main);color:var(--text-bright);font-family:var(--font-mono);font-size:12px;">

                <div class="pa-modal-step-label" style="margin-top:14px;">Choose Stadium Size</div>
                <div id="vola-stadium-tiers">${tiersHtml}</div>

                ${lastError ? `<div style="margin-top:10px;padding:8px 10px;background:rgba(200,80,80,0.08);border:1px solid rgba(200,80,80,0.2);font-family:var(--font-mono);font-size:10px;color:var(--red);">${esc(lastError)}</div>` : ''}
            `;
        }

        const footerHtml = bidsContract
            ? `<button class="pa-modal-btn pa-modal-btn--cancel" id="vola-stadium-cancel-bid" ${submitting ? 'disabled' : ''}>Cancel Bid</button>
               <button class="pa-modal-btn" id="vola-stadium-close" style="background:var(--bg-card);">Close</button>`
            : `<button class="pa-modal-btn pa-modal-btn--cancel" id="vola-stadium-close">Cancel</button>
               <button class="pa-modal-btn pa-modal-btn--submit" id="vola-stadium-post" ${(!selectedSize || !stadiumName.trim() || submitting) ? 'disabled' : ''} style="background:#c8a832;">Post Stadium Contract</button>`;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:560px;max-height:85vh;overflow-y:auto;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Expand Stadium Infrastructure</span>
                    </div>
                    <button class="pa-modal-close" id="vola-stadium-x">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    ${hasMinister && isMinister
                        ? `Posting cost pulls from the Sports Ministry's discretionary budget — <strong style="color:${balanceColor};">${fmtDiscretionaryBalance(balance)}</strong> available. Top it up via a funding article on a passed bill.`
                        : '<span style="color:var(--red);">You are no longer the active Sports Minister.</span>'}
                </div>
                <div class="pa-modal-body" style="gap:6px;">
                    ${bodyHtml}
                </div>
                <div class="pa-modal-footer">${footerHtml}</div>
            </div>
        `;

        const close = () => overlay.classList.remove('active');
        document.getElementById('vola-stadium-x')?.addEventListener('click', close);
        document.getElementById('vola-stadium-close')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        // Posting view bindings.
        const nameEl = document.getElementById('vola-stadium-name');
        const teamEl = document.getElementById('vola-stadium-team');
        nameEl?.addEventListener('input', (e) => { stadiumName = e.target.value; document.getElementById('vola-stadium-post').disabled = !stadiumName.trim() || !selectedSize || submitting; });
        teamEl?.addEventListener('input', (e) => { teamName = e.target.value; });

        document.getElementById('vola-stadium-tiers')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-size]');
            if (!item || item.classList.contains('locked') || submitting) return;
            selectedSize = item.dataset.size;
            render();
        });

        document.getElementById('vola-stadium-post')?.addEventListener('click', async () => {
            if (submitting || !selectedSize || !stadiumName.trim()) return;
            submitting = true; lastError = null; render();
            try {
                const { data: shard } = await _supabase.from('shard').select('current_tick').eq('name', 'Alpha Shard').single();
                const tick = Number(shard?.current_tick) || 0;
                const r = await postStadiumConstruction(_supabase, _state.nation, faction.id, {
                    stadiumName: stadiumName.trim(),
                    teamName:    teamName.trim(),
                    size:        selectedSize,
                }, tick);
                if (r?.success) {
                    selectedSize = null; stadiumName = ''; teamName = '';
                    await render();
                } else {
                    lastError = _stadiumReasonCopy(r?.reason) || 'Could not post: ' + (r?.reason || 'unknown error');
                }
            } catch (err) {
                lastError = 'Posting failed: ' + (err?.message || err);
            } finally {
                submitting = false;
                render();
            }
        });

        // Bids-list view bindings.
        document.querySelectorAll('[data-action]').forEach(btn => {
            btn.addEventListener('click', async (e) => {
                if (submitting) return;
                const action = btn.dataset.action;
                const bidId  = btn.dataset.bidId;
                if (!bidId) return;
                submitting = true; render();
                try {
                    if (action === 'accept') {
                        const { data, error } = await _supabase.rpc('award_stadium_bid_to_corp', { p_bid_id: bidId });
                        if (error) throw error;
                        if (!data?.success) throw new Error(data?.error || 'Award failed');
                    } else if (action === 'reject') {
                        const { data, error } = await _supabase.rpc('reject_stadium_bid', { p_bid_id: bidId });
                        if (error) throw error;
                        if (!data?.success) throw new Error(data?.error || 'Reject failed');
                    }
                } catch (err) {
                    alert('Action failed: ' + (err?.message || err));
                } finally {
                    submitting = false;
                    render();
                }
            });
        });

        document.getElementById('vola-stadium-cancel-bid')?.addEventListener('click', async () => {
            if (submitting || !bidsContract) return;
            if (!confirm('Cancel this stadium contract?\n\nDiscretionary cost will be refunded.')) return;
            submitting = true; render();
            try {
                const { data, error } = await _supabase.rpc('cancel_stadium_contract', { p_contract_id: bidsContract.id });
                if (error) throw error;
                if (!data?.success) throw new Error(data?.error || 'Cancel failed');
                bidsContract = null;
                bids = [];
            } catch (err) {
                alert('Cancel failed: ' + (err?.message || err));
            } finally {
                submitting = false;
                render();
            }
        });
    }

    function _stadiumReasonCopy(reason) {
        const map = {
            no_minister:          'No active Sports Minister.',
            not_minister:         'Only the Sports Minister can post stadium contracts.',
            insufficient_balance: 'Sports discretionary budget is below the tier cost — pass a funding bill first.',
            already_open:         'A stadium contract is already open. Wait for it to resolve, or cancel it first.',
            no_stadium_name:      'Stadium name is required.',
            invalid_size:         'Pick a stadium size first.',
            insert_failed:        'Could not post the contract. Try again in a moment.',
        };
        return map[reason];
    }

    overlay.classList.add('active');
    await render();
}

// ════════════════════ EXPAND INFRASTRUCTURE ════════════════════
// Minister of the Interior's contract-creating action. Mirrors the
// Vola Stadium modal: tier picker view when no open contract exists,
// open-contract view with pending bids list (read-only — interior
// contracts auto-award via the construction cron when the bid window
// expires, no minister pick). RPCs used:
//   interior_infrastructure_tiers()   — tier specs JSONB
//   post_interior_infrastructure(p_size) — posts the contract
async function openExpandInfrastructureModal(root, faction) {
    const overlay = document.getElementById('pa-expand-infra-modal');
    if (!overlay) return;

    let tiers = null;              // loaded once from RPC
    let selectedSize = null;
    let submitting = false;
    let bidsContract = null;       // open contract row, if any
    let bids = [];                 // pending bids on the open contract
    let lastError = null;

    async function refreshState() {
        const { data: mRow } = await _supabase.from('ministries')
            .select('id, party_id, discretionary_balance')
            .eq('nation_id', _state.nation.id)
            .eq('ministry_key', 'interior').eq('is_active', true).maybeSingle();
        const balance = Number(mRow?.discretionary_balance) || 0;

        // Expand Infrastructure now posts to the entrepreneur construction-bid
        // system (government ent_construction_contracts). Aliased to the field
        // names the render below already uses.
        const { data: open } = await _supabase.from('ent_construction_contracts')
            .select('id, name, budget, status, spec_category:spec_tier, timeline_months:timeline_ticks, expires_at_tick:bidding_closes_tick, created_at_tick')
            .eq('issuer_nation_id', _state.nation.id)
            .eq('contract_type', 'government')
            .in('status', ['open', 'active'])
            .order('created_at_tick', { ascending: false }).limit(1).maybeSingle();
        bidsContract = open || null;

        bids = [];
        if (bidsContract && bidsContract.status !== 'active') {
            const { data: bidRows } = await _supabase.from('ent_construction_bids')
                .select('id, bid_amount, status, created_tick, factions:entrepreneur_corps!bidder_corp_id(faction_name:name)')
                .eq('contract_id', bidsContract.id)
                .eq('status', 'pending')
                .order('bid_amount', { ascending: true });
            bids = bidRows || [];
        }

        if (!tiers) {
            const { data: tData, error: tErr } = await _supabase.rpc('interior_infrastructure_tiers');
            if (tErr) {
                lastError = 'Could not load tier specs: ' + tErr.message;
                tiers = {};
            } else {
                tiers = tData || {};
            }
        }

        return { balance, isMinister: !!mRow && mRow.party_id === faction.id };
    }

    async function render() {
        const { balance, isMinister } = await refreshState();
        const balanceColor = balance > 0 ? 'var(--green)' : 'var(--red)';
        const fmtM = (n) => '$' + (Number(n) / 1_000_000).toFixed(Number(n) % 1_000_000 === 0 ? 0 : 1) + 'M';
        const isActive = bidsContract?.status === 'active';

        let bodyHtml = '';

        if (bidsContract) {
            // Existing-contract view — bid window auto-awards via cron
            // using composite score (cost, timeline, reputation).
            bodyHtml += `
                <div class="pa-modal-step-label">${isActive ? 'Active Infrastructure Contract' : 'Open Infrastructure Contract'}</div>
                <div class="pa-action-item" style="cursor:default;">
                    <div class="pa-action-top">
                        <span style="font-size:13px;font-weight:700;color:var(--text-bright);">${esc(bidsContract.name)}</span>
                        <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#5aafa5;">${fmtM(bidsContract.budget)}</span>
                    </div>
                    <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">
                        ${esc(bidsContract.spec_category)} · Timeline ${bidsContract.timeline_months} ticks${isActive ? '' : ` · Bidding closes tick ${bidsContract.expires_at_tick}`}
                    </div>
                </div>
            `;

            if (isActive) {
                bodyHtml += `<div style="margin-top:10px;padding:10px 12px;font-family:var(--font-mono);font-size:10px;color:var(--text-dim);background:rgba(90,175,165,0.06);border:1px solid rgba(90,175,165,0.2);">Construction is underway. Stat boosts apply on completion.</div>`;
            } else {
                bodyHtml += `<div class="pa-modal-step-label" style="margin-top:14px;">Pending Bids ${bids.length ? '· ' + bids.length : ''}</div>`;
                if (bids.length === 0) {
                    bodyHtml += `<div style="padding:14px;font-family:var(--font-mono);font-size:10px;color:var(--text-dim);font-style:italic;text-align:center;">Awaiting construction corporation bids…</div>`;
                } else {
                    bodyHtml += `<div id="expand-infra-bids">` + bids.map(b => {
                        const corpName = b.factions?.faction_name || 'Unknown Corp';
                        const price    = Number(b.bid_amount || 0);
                        const priceLabel = price >= 1e9 ? '$' + (price / 1e9).toFixed(2) + 'B'
                                         : price >= 1e6 ? '$' + (price / 1e6).toFixed(1) + 'M'
                                         : '$' + Math.round(price).toLocaleString();
                        const dis = (submitting || !isMinister) ? ' disabled' : '';
                        return `<div class="pa-action-item" style="cursor:default;">
                            <div class="pa-action-top">
                                <div>
                                    <div style="font-size:13px;font-weight:700;color:var(--text-bright);">${esc(corpName)}</div>
                                    <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">Bid ${priceLabel}</div>
                                </div>
                            </div>
                            ${isMinister ? `<div style="display:flex;gap:8px;margin-top:10px;">
                                <button class="pa-modal-btn pa-modal-btn--submit" data-bid-action="accept" data-bid-id="${esc(b.id)}" style="flex:1;min-height:36px;background:#5aafa5;"${dis}>Accept</button>
                                <button class="pa-modal-btn pa-modal-btn--cancel" data-bid-action="reject" data-bid-id="${esc(b.id)}" style="flex:1;min-height:36px;"${dis}>Reject</button>
                            </div>` : ''}
                        </div>`;
                    }).join('') + `</div>`;
                }
                bodyHtml += `<div style="margin-top:10px;padding:8px 10px;font-family:var(--font-mono);font-size:9px;color:var(--text-dim);background:rgba(255,255,255,0.02);border:1px dashed rgba(255,255,255,0.08);">${isMinister
                    ? 'Accept any bid to award immediately, or reject specific bidders. If no action is taken, the lowest remaining bid auto-wins when the window closes.'
                    : 'The lowest qualifying bid wins automatically when the bid window closes.'}</div>`;
                if (lastError) {
                    bodyHtml += `<div style="margin-top:8px;padding:8px 10px;background:rgba(200,80,80,0.08);border:1px solid rgba(200,80,80,0.2);font-family:var(--font-mono);font-size:10px;color:var(--red);">${esc(lastError)}</div>`;
                }
            }
        } else {
            // Tier-picking view.
            const order = ['small', 'modest', 'extravagant'];
            const tierLabel = { small: 'SMALL', modest: 'MODEST', extravagant: 'EXTRAVAGANT' };
            const tiersHtml = order.map(k => {
                const t = tiers?.[k];
                if (!t) return '';
                const postCost = Number(t.post_cost || 0);
                const budget   = Number(t.budget || 0);
                const canAfford = balance >= postCost;
                const isSel = selectedSize === k;
                const effects = (t.stat_effects || []).map(e => {
                    const sign = Number(e.delta) >= 0 ? '+' : '';
                    const stat = String(e.stat).replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
                    return `<span class="pa-action-tag" style="color:var(--green);">${sign}${e.delta} ${stat}</span>`;
                }).join(' ');
                return `<div class="pa-action-item ${!canAfford || submitting ? 'locked' : ''} ${isSel ? 'selected' : ''}" data-size="${k}" style="cursor:${canAfford && !submitting ? 'pointer' : 'not-allowed'};${isSel ? 'border-color:#5aafa5;background:rgba(90,175,165,0.06);' : ''}">
                    <div class="pa-action-top">
                        <span style="font-size:13px;font-weight:700;color:${isSel ? '#5aafa5' : 'var(--text-bright)'};">${esc(t.name || tierLabel[k])}</span>
                        <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#5aafa5;">${tierLabel[k]}</span>
                    </div>
                    <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">
                        Post fee ${fmtM(postCost)} · Contract budget ${fmtM(budget)} · Timeline ${t.timeline} ticks
                    </div>
                    ${effects ? `<div class="pa-action-tags" style="margin-top:4px;">${effects}</div>` : ''}
                    ${!canAfford ? `<div style="font-family:var(--font-mono);font-size:8px;color:var(--red);margin-top:4px;">Insufficient discretionary — need ${fmtM(postCost)}</div>` : ''}
                </div>`;
            }).join('');

            bodyHtml = `
                <div class="pa-modal-step-label">Choose Tier</div>
                <div id="expand-infra-tiers">${tiersHtml}</div>
                ${lastError ? `<div style="margin-top:10px;padding:8px 10px;background:rgba(200,80,80,0.08);border:1px solid rgba(200,80,80,0.2);font-family:var(--font-mono);font-size:10px;color:var(--red);">${esc(lastError)}</div>` : ''}
            `;
        }

        const footerHtml = bidsContract
            ? `<button class="pa-modal-btn" id="expand-infra-close" style="background:var(--bg-card);">Close</button>`
            : `<button class="pa-modal-btn pa-modal-btn--cancel" id="expand-infra-close">Cancel</button>
               <button class="pa-modal-btn pa-modal-btn--submit" id="expand-infra-post" ${(!selectedSize || submitting) ? 'disabled' : ''} style="background:#5aafa5;">Post Infrastructure Contract</button>`;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:560px;max-height:85vh;overflow-y:auto;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#5aafa5;"></div>
                        <span class="pa-modal-title">Expand Infrastructure</span>
                    </div>
                    <button class="pa-modal-close" id="expand-infra-x">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    ${isMinister
                        ? `Post fee pulls from the Interior Ministry's discretionary budget — <strong style="color:${balanceColor};">${fmtDiscretionaryBalance(balance)}</strong> available. Construction corps bid; the best-scoring bid (cost, timeline, reputation) auto-wins when the bid window closes. Stat boosts apply on completion.`
                        : '<span style="color:var(--red);">You are no longer the active Interior Minister.</span>'}
                </div>
                <div class="pa-modal-body" style="gap:6px;">
                    ${bodyHtml}
                </div>
                <div class="pa-modal-footer">${footerHtml}</div>
            </div>
        `;

        const close = () => overlay.classList.remove('active');
        document.getElementById('expand-infra-x')?.addEventListener('click', close);
        document.getElementById('expand-infra-close')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        document.getElementById('expand-infra-tiers')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-size]');
            if (!item || item.classList.contains('locked') || submitting) return;
            selectedSize = item.dataset.size;
            render();
        });

        document.getElementById('expand-infra-post')?.addEventListener('click', async () => {
            if (submitting || !selectedSize) return;
            submitting = true; lastError = null; render();
            try {
                const { data, error } = await _supabase.rpc('post_interior_infrastructure', { p_size: selectedSize });
                if (error) {
                    lastError = error.message || 'Post failed';
                } else if (!data?.success) {
                    lastError = data?.error || 'Could not post contract';
                } else {
                    selectedSize = null;
                }
            } catch (err) {
                lastError = 'Posting failed: ' + (err?.message || err);
            } finally {
                submitting = false;
                render();
            }
        });

        // Minister Accept / Reject on a specific bid. Accept awards immediately
        // (contract → 'active', bids list empties on next render); Reject flips
        // the single bid to 'rejected' (removed from the next pending fetch).
        // The shared `submitting` flag gates all bid actions to prevent
        // double-fire across cards.
        document.getElementById('expand-infra-bids')?.addEventListener('click', async (e) => {
            const btn = e.target.closest('[data-bid-action]');
            if (!btn || submitting) return;
            const action = btn.dataset.bidAction;
            const bidId  = btn.dataset.bidId;
            if (!bidId || (action !== 'accept' && action !== 'reject')) return;
            const rpcName = action === 'accept'
                ? 'interior_accept_construction_bid'
                : 'interior_reject_construction_bid';
            const reasonLabel = {
                not_minister:      'Only the active Interior Minister can act on these bids.',
                not_open:          'This contract is no longer open.',
                not_government:    'This is not a government contract.',
                bid_not_pending:   'That bid is no longer pending.',
                bid_not_found:     'That bid no longer exists.',
                contract_not_found: 'Contract not found.',
                bidder_at_capacity: 'That builder is at their construction-yard capacity.',
                not_authenticated: 'Sign in to continue.',
            };
            submitting = true; lastError = null; render();
            try {
                const { data, error } = await _supabase.rpc(rpcName, { p_bid_id: bidId });
                if (error) {
                    lastError = error.message || `${action} failed`;
                } else if (!data?.success) {
                    lastError = reasonLabel[data?.reason] || `Could not ${action} bid (${data?.reason || 'unknown'}).`;
                }
            } catch (err) {
                lastError = `${action === 'accept' ? 'Accept' : 'Reject'} failed: ` + (err?.message || err);
            } finally {
                submitting = false;
                render();
            }
        });
    }

    overlay.classList.add('active');
    await render();
}

// ════════════════════════ BID TO HOST VWC ════════════════════════

// Cup-schedule constants — mirror political-actions.js (which the
// edge bundle owns; the JS-side modal needs them locally).
const _VWC_FIRST_TICK = 84;
const _VWC_PERIOD     = 24;
const _VWC_QUAL_OFFSET = 12;

function _hbCupOrdinal(n) {
    const v = n % 100, last = n % 10;
    if (v >= 11 && v <= 13) return n + 'th';
    if (last === 1) return n + 'st';
    if (last === 2) return n + 'nd';
    if (last === 3) return n + 'rd';
    return n + 'th';
}

function _hbTickToDate(tick) {
    if (tick == null) return '—';
    const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    const y = 2000 + Math.floor(tick / 12);
    return `${MONTHS[tick % 12]}, ${y}`;
}

async function openVolaHostBidModal(root, faction) {
    const overlay = document.getElementById('pa-vola-host-bid-modal');
    if (!overlay) return;

    let submitting = false;
    let lastError = null;
    let result = null;
    // In-session bid tracker — belt-and-suspenders so the cup row
    // flips to "bid placed" immediately on success, even if the
    // re-fetch from vola_host_bids hasn't surfaced the new row yet
    // (postgrest read-after-write occasionally lags by a frame).
    // Map of cupNumber → bid_at_tick so the row's metadata
    // (placed-on date) renders without a second round-trip.
    const inSessionBids = new Map();

    async function refreshState() {
        const { data: mRow } = await _supabase.from('ministries')
            .select('id, party_id, discretionary_balance')
            .eq('nation_id', _state.nation.id)
            .eq('ministry_key', 'sports').eq('is_active', true).maybeSingle();
        const { data: shard } = await _supabase.from('shard').select('current_tick').eq('name', 'Alpha Shard').single();
        const tick = Number(shard?.current_tick) || 0;

        // Pick the next 3 cups whose qualifier (resolution) tick is
        // still in the future. Once that tick passes, bidding is
        // closed regardless of host state.
        const cups = [];
        let n = 0;
        while (cups.length < 3 && n < 200) {
            const cupNumber = n + 1;
            const cupStart = _VWC_FIRST_TICK + _VWC_PERIOD * n;
            const resolutionTick = cupStart - _VWC_QUAL_OFFSET;
            if (resolutionTick > tick) {
                cups.push({ cupNumber, cupStart, resolutionTick });
            }
            n++;
        }

        if (cups.length > 0) {
            const cupNumbers = cups.map(c => c.cupNumber);
            const [{ data: hosts }, { data: myBids }] = await Promise.all([
                _supabase.from('vola_cup_hosts')
                    .select('cup_number, host_nation_id, nations:host_nation_id(name)')
                    .in('cup_number', cupNumbers),
                _supabase.from('vola_host_bids')
                    .select('cup_number, bid_at_tick')
                    .eq('nation_id', _state.nation.id)
                    .in('cup_number', cupNumbers),
            ]);
            const hostMap = new Map((hosts || []).map(h => [h.cup_number, h]));
            const myBidMap = new Map((myBids || []).map(b => [b.cup_number, b]));
            for (const c of cups) {
                c.host = hostMap.get(c.cupNumber) || null;
                // Combine the DB read with the in-session set so a
                // freshly-placed bid never re-renders as AVAILABLE,
                // even if the postgrest read-after-write lags a frame.
                const dbBid = myBidMap.get(c.cupNumber);
                const hasSessionBid = inSessionBids.has(c.cupNumber);
                c.iBid = !!dbBid || hasSessionBid;
                c.bidAtTick = dbBid?.bid_at_tick ?? inSessionBids.get(c.cupNumber) ?? null;
            }
            // Per-spec: "the next cup opens up 1 tick after the
            // current/upcoming World Cup passes." So Cup N+1 only
            // unlocks once tick > cupStart(N) — i.e., the previous
            // cup has already begun. Cup #1 has no predecessor and
            // is always selectable inside its bid window.
            // Already-bid cups are also locked out so the player
            // can't double-tap their way into a constraint error.
            for (const c of cups) {
                const prevCupStart = c.cupNumber > 1
                    ? _VWC_FIRST_TICK + _VWC_PERIOD * (c.cupNumber - 2)
                    : null;
                const prevCupHasPassed = prevCupStart === null || tick > prevCupStart;
                c.selectable = !c.host && !c.iBid && prevCupHasPassed;
            }
        }

        return {
            balance:      Number(mRow?.discretionary_balance) || 0,
            isMinister:   mRow?.party_id === faction.id,
            cups,
        };
    }

    async function render() {
        const { balance, isMinister, cups } = await refreshState();
        const cost = 10_000_000; // $10M raw
        const canAfford = balance >= cost;

        const cupRowsHtml = cups.length === 0
            ? `<div class="pa-empty-msg" style="padding:20px;text-align:center;font-family:var(--font-mono);font-size:10px;color:var(--text-dim);">No upcoming Vola World Cups within the bid window.</div>`
            : cups.map(c => {
                let badge = '';
                let cardStyle = '';
                let cls = '';
                let actionBtn = '';
                if (c.host) {
                    const hostName = c.host.nations?.name || 'Awarded';
                    badge = `<span class="pa-action-tag" style="color:var(--text-dim);">HOSTED — ${esc(hostName.toUpperCase())}</span>`;
                    cls = 'locked';
                    cardStyle = 'opacity:0.5;cursor:not-allowed;';
                } else if (c.iBid) {
                    badge = `<span class="pa-action-tag" style="color:#5cc55c;">YOUR BID PENDING</span>`;
                    cls = 'locked';
                    cardStyle = 'cursor:not-allowed;border-color:#5cc55c;background:rgba(92,197,92,0.06);';
                    // Greyed-out, disabled button replaces SUBMIT BID once
                    // a bid is on file. Keeps the cup row's visual rhythm
                    // identical to AVAILABLE so the Minister can see at a
                    // glance which cups they've already committed to,
                    // while the disabled attribute + cursor + opacity
                    // make it unmistakably non-clickable. No data-cup-number
                    // here so the click delegate skips it entirely (belt to
                    // the existing tagName !== 'BUTTON' suspender).
                    const placedCopy = c.bidAtTick != null
                        ? `Bid placed on ${_hbTickToDate(c.bidAtTick)} for $10`
                        : 'Bid placed earlier this session for $10';
                    actionBtn = `<button class="pa-modal-btn pa-modal-btn--placed" disabled style="background:transparent;color:#5cc55c;border:1px solid #5cc55c;padding:4px 10px;font-size:9px;cursor:not-allowed;opacity:0.75;font-weight:600;letter-spacing:0.04em;">${esc(placedCopy)}</button>`;
                } else if (c.selectable && isMinister && canAfford) {
                    badge = `<span class="pa-action-tag" style="color:#c8a832;">AVAILABLE</span>`;
                    cardStyle = 'cursor:pointer;border-color:#c8a832;background:rgba(200,168,50,0.06);';
                    actionBtn = `<button class="pa-modal-btn pa-modal-btn--submit" data-cup-number="${c.cupNumber}" ${submitting ? 'disabled' : ''} style="background:#c8a832;padding:4px 10px;font-size:9px;">Submit Bid — $10</button>`;
                } else if (c.selectable && !canAfford) {
                    badge = `<span class="pa-action-tag" style="color:var(--red);">INSUFFICIENT BUDGET</span>`;
                    cls = 'locked';
                    cardStyle = 'opacity:0.6;cursor:not-allowed;';
                } else {
                    badge = `<span class="pa-action-tag" style="color:var(--text-dim);">FUTURE CYCLE</span>`;
                    cls = 'locked';
                    cardStyle = 'opacity:0.5;cursor:not-allowed;';
                }

                return `<div class="pa-action-item ${cls}" data-cup-number="${c.cupNumber}" style="${cardStyle}">
                    <div class="pa-action-top">
                        <div>
                            <div style="font-size:13px;font-weight:700;color:var(--text-bright);">${_hbCupOrdinal(c.cupNumber)} World Vola Cup</div>
                            <div style="font-family:var(--font-mono);font-size:9px;color:var(--text-dim);margin-top:2px;">
                                Begins ${_hbTickToDate(c.cupStart)} · Bids resolve ${_hbTickToDate(c.resolutionTick)}
                            </div>
                        </div>
                        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;">
                            ${badge}
                            ${actionBtn}
                        </div>
                    </div>
                </div>`;
            }).join('');

        const formulaHtml = `
            <div style="margin-top:14px;padding:10px;background:var(--bg-card);border:1px solid var(--border-main);font-family:var(--font-mono);font-size:9px;color:var(--text-dim);line-height:1.6;">
                <div style="font-weight:700;color:var(--text-secondary);margin-bottom:4px;">Bid Score Formula</div>
                (Sports Culture &divide; 2) + (Infrastructure &times; 3) + (Global Image &times; 3) + (Stadiums &times; 5) + 1d20<br>
                Highest score wins · ties broken by Sports Culture
            </div>
        `;

        const winEffectsHtml = `
            <div style="margin-top:10px;padding:10px;background:rgba(92,197,92,0.06);border:1px solid rgba(92,197,92,0.2);font-family:var(--font-mono);font-size:9px;color:var(--text-dim);line-height:1.6;">
                <div style="font-weight:700;color:#5cc55c;margin-bottom:4px;">Win Effects</div>
                Host the VWC · +15 home advantage · +1d20+5 Budget · +3 Global Image · +0.5 Public Approval · +1d6 Sports Culture
            </div>
        `;

        const loseEffectsHtml = `
            <div style="margin-top:6px;padding:10px;background:rgba(200,80,80,0.06);border:1px solid rgba(200,80,80,0.2);font-family:var(--font-mono);font-size:9px;color:var(--text-dim);line-height:1.6;">
                <div style="font-weight:700;color:var(--red);margin-bottom:4px;">Lose Effect</div>
                &minus;0.2 Public Approval (failed national bid)
            </div>
        `;

        const resultHtml = result ? `
            <div style="margin-top:12px;padding:12px;background:rgba(200,168,50,0.08);border:1px solid rgba(200,168,50,0.22);">
                <div style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:#c8a832;margin-bottom:4px;">Bid submitted</div>
                <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);">
                    ${_hbCupOrdinal(result.cupNumber)} World Vola Cup · resolves ${_hbTickToDate(result.resolutionTick)}<br>
                    $${(result.cost / 1_000_000)} deducted from discretionary
                </div>
            </div>
        ` : '';

        const errorHtml = lastError ? `
            <div style="margin-top:10px;padding:8px 10px;background:rgba(200,80,80,0.08);border:1px solid rgba(200,80,80,0.2);font-family:var(--font-mono);font-size:10px;color:var(--red);">${esc(lastError)}</div>
        ` : '';

        overlay.innerHTML = `
            <div class="pa-modal" style="width:560px;max-height:85vh;overflow-y:auto;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Bid to Host Vola World Cup</span>
                    </div>
                    <button class="pa-modal-close" id="vola-host-x">&times;</button>
                </div>
                <div style="padding:10px 16px;border-bottom:1px solid var(--border-main);font-size:11px;color:var(--text-secondary);line-height:1.5;">
                    ${isMinister
                        ? `Discretionary budget <strong style="color:${balance > 0 ? 'var(--green)' : 'var(--red)'};">${fmtDiscretionaryBalance(balance)}</strong> available · cost <strong style="color:#c8a832;">$10</strong> per bid · once per cup.`
                        : '<span style="color:var(--red);">You are no longer the active Sports Minister.</span>'}
                </div>
                <div class="pa-modal-body" style="gap:6px;">
                    ${cupRowsHtml}
                    ${formulaHtml}
                    ${winEffectsHtml}
                    ${loseEffectsHtml}
                    ${resultHtml}
                    ${errorHtml}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="vola-host-close">Close</button>
                </div>
            </div>
        `;

        const close = () => { overlay.classList.remove('active'); renderPage(root); };
        document.getElementById('vola-host-x')?.addEventListener('click', close);
        document.getElementById('vola-host-close')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        overlay.querySelectorAll('[data-cup-number]').forEach(el => {
            // Only the inner Submit button gets a click handler — outer
            // card stays informational. Filter to <button> nodes.
            if (el.tagName !== 'BUTTON') return;
            el.addEventListener('click', async () => {
                if (submitting || result) return;
                const cupNumber = Number(el.dataset.cupNumber);
                if (!cupNumber) return;
                if (!confirm(`Submit a host bid for the ${_hbCupOrdinal(cupNumber)} World Vola Cup?\n\n$10 from discretionary budget.\nResolves at the qualifier tick (12 ticks before the cup begins).`)) return;
                submitting = true; lastError = null; render();
                try {
                    const r = await bidToHostVwc(_supabase, cupNumber, _state.nation.id);
                    if (r?.success) {
                        result = r;
                        // Capture the bid tick locally so the row can
                        // render its "Bid placed on …" line without
                        // waiting on the next DB read. Falls back to
                        // current tick if the RPC didn't echo one.
                        const { data: shardNow } = await _supabase.from('shard')
                            .select('current_tick').eq('name', 'Alpha Shard').single();
                        const placedTick = Number(shardNow?.current_tick) || Number(r.cupStartTick) - 999;
                        inSessionBids.set(cupNumber, placedTick);
                    } else {
                        // Server flagged a duplicate (constraint hit or
                        // explicit already_bid) — record locally too so
                        // the cup row reflects the bound state on the
                        // next render. Tick value isn't known here so
                        // we leave it null; the next refreshState will
                        // backfill from the DB row.
                        if (r?.reason === 'already_bid' && !inSessionBids.has(cupNumber)) {
                            inSessionBids.set(cupNumber, null);
                        }
                        lastError = _vwcBidReasonCopy(r?.reason) || 'Could not submit: ' + (r?.reason || 'unknown error');
                    }
                } catch (err) {
                    lastError = 'Bid failed: ' + (err?.message || err);
                } finally {
                    submitting = false;
                    render();
                }
            });
        });
    }

    function _vwcBidReasonCopy(reason) {
        const map = {
            invalid_cup:          'Invalid cup selection.',
            invalid_nation:       'Nation context unavailable. Reload and try again.',
            not_minister:         'Only the Sports Minister can submit host bids.',
            insufficient_balance: 'Sports discretionary budget is below $10M — pass a funding bill first.',
            no_shard:             'Game state unavailable. Try again.',
            bidding_closed:       'Bidding window has closed for this cup.',
            already_hosted:       'This cup has already been awarded.',
            already_bid:          'You have already bid for this cup.',
            cup_not_open_yet:     'This cup’s bid window opens 1 tick after the previous cup begins.',
        };
        return map[reason];
    }

    overlay.classList.add('active');
    await render();
}

