// "Commission a Geological Survey" vs "Commission an Agricultural
// Expansion" — pick the right article from the label's first letter.
function _aOrAn(noun) {
    return /^[aeiou]/i.test(noun) ? 'an' : 'a';
}

async function triggerSurvey(actionKey, faction) {
    if (_surveyInflight.has(actionKey)) return;
    if (!faction) return;
    const cfg = SURVEY_CONFIG[actionKey];
    if (!cfg) return;

    // Lock the whole flow (cost refresh + confirm + RPC) up front so a rapid
    // second click during the async cost refresh can't fire the survey twice.
    // Released on the cancel path below and in the finally.
    _surveyInflight.add(actionKey);

    // Refresh the card's cost from the server before reading it for the
    // confirm — the DOM cell can lag the live escalated cost after prior
    // uses (notably on mobile, where the initial patch can race). Both this
    // and the survey RPC count ministry_action_log, so the figure shown now
    // matches what will be charged.
    await patchSurveyCard(actionKey);

    // Read the live cost off the DOM cell — patchSurveyCard puts it there.
    // If the patch hasn't run yet, the cell still reads as the "$…"
    // placeholder and we skip the specific number in the confirm dialog.
    // The server is authoritative and will reject with insufficient_balance
    // + the real figure if we ask too cheaply.
    const costCellText = document.querySelector(
        `.pa-action-item[data-action-id="${actionKey}"] .pa-action-cost`
    )?.textContent?.trim() || '';
    const costLine = /^\$\d/.test(costCellText)
        ? `Cost: ${costCellText} (charged from ${cfg.ministryName} discretionary budget).\n`
        : `Cost is charged from ${cfg.ministryName} discretionary budget.\n`;

    if (!confirm(
        `Commission ${_aOrAn(cfg.actionLabel)} ${cfg.actionLabel}?\n\n` +
        costLine +
        `Cost ${cfg.costEscalation} every use. ${cfg.cooldownTicks}-tick cooldown after firing.\n\n` +
        cfg.oddsHint
    )) { _surveyInflight.delete(actionKey); return; }

    try {
        const { data, error } = await _supabase.rpc(cfg.rpc);
        if (error) {
            alert(`${cfg.actionLabel} failed: ${error.message}`);
            return;
        }
        if (!data?.success) {
            const reason = data?.reason || 'unknown error';
            let detail = '';
            if (data?.reason === 'insufficient_balance' && data?.cost) {
                detail = `\n\n(needed $${Math.round(Number(data.cost) / 1_000_000)}, have $${Math.round(Number(data.balance) / 1_000_000)})`;
            } else if (data?.reason === 'cooldown' && data?.ready_at_tick) {
                detail = `\n\nNext ${cfg.actionNoun} ready at tick ${data.ready_at_tick}.`;
            }
            alert(`Could not run ${cfg.actionNoun}: ${reason}${detail}`);
            patchSurveyCard(actionKey);
            return;
        }

        const bucketLabel = cfg.bucketLabels[data.bucket] || data.bucket;
        const bonus = (Number(data.total) - Number(data.d100)).toFixed(1);

        // Effective delta = visible before→after change. data.delta is the
        // rolled value, which can overstate the change when the stat
        // clipped at 100 (e.g. 98→100 on a +5 roll).
        const primaryBefore = data[`${cfg.primaryStat}_before`];
        const primaryAfter  = data[`${cfg.primaryStat}_after`];
        const effectiveDelta = Number(primaryAfter) - Number(primaryBefore);
        const primaryLine = `${cfg.primaryStatLabel}: ${primaryBefore} → ${primaryAfter}` +
            (effectiveDelta > 0 ? ' (+' + effectiveDelta + ')' : '');

        // Secondary stat (currently only agricultural expansion's industry
        // displacement). secondary_delta is already the effective post-floor
        // value, computed in the RPC.
        let secondaryLine = '';
        if (cfg.secondaryStat) {
            const secondaryDelta = Number(data[`${cfg.secondaryStat}_delta`] || 0);
            if (secondaryDelta > 0) {
                secondaryLine = '\n' + cfg.secondaryStatLabel + ': ' +
                    data[`${cfg.secondaryStat}_before`] + ' → ' + data[`${cfg.secondaryStat}_after`] +
                    ' (-' + secondaryDelta + ')';
            }
        }

        alert(
            cfg.actionLabel + ' — ' + bucketLabel + '\n\n' +
            'Roll: ' + data.d100 + ' + ' + bonus + ' (' + cfg.bonusLabel + ') = ' + data.total + '\n' +
            primaryLine + secondaryLine + '\n\n' +
            (data.description || '')
        );

        // Local state refresh: stat(s) on the nation + debited ministry
        // balance. Mirrors what the server just wrote.
        if (_state?.nation) {
            _state.nation[cfg.primaryStat] = Number(primaryAfter);
            if (cfg.secondaryStat) {
                _state.nation[cfg.secondaryStat] = Number(data[`${cfg.secondaryStat}_after`]);
            }
        }
        const m = (_heldMinistries || []).find(x => x.ministry_key === cfg.ministryKey);
        if (m) {
            const paid = Number(data.cost_paid) || 0;
            m.discretionary_balance = Math.max(0, Number(m.discretionary_balance || 0) - paid);
        }

        const panel = document.getElementById('pa-actions-panel');
        if (panel) panel.innerHTML = renderActionsPanel(null, null, faction);

        // Apply server-authoritative next_cost + cooldown directly from the
        // survey RPC's response. Earlier this called patchSurveyCard, which
        // re-fetches via the read-only helper RPCs — that path can race
        // against the just-committed action_log row's visibility to
        // PostgREST (especially on mobile / high-latency links) and
        // silently paint a stale cost over the freshly-rendered card. The
        // values we need are already in `data`; use them directly.
        const newCard = document.querySelector(
            `.pa-action-item[data-action-id="${actionKey}"]`
        );
        if (newCard) {
            _renderSurveyCardState(
                newCard,
                cfg,
                Number(data.next_cost),
                data.cooldown_until != null ? Number(data.cooldown_until) : null,
            );
        }
    } catch (err) {
        alert(`${cfg.actionLabel} failed: ${err?.message || err}`);
    } finally {
        _surveyInflight.delete(actionKey);
    }
}

// Pure DOM update for a survey card given the latest cost + cooldown.
// Shared by patchSurveyCard (which reads the values via the read-only
// helper RPCs) and triggerSurvey's success path (which already has
// them in the action RPC's response — applying directly there avoids
// a race where the follow-up read-RPC can fire before the just-
// committed action_log row is visible to PostgREST, which would
// silently paint a stale cost over the new HTML).
function _renderSurveyCardState(card, cfg, nextCostRaw, cooldownUntil) {
    const costCell = card.querySelector('.pa-action-cost');
    if (costCell && Number.isFinite(nextCostRaw) && nextCostRaw > 0) {
        costCell.textContent = '$' + Math.round(nextCostRaw / 1_000_000);
    }

    // Cooldown wins over budget — mirrors the server-side gate order in
    // each survey RPC.
    const currentTick = Number(_state?.shard?.current_tick) || 0;
    const ministry    = (_heldMinistries || []).find(m => m.ministry_key === cfg.ministryKey);
    const balance     = Number(ministry?.discretionary_balance ?? 0);

    let lockReason = '';
    if (Number.isFinite(cooldownUntil) && cooldownUntil > currentTick) {
        const away = cooldownUntil - currentTick;
        lockReason = `Cooldown — next ${cfg.actionNoun} ready at tick ${cooldownUntil} (${away} tick${away === 1 ? '' : 's'} away).`;
    } else if (Number.isFinite(nextCostRaw) && balance < nextCostRaw) {
        const displayed = Math.round(nextCostRaw / 1_000_000);
        lockReason = `${cfg.ministryName} discretionary budget is below $${displayed} — next ${cfg.actionNoun} cost has outgrown the budget.`;
    }

    const existingLockLine = card.querySelector('.' + cfg.lockLineClass);
    if (lockReason) {
        card.classList.add('locked');
        if (existingLockLine) {
            const span = existingLockLine.querySelector('span:last-child');
            if (span) span.textContent = lockReason;
        } else {
            const div = document.createElement('div');
            div.className = cfg.lockLineClass;
            div.style.cssText = 'margin-top:4px;font-family:var(--font-mono);font-size:7px;color:var(--orange);display:flex;align-items:center;gap:4px;';
            const icon = document.createElement('span'); icon.textContent = '⊘';
            const txt  = document.createElement('span'); txt.textContent = lockReason;
            div.appendChild(icon); div.appendChild(txt);
            card.appendChild(div);
        }
    } else {
        card.classList.remove('locked');
        if (existingLockLine) existingLockLine.remove();
    }
}

// Server owns the cost (escalates per use) and the cooldown. After every
// render of the relevant ministry detail, this fetches both, replaces the
// cost text in-place, and applies/removes the locked state. No module-
// level cache — display drift from a stale cache was the root cause of an
// earlier silent-failure bug class.
async function patchSurveyCard(actionKey) {
    const cfg = SURVEY_CONFIG[actionKey];
    if (!cfg) return;
    const card = document.querySelector(
        `.pa-action-item[data-action-id="${actionKey}"]`
    );
    if (!card) return; // The relevant ministry detail isn't on screen — no-op.

    const nationId = _state?.nation?.id;
    if (!nationId) return;

    let costRes, cdRes;
    try {
        [costRes, cdRes] = await Promise.all([
            _supabase.rpc(cfg.nextCostRpc,  { p_nation_id: nationId }),
            _supabase.rpc(cfg.cooldownRpc,  { p_nation_id: nationId }),
        ]);
    } catch (err) {
        console.warn(`[${cfg.actionLabel}] RPC fetch threw:`, err?.message || err);
        return;
    }
    if (costRes.error) console.warn(`[${cfg.actionLabel}] next_cost RPC failed:`, costRes.error.message);
    if (cdRes.error)   console.warn(`[${cfg.actionLabel}] cooldown_until RPC failed:`, cdRes.error.message);

    const nextCostRaw   = Number(costRes.data);
    const cooldownUntil = cdRes.data != null ? Number(cdRes.data) : null;

    _renderSurveyCardState(card, cfg, nextCostRaw, cooldownUntil);
}

