let _lawsuitSubmitting = false;

function openLawsuitModal(root) {
    const overlay = document.getElementById('pa-lawsuit-modal');
    if (!overlay) return;

    if (!_administration) {
        alert('No active government to file against.');
        return;
    }

    const faction = _state.faction;
    const ag = _agitator;
    let selectedTarget = null;
    let selectedBasis = null;

    function render() {
        const canFile = selectedTarget && selectedBasis;

        const targetsHtml = LAWSUIT_TARGETS.map(t => {
            const isSel = selectedTarget === t.key;
            return `<div class="pa-lawsuit-target ${isSel ? 'selected' : ''}" data-target="${t.key}">
                <span style="font-size:18px;">${t.icon}</span>
                <span style="font-size:12px;font-weight:600;color:${isSel ? 'var(--text-bright)' : 'var(--text-secondary)'};">${esc(t.label)}</span>
            </div>`;
        }).join('');

        const basesHtml = LAWSUIT_BASES.map(b => {
            const isSel = selectedBasis === b.key;
            return `<div class="pa-lawsuit-basis ${isSel ? 'selected' : ''}" data-basis="${b.key}">
                <div style="display:flex;align-items:center;gap:10px;">
                    <div style="width:16px;height:16px;border-radius:50%;border:2px solid ${isSel ? '#d44a4a' : 'var(--border-mid)'};display:flex;align-items:center;justify-content:center;">
                        ${isSel ? '<div style="width:8px;height:8px;border-radius:50%;background:#d44a4a;"></div>' : ''}
                    </div>
                    <div>
                        <div style="font-size:14px;font-weight:600;color:${isSel ? 'var(--text-bright)' : 'var(--text-secondary)'};">${esc(b.label)}</div>
                        <div style="font-size:11px;color:var(--text-dim);margin-top:2px;">${esc(b.desc)}</div>
                    </div>
                </div>
            </div>`;
        }).join('');

        overlay.innerHTML = `
            <div class="pa-modal" style="width:700px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#d44a4a;"></div>
                        <span class="pa-modal-title">File Lawsuit</span>
                        <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;padding:3px 8px;color:#5a8aaa;background:rgba(90,138,170,0.08);border:1px solid rgba(90,138,170,0.2);margin-left:6px;">LEGAL</span>
                        <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;padding:3px 8px;color:#c84;background:rgba(200,132,0,0.08);border:1px solid rgba(200,132,0,0.2);">OFFENSIVE</span>
                    </div>
                    <button class="pa-modal-close" id="pa-lawsuit-close">&times;</button>
                </div>

                ${ag ? `<div style="padding:6px 16px;border-bottom:1px solid var(--border-main);background:rgba(212,74,74,0.04);display:flex;align-items:center;gap:8px;">
                    <span style="width:5px;height:5px;border-radius:50%;background:#d44a4a;display:inline-block;"></span>
                    <span style="font-family:var(--font-mono);font-size:9px;color:var(--text-secondary);">Filed by:</span>
                    <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;color:#d44a4a;">${esc(ag.first_name)} ${esc(ag.last_name)}</span>
                    <span style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">Skill ${ag.skill}</span>
                </div>` : ''}

                <div class="pa-modal-body" style="gap:16px;">
                    <div>
                        <div class="pa-modal-step-label">1 &mdash; Target Ministry</div>
                        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:4px;" id="pa-lawsuit-targets">${targetsHtml}</div>
                    </div>

                    <div>
                        <div class="pa-modal-step-label">2 &mdash; Legal Basis</div>
                        <div style="display:flex;flex-direction:column;gap:4px;" id="pa-lawsuit-bases">${basesHtml}</div>
                    </div>

                    <div style="padding:8px 10px;background:var(--bg-card);border:1px solid var(--border-main);">
                        <div style="font-family:var(--font-mono);font-size:7px;color:var(--text-dim);letter-spacing:0.06em;margin-bottom:3px;">INTELLIGENCE</div>
                        <div style="font-size:9px;color:var(--text-dim);font-style:italic;">No intelligence gathered. File FOIA requests first to assess corruption levels.</div>
                    </div>

                    <div style="padding:8px 10px;background:rgba(212,74,74,0.04);border:1px solid rgba(212,74,74,0.12);">
                        <div style="font-family:var(--font-mono);font-size:7px;color:#d44a4a;letter-spacing:0.06em;margin-bottom:4px;">COST &amp; RISK</div>
                        <div style="font-size:9px;color:var(--text-dim);line-height:1.6;">
                            <strong style="color:var(--text-bright);">FREE</strong> &middot; Duration: <strong style="color:var(--text-bright);">8 ticks</strong><br>
                            If corruption growth is low (0-5):<br>
                            <span style="color:var(--red);">YOU: -5 Momentum</span><br>
                            <span style="color:var(--green);">THEM: +3 Momentum</span>
                        </div>
                    </div>
                </div>

                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-lawsuit-cancel">Cancel</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-lawsuit-submit" ${canFile ? '' : 'disabled'} style="background:#d44a4a;">File Lawsuit</button>
                </div>
            </div>
        `;

        // Bind
        const close = () => overlay.classList.remove('active');
        document.getElementById('pa-lawsuit-close')?.addEventListener('click', close);
        document.getElementById('pa-lawsuit-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        document.getElementById('pa-lawsuit-targets')?.addEventListener('click', (e) => {
            const el = e.target.closest('.pa-lawsuit-target');
            if (!el) return;
            selectedTarget = el.dataset.target;
            render();
        });

        document.getElementById('pa-lawsuit-bases')?.addEventListener('click', (e) => {
            const el = e.target.closest('.pa-lawsuit-basis');
            if (!el) return;
            selectedBasis = el.dataset.basis;
            render();
        });

        document.getElementById('pa-lawsuit-submit')?.addEventListener('click', async () => {
            if (_lawsuitSubmitting || !selectedTarget || !selectedBasis) return;
            _lawsuitSubmitting = true;
            const btn = document.getElementById('pa-lawsuit-submit');
            if (btn) { btn.disabled = true; btn.textContent = 'Filing...'; }

            try {
                // Deduct $250k from party funds
                const lawsuitCost = 250000;
                const { data: freshFac } = await _supabase.from('factions').select('party_funds').eq('id', faction.id).single();
                const curFunds = freshFac?.party_funds || 0;
                if (curFunds < lawsuitCost) {
                    alert(`Not enough funds. You have $${Math.round(curFunds / 1000)}k, need $250k.`);
                    _lawsuitSubmitting = false;
                    if (btn) { btn.disabled = false; btn.textContent = 'File Lawsuit'; }
                    return;
                }
                const newFunds = curFunds - lawsuitCost;
                await _supabase.from('factions').update({ party_funds: newFunds }).eq('id', faction.id);
                faction.party_funds = newFunds;
                sessionStorage.removeItem('nationhood_state');

                const tick = _state.shard?.current_tick || 0;
                const result = await fileLawsuit(_supabase, {
                    factionId: faction?.id,
                    nationId: _state.nation?.id,
                    agitatorId: ag?.id,
                    targetMinistry: selectedTarget,
                    basis: selectedBasis,
                    currentTick: tick,
                    partyName: faction?.faction_name || 'Opposition',
                    administration: _administration,
                });

                if (!result.success) {
                    alert(result.error || 'Failed to file lawsuit.');
                    return;
                }

                const tierInfo = calculateTier(result.lawsuit?.corruption_growth || 0);
                const effects = TIER_EFFECTS[result.tier] || TIER_EFFECTS[1];
                close();

                // Show a brief result notification
                alert(`Lawsuit filed against ${LAWSUIT_TARGETS.find(t => t.key === selectedTarget)?.label || selectedTarget}.\nThe case is now under investigation. Results will be determined when it resolves in 8 ticks.`);

                renderPage(root);
            } catch (err) {
                console.error('[PartyActions] File lawsuit error:', err);
                alert('An error occurred. Please try again.');
            } finally {
                _lawsuitSubmitting = false;
                if (btn) { btn.disabled = false; btn.textContent = 'File Lawsuit'; }
            }
        });
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ GRANT / REVOKE SEATS (Monarchy) ════════════════════════

async function openAppointPMModal(root) {
    const overlay = document.getElementById('pa-appoint-pm-modal');
    if (!overlay) return;

    const nation = _state.nation;
    const faction = _state.faction;

    // Fetch all parties in this nation
    const { data: allFactions } = await _supabase.from('factions')
        .select('id, faction_name, abbreviation, party_color, seats, leader_first_name, leader_last_name, leader_age')
        .eq('nation_id', nation.id).eq('faction_type', 'party').is('abandoned_at', null)
        .order('seats', { ascending: false });

    const parties = allFactions || [];
    let selectedPartyId = null;
    let submitting = false;

    // Check current PM
    const { data: currentHog } = await _supabase.from('head_of_government')
        .select('faction_id, first_name, last_name, factions(faction_name)')
        .eq('nation_id', nation.id).eq('active', true).maybeSingle();

    function render() {
        const selected = parties.find(p => p.id === selectedPartyId);
        const currentPmName = currentHog ? `${currentHog.first_name} ${currentHog.last_name}` : null;
        const currentPmParty = currentHog?.factions?.faction_name || null;
        const isSameAsCurrentPM = currentHog && selectedPartyId === currentHog.faction_id;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:500px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Appoint Prime Minister</span>
                        <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;padding:3px 8px;color:#c8a832;background:rgba(200,168,50,0.06);border:1px solid rgba(200,168,50,0.15);">ROYAL</span>
                    </div>
                    <button class="pa-modal-close" id="apm-close">&times;</button>
                </div>
                <div style="padding:8px 20px;border-bottom:1px solid var(--border-main);font-size:12px;color:var(--text-secondary);line-height:1.5;">
                    Choose a party to lead the government. Their leader becomes Prime Minister and can assign cabinet ministries.
                    ${currentPmName ? `<div style="margin-top:4px;font-family:var(--font-mono);font-size:9px;color:var(--text-dim);">Current PM: <strong style="color:var(--text-bright);">${esc(currentPmName)}</strong> (${esc(currentPmParty || '?')})</div>` : '<div style="margin-top:4px;font-family:var(--font-mono);font-size:9px;color:var(--amber);">No Prime Minister appointed.</div>'}
                </div>
                <div class="pa-modal-body" style="max-height:300px;overflow-y:auto;">
                    <div class="pa-modal-step-label">Select a Party</div>
                    <div style="display:flex;flex-direction:column;gap:4px;">
                        ${parties.map(p => {
                            const isSel = p.id === selectedPartyId;
                            const isCurrent = currentHog && p.id === currentHog.faction_id;
                            const leaderName = p.leader_first_name && p.leader_last_name ? `${p.leader_first_name} ${p.leader_last_name}` : '?';
                            return `<div class="pa-action-item ${isSel ? 'selected' : ''}" data-party-id="${p.id}" style="cursor:pointer;${isSel ? `border-color:${p.party_color || '#888'};background:${(p.party_color || '#888')}08;` : ''}">
                                <div style="display:flex;justify-content:space-between;align-items:center;">
                                    <div style="display:flex;align-items:center;gap:8px;">
                                        <div style="width:8px;height:8px;background:${p.party_color || '#888'};"></div>
                                        <div>
                                            <div style="font-size:13px;font-weight:600;color:var(--text-bright);">${esc(p.faction_name)}</div>
                                            <div style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">${esc(leaderName)}, Age ${p.leader_age || '?'} · ${p.seats || 0} seats</div>
                                        </div>
                                    </div>
                                    ${isCurrent ? '<span style="font-family:var(--font-mono);font-size:7px;font-weight:700;padding:2px 6px;color:var(--green);background:rgba(92,204,92,0.08);border:1px solid rgba(92,204,92,0.2);">CURRENT PM</span>' : ''}
                                </div>
                            </div>`;
                        }).join('')}
                    </div>
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="apm-cancel">Cancel</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="apm-confirm" ${!selected || submitting || isSameAsCurrentPM ? 'disabled' : ''} style="background:#c8a832;">${selected ? (isSameAsCurrentPM ? 'Already PM' : `Appoint ${esc(selected.faction_name)}`) : 'Select a party'}</button>
                </div>
            </div>
        `;

        const close = () => overlay.classList.remove('active');
        document.getElementById('apm-close')?.addEventListener('click', close);
        document.getElementById('apm-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        // Party selection
        overlay.querySelector('.pa-modal-body')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-party-id]');
            if (item) { selectedPartyId = item.dataset.partyId; render(); }
        });

        // Confirm appointment
        document.getElementById('apm-confirm')?.addEventListener('click', async () => {
            if (!selectedPartyId || submitting) return;
            const party = parties.find(p => p.id === selectedPartyId);
            if (!party) return;

            if (!confirm(`Appoint ${party.leader_first_name} ${party.leader_last_name} of ${party.faction_name} as Prime Minister?`)) return;

            submitting = true;
            const btn = document.getElementById('apm-confirm');
            if (btn) { btn.disabled = true; btn.textContent = 'Appointing...'; }

            try {
                const currentTick = _state.shard?.current_tick || 0;

                // Single source of truth — installHOG handles dedup (UNIQUE
                // nation_id), the canonical leader_ideology lookup, and the
                // upsert shape used by every other PM-install path.
                await installHOG(_supabase, {
                    nationId: nation.id,
                    factionId: selectedPartyId,
                    firstName: party.leader_first_name || 'Unknown',
                    lastName: party.leader_last_name || 'Unknown',
                    age: party.leader_age || 50,
                    currentTick,
                });

                // Persist a real government_formations row so reads stop
                // depending on the synthetic monarchy fallback in
                // government-structure.js. Mirrors the parliamentary
                // pattern: dissolve any prior formed/caretaker/active rows,
                // then insert a fresh 'formed' row keyed to this royal
                // appointment. Non-blocking: the synthetic fallback still
                // covers a write failure.
                try {
                    await _supabase.from('government_formations')
                        .update({ status: 'dissolved' })
                        .eq('nation_id', nation.id)
                        .in('status', ['formed', 'caretaker', 'active']);
                    const { data: shardData } = await _supabase.from('shard')
                        .select('current_date').eq('name', 'Alpha Shard').single();
                    await _supabase.from('government_formations').insert({
                        nation_id: nation.id,
                        election_id: null,
                        proposed_by: faction.id,
                        party_ids: [selectedPartyId],
                        status: 'formed',
                        formation_type: 'monarchy',
                        formed_at: new Date().toISOString(),
                        ministry_assignments: { prime_minister: selectedPartyId },
                        game_year: shardData?.current_date || '',
                    });
                } catch (gfErr) {
                    console.warn('[AppointPM] government_formations write failed (non-blocking — synthetic fallback still works):', gfErr?.message || gfErr);
                }

                // Crown-authority effects (monarchy only). Dismissing a
                // non-monarch PM costs -4. Appointing a non-monarch PM
                // grants +3. (Was previously routed to public_approval as
                // a Phase 7H legacy; consolidated onto crown_authority
                // alongside grant/revoke/veto.)
                let crownAuthorityDelta = 0;
                const monarchPartyId = nation.monarch_faction_id;
                const prevPmPartyId = currentHog?.faction_id || null;
                const dismissingNonMonarchPm = prevPmPartyId && prevPmPartyId !== monarchPartyId && prevPmPartyId !== selectedPartyId;
                const appointingNonMonarchPm = selectedPartyId !== monarchPartyId && selectedPartyId !== prevPmPartyId;
                if (dismissingNonMonarchPm) crownAuthorityDelta -= 4;
                if (appointingNonMonarchPm) crownAuthorityDelta += 3;
                if (crownAuthorityDelta !== 0) {
                    const currentCA = Number(nation.crown_authority ?? 50);
                    const newCA = Math.max(0, Math.min(100, currentCA + crownAuthorityDelta));
                    try {
                        await _supabase.from('nations').update({ crown_authority: newCA }).eq('id', nation.id);
                        nation.crown_authority = newCA;
                    } catch (_) { /* non-blocking */ }
                }

                // Log event (non-blocking)
                try {
                    await _supabase.from('event_log').insert({
                        nation_id: nation.id,
                        event_name: `${nation.monarch_title || 'King'} appoints Prime Minister`,
                        category: 'government',
                        description_chosen: `${nation.monarch_title || 'The King'} has appointed ${party.leader_first_name} ${party.leader_last_name} of ${party.faction_name} as Prime Minister.`,
                        fired_at_tick: currentTick,
                    });
                } catch (_) { /* non-blocking */ }

                close();
                const caSuffix = crownAuthorityDelta > 0
                    ? `\n\nCrown Authority +${crownAuthorityDelta}.`
                    : crownAuthorityDelta < 0
                        ? `\n\nCrown Authority ${crownAuthorityDelta}.`
                        : '';
                alert(`${party.leader_first_name} ${party.leader_last_name} of ${party.faction_name} has been appointed Prime Minister.${caSuffix}`);
                renderPage(root);
            } catch (err) {
                alert('Failed to appoint PM: ' + (err.message || 'Error'));
                submitting = false;
                if (btn) { btn.disabled = false; btn.textContent = `Appoint ${esc(party.faction_name)}`; }
            }
        });
    }

    overlay.classList.add('active');
    render();
}

async function openGrantSeatsModal(root) {
    const overlay = document.getElementById('pa-royal-modal');
    if (!overlay) return;

    const nation = _state.nation;
    const faction = _state.faction;
    const monarchSeats = faction.seats || 0;
    const totalSeats = nation?.total_seats || 100;

    // Fetch all factions in this nation
    const { data: allFactions } = await _supabase.from('factions')
        .select('id, faction_name, abbreviation, party_color, seats')
        .eq('nation_id', nation.id).eq('faction_type', 'party').is('abandoned_at', null)
        .order('faction_name');

    const otherFactions = (allFactions || []).filter(f => f.id !== faction.id);
    let selectedFactionId = null;
    const maxGrant = Math.max(0, monarchSeats - 1); // keep at least 1 seat
    let grantAmount = Math.min(5, maxGrant || 1);

    function render() {
        const selected = otherFactions.find(f => f.id === selectedFactionId);

        overlay.innerHTML = `
            <div class="pa-modal" style="width:560px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#c8a832;"></div>
                        <span class="pa-modal-title">Grant Seats</span>
                        <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;padding:3px 8px;color:#c8a832;background:rgba(200,168,50,0.06);border:1px solid rgba(200,168,50,0.15);">ROYAL</span>
                    </div>
                    <button class="pa-modal-close" id="royal-close">&times;</button>
                </div>
                <div style="padding:8px 20px;border-bottom:1px solid var(--border-main);font-size:12px;color:var(--text-secondary);line-height:1.5;">
                    Grant parliamentary seats to a noble house. Each seat granted earns <span style="color:#5cc55c;font-weight:700;">+0.5 Crown Authority</span>.
                    You currently hold <strong>${monarchSeats}</strong> of ${totalSeats} seats.
                    ${monarchSeats / totalSeats > 0.7 ? '<div style="color:#d44a4a;font-weight:700;margin-top:4px;">⚠ You hold >70% of seats — tyranny crown authority decay active!</div>' : ''}
                </div>
                <div class="pa-modal-body">
                    <div class="pa-modal-step-label">Select Noble House</div>
                    <div style="display:flex;flex-direction:column;gap:4px;">
                        ${otherFactions.length > 0 ? otherFactions.map(f => {
                            const isSel = f.id === selectedFactionId;
                            return `<div class="pa-action-item ${isSel ? 'selected' : ''}" data-faction-id="${f.id}" style="cursor:pointer;${isSel ? `border-color:${f.party_color || '#888'};background:${(f.party_color || '#888')}08;` : ''}">
                                <div style="display:flex;justify-content:space-between;align-items:center;">
                                    <div style="display:flex;align-items:center;gap:8px;">
                                        <div style="width:8px;height:8px;background:${f.party_color || '#888'};"></div>
                                        <span style="font-size:14px;font-weight:600;color:var(--text-bright);">${esc(f.faction_name)}</span>
                                    </div>
                                    <span style="font-family:var(--font-mono);font-size:13px;color:var(--text-dim);">${Math.max(0, f.seats || 0)} seats</span>
                                </div>
                            </div>`;
                        }).join('') : '<div style="font-size:12px;color:var(--text-dim);padding:20px;text-align:center;">No other factions in this nation.</div>'}
                    </div>
                    ${selected ? `
                        <div style="margin-top:14px;">
                            <div class="pa-modal-step-label">Seats to Grant</div>
                            <div style="display:flex;align-items:center;gap:12px;">
                                <input type="range" min="1" max="${maxGrant}" value="${grantAmount}" id="grant-slider" style="flex:1;">
                                <span style="font-family:var(--font-mono);font-size:18px;font-weight:700;color:var(--accent);width:40px;text-align:center;" id="grant-count">${grantAmount}</span>
                            </div>
                            <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim);margin-top:4px;">
                                Crown Authority gain: <span style="color:#5cc55c;font-weight:700;">+${(grantAmount * 0.5).toFixed(1)}</span>
                                &middot; Your seats after: ${monarchSeats - grantAmount} &middot; Their seats after: ${(selected.seats || 0) + grantAmount}
                            </div>
                        </div>
                    ` : ''}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="royal-cancel">Cancel</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="royal-grant" ${!selected ? 'disabled' : ''} style="background:#c8a832;">Grant ${grantAmount} Seats</button>
                </div>
            </div>
        `;

        const close = () => overlay.classList.remove('active');
        document.getElementById('royal-close')?.addEventListener('click', close);
        document.getElementById('royal-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        // Faction selection
        overlay.querySelector('.pa-modal-body')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-faction-id]');
            if (item) { selectedFactionId = item.dataset.factionId; render(); }
        });

        // Slider
        document.getElementById('grant-slider')?.addEventListener('input', (e) => {
            grantAmount = parseInt(e.target.value) || 1;
            document.getElementById('grant-count').textContent = grantAmount;
            const btn = document.getElementById('royal-grant');
            if (btn) btn.textContent = `Grant ${grantAmount} Seats`;
        });

        // Grant button
        document.getElementById('royal-grant')?.addEventListener('click', async () => {
            if (!selectedFactionId) return;
            if (_seatTxInProgress) return;
            _seatTxInProgress = true;
            const btn = document.getElementById('royal-grant');
            if (btn) { btn.disabled = true; btn.textContent = 'Granting...'; }

            try {
                // Re-fetch all factions to get fresh seat counts
                const { data: freshFactions } = await _supabase.from('factions')
                    .select('id, faction_name, seats')
                    .eq('nation_id', nation.id).eq('faction_type', 'party').is('abandoned_at', null);
                const freshMonarch = (freshFactions || []).find(f => f.id === faction.id);
                const freshTarget = (freshFactions || []).find(f => f.id === selectedFactionId);
                if (!freshMonarch || !freshTarget) { alert('Faction not found.'); return; }

                const sumBefore = (freshFactions || []).reduce((s, f) => s + Math.max(0, f.seats || 0), 0);

                // Build a working map of seat counts so we can validate conservation in one place.
                const seatMap = new Map();
                for (const f of (freshFactions || [])) seatMap.set(f.id, Math.max(0, f.seats || 0));

                // 1. Take from monarch (leave at least 1 seat).
                let remaining = grantAmount;
                const monarchAvail = Math.max(0, (seatMap.get(faction.id) || 0) - 1);
                const monarchTake = Math.min(remaining, monarchAvail);
                if (monarchTake > 0) {
                    seatMap.set(faction.id, (seatMap.get(faction.id) || 0) - monarchTake);
                    remaining -= monarchTake;
                }

                // 2. If monarch couldn't cover, take proportionally from other parties (excluding target).
                if (remaining > 0) {
                    const donors = (freshFactions || [])
                        .filter(f => f.id !== faction.id && f.id !== selectedFactionId && (seatMap.get(f.id) || 0) > 0);
                    let donorPool = donors.reduce((s, f) => s + (seatMap.get(f.id) || 0), 0);
                    for (const d of donors) {
                        if (remaining <= 0 || donorPool <= 0) break;
                        const share = Math.round(remaining * (seatMap.get(d.id) || 0) / donorPool);
                        const take = Math.min(share, seatMap.get(d.id) || 0, remaining);
                        if (take > 0) {
                            seatMap.set(d.id, (seatMap.get(d.id) || 0) - take);
                            donorPool -= take;
                            remaining -= take;
                        }
                    }
                    // Top-up pass: if rounding left a leftover, drain remaining from any donor with seats.
                    if (remaining > 0) {
                        for (const d of donors) {
                            if (remaining <= 0) break;
                            const avail = seatMap.get(d.id) || 0;
                            const take = Math.min(remaining, avail);
                            if (take > 0) {
                                seatMap.set(d.id, avail - take);
                                remaining -= take;
                            }
                        }
                    }
                }

                const actualGrant = grantAmount - remaining;
                if (actualGrant <= 0) { alert('No seats available to grant.'); return; }

                // 3. Credit target.
                seatMap.set(selectedFactionId, (seatMap.get(selectedFactionId) || 0) + actualGrant);

                // 4. Conservation invariant: sum-after must equal sum-before.
                let sumAfter = 0;
                for (const v of seatMap.values()) sumAfter += v;
                if (sumAfter !== sumBefore) {
                    console.error('[GrantSeats] Conservation violated', { sumBefore, sumAfter, grantAmount, actualGrant });
                    alert('Internal error: seat totals would not balance. Aborting.');
                    return;
                }

                // 5. Write only the rows whose seats actually changed.
                const writes = [];
                for (const f of (freshFactions || [])) {
                    const before = Math.max(0, f.seats || 0);
                    const after = seatMap.get(f.id) || 0;
                    if (before !== after) writes.push({ id: f.id, seats: after });
                }
                for (const w of writes) {
                    const { error } = await _supabase.from('factions').update({ seats: w.seats }).eq('id', w.id);
                    if (error) { alert('Failed to grant seats: ' + error.message); return; }
                }

                const caGain = actualGrant * 0.5;
                const newCA = Math.min(100, (Number(nation.crown_authority) || 50) + caGain);
                const { error: e3 } = await _supabase.from('nations').update({ crown_authority: newCA }).eq('id', nation.id);
                if (e3) { alert('Failed to update crown authority.'); return; }

                faction.seats = seatMap.get(faction.id) || 0;
                nation.crown_authority = newCA;

                // Log event (non-blocking)
                try {
                    const target = otherFactions.find(f => f.id === selectedFactionId);
                    await _supabase.from('event_log').insert({
                        nation_id: nation.id,
                        event_name: `${nation.monarch_title || 'King'} grants ${actualGrant} seats to ${target?.faction_name || 'unknown'}`,
                        category: 'government',
                        description_chosen: `The ${nation.monarch_title || 'King'} has granted ${actualGrant} parliamentary seat${actualGrant !== 1 ? 's' : ''} to ${target?.faction_name}. Crown Authority +${caGain.toFixed(1)}.`,
                        fired_at_tick: _state.shard?.current_tick || 0,
                    });
                } catch (_) { /* non-blocking */ }

                close();
                renderPage(root);
            } catch (err) {
                console.error('[GrantSeats] Error:', err);
                alert('Failed to grant seats.');
            } finally {
                _seatTxInProgress = false;
            }
        });
    }

    overlay.classList.add('active');
    render();
}

async function openRevokeSeatsModal(root) {
    const overlay = document.getElementById('pa-royal-modal');
    if (!overlay) return;

    const nation = _state.nation;
    const faction = _state.faction;

    const { data: allFactions } = await _supabase.from('factions')
        .select('id, faction_name, abbreviation, party_color, seats')
        .eq('nation_id', nation.id).eq('faction_type', 'party').is('abandoned_at', null)
        .order('faction_name');

    const seatedFactions = (allFactions || []).filter(f => f.id !== faction.id && (f.seats || 0) > 0);
    let selectedFactionId = null;
    let revokeAmount = 1;

    function render() {
        const selected = seatedFactions.find(f => f.id === selectedFactionId);
        const maxRevoke = selected ? selected.seats || 0 : 0;
        const costPerSeat = 100000;
        const totalCost = revokeAmount * costPerSeat;
        const currentFunds = faction.party_funds || 0;

        overlay.innerHTML = `
            <div class="pa-modal" style="width:560px;">
                <div class="pa-modal-header">
                    <div class="pa-modal-header-left">
                        <div class="pa-modal-dot" style="background:#d44a4a;"></div>
                        <span class="pa-modal-title">Revoke Seats</span>
                        <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;padding:3px 8px;color:#d44a4a;background:rgba(212,74,74,0.06);border:1px solid rgba(212,74,74,0.15);">ROYAL</span>
                    </div>
                    <button class="pa-modal-close" id="royal-close">&times;</button>
                </div>
                <div style="padding:8px 20px;border-bottom:1px solid var(--border-main);font-size:12px;color:var(--text-secondary);line-height:1.5;">
                    Revoke seats from a noble house. Costs <span style="color:#d44a4a;font-weight:700;">$100k per seat</span> and
                    <span style="color:#d44a4a;font-weight:700;">-1 Crown Authority per seat</span>. Revoked seats return to the crown.
                </div>
                <div class="pa-modal-body">
                    <div class="pa-modal-step-label">Select Noble House</div>
                    <div style="display:flex;flex-direction:column;gap:4px;">
                        ${seatedFactions.length > 0 ? seatedFactions.map(f => {
                            const isSel = f.id === selectedFactionId;
                            return `<div class="pa-action-item ${isSel ? 'selected' : ''}" data-faction-id="${f.id}" style="cursor:pointer;${isSel ? 'border-color:#d44a4a;background:rgba(212,74,74,0.04);' : ''}">
                                <div style="display:flex;justify-content:space-between;align-items:center;">
                                    <div style="display:flex;align-items:center;gap:8px;">
                                        <div style="width:8px;height:8px;background:${f.party_color || '#888'};"></div>
                                        <span style="font-size:14px;font-weight:600;color:var(--text-bright);">${esc(f.faction_name)}</span>
                                    </div>
                                    <span style="font-family:var(--font-mono);font-size:13px;color:var(--text-dim);">${f.seats} seats</span>
                                </div>
                            </div>`;
                        }).join('') : '<div style="font-size:12px;color:var(--text-dim);padding:20px;text-align:center;">No factions have seats to revoke.</div>'}
                    </div>
                    ${selected ? `
                        <div style="margin-top:14px;">
                            <div class="pa-modal-step-label">Seats to Revoke</div>
                            <div style="display:flex;align-items:center;gap:12px;">
                                <input type="range" min="1" max="${maxRevoke}" value="${revokeAmount}" id="revoke-slider" style="flex:1;">
                                <span style="font-family:var(--font-mono);font-size:18px;font-weight:700;color:#d44a4a;width:40px;text-align:center;" id="revoke-count">${revokeAmount}</span>
                            </div>
                            <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim);margin-top:4px;">
                                Cost: <span style="color:#d44a4a;font-weight:700;">$${Math.round(totalCost / 1000)}k</span>
                                &middot; Crown Authority: <span style="color:#d44a4a;font-weight:700;">-${revokeAmount}</span>
                                ${currentFunds < totalCost ? '<span style="color:#d44a4a;margin-left:8px;">⚠ Not enough funds</span>' : ''}
                            </div>
                        </div>
                    ` : ''}
                </div>
                <div class="pa-modal-footer">
                    <button class="pa-modal-btn pa-modal-btn--cancel" id="royal-cancel">Cancel</button>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="royal-revoke" ${!selected || currentFunds < totalCost ? 'disabled' : ''} style="background:#d44a4a;">Revoke ${revokeAmount} Seats</button>
                </div>
            </div>
        `;

        const close = () => overlay.classList.remove('active');
        document.getElementById('royal-close')?.addEventListener('click', close);
        document.getElementById('royal-cancel')?.addEventListener('click', close);
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        overlay.querySelector('.pa-modal-body')?.addEventListener('click', (e) => {
            const item = e.target.closest('[data-faction-id]');
            if (item) { selectedFactionId = item.dataset.factionId; revokeAmount = 1; render(); }
        });

        document.getElementById('revoke-slider')?.addEventListener('input', (e) => {
            revokeAmount = parseInt(e.target.value) || 1;
            document.getElementById('revoke-count').textContent = revokeAmount;
            const btn = document.getElementById('royal-revoke');
            if (btn) btn.textContent = `Revoke ${revokeAmount} Seats`;
        });

        document.getElementById('royal-revoke')?.addEventListener('click', async () => {
            if (!selectedFactionId) return;
            if (_seatTxInProgress) return;
            _seatTxInProgress = true;
            const btn = document.getElementById('royal-revoke');
            if (btn) { btn.disabled = true; btn.textContent = 'Revoking...'; }

            try {
                const cost = revokeAmount * 100000;

                // Fetch fresh state for monarch + target so we don't write stale seats.
                const { data: freshFactions } = await _supabase.from('factions')
                    .select('id, faction_name, seats, party_funds')
                    .eq('nation_id', nation.id).eq('faction_type', 'party').is('abandoned_at', null);
                const freshMonarch = (freshFactions || []).find(f => f.id === faction.id);
                const freshTarget = (freshFactions || []).find(f => f.id === selectedFactionId);
                if (!freshMonarch || !freshTarget) { alert('Faction not found.'); return; }

                const curFunds = freshMonarch.party_funds || 0;
                if (curFunds < cost) { alert('Not enough funds.'); return; }

                const sumBefore = (freshFactions || []).reduce((s, f) => s + Math.max(0, f.seats || 0), 0);

                const take = Math.min(revokeAmount, freshTarget.seats || 0);
                if (take <= 0) { alert('Target has no seats to revoke.'); return; }

                const newFunds = curFunds - cost;
                const newMonarchSeats = (freshMonarch.seats || 0) + take;
                const newTargetSeats = (freshTarget.seats || 0) - take;
                const caCost = take;
                const newCA = Math.max(0, (Number(nation.crown_authority) || 50) - caCost);

                // Conservation invariant: monarch gains exactly what target loses.
                const sumAfter = sumBefore - (freshMonarch.seats || 0) - (freshTarget.seats || 0)
                    + newMonarchSeats + newTargetSeats;
                if (sumAfter !== sumBefore) {
                    console.error('[RevokeSeats] Conservation violated', { sumBefore, sumAfter, take });
                    alert('Internal error: seat totals would not balance. Aborting.');
                    return;
                }

                const { error: e1 } = await _supabase.from('factions').update({ seats: newMonarchSeats, party_funds: newFunds }).eq('id', faction.id);
                if (e1) { alert('Failed to revoke seats: ' + e1.message); return; }
                const { error: e2 } = await _supabase.from('factions').update({ seats: newTargetSeats }).eq('id', selectedFactionId);
                if (e2) { alert('Failed to revoke seats: ' + e2.message); return; }
                const { error: e3 } = await _supabase.from('nations').update({ crown_authority: newCA }).eq('id', nation.id);
                if (e3) { alert('Failed to update crown authority.'); return; }

                faction.seats = newMonarchSeats;
                faction.party_funds = newFunds;
                nation.crown_authority = newCA;
                sessionStorage.removeItem('nationhood_state');

                try {
                    await _supabase.from('event_log').insert({
                        nation_id: nation.id,
                        event_name: `${nation.monarch_title || 'King'} revokes ${take} seats from ${freshTarget.faction_name || 'unknown'}`,
                        category: 'political',
                        description_chosen: `The ${nation.monarch_title || 'King'} has revoked ${take} seat${take !== 1 ? 's' : ''} from ${freshTarget.faction_name}. Crown Authority -${caCost}.`,
                        fired_at_tick: _state.shard?.current_tick || 0,
                    });
                } catch (_) { /* non-blocking */ }

                close();
                renderPage(root);
            } catch (err) {
                console.error('[RevokeSeats] Error:', err);
                alert('Failed to revoke seats.');
            } finally {
                _seatTxInProgress = false;
            }
        });
    }

    overlay.classList.add('active');
    render();
}

// ════════════════════════ VOTE OF NO CONFIDENCE ════════════════════════
// Files a no_confidence bill against the current PM and writes the cooldown
// row in campaign_actions. Same backend shape as government.html's
// fileNoConfidence() so the bill resolves through the same tick path.

// ════════════════════════ CALL EARLY ELECTIONS (PM-ONLY) ════════════════════════
// Thin wrapper around elections.callEarlyElectionsAction. The server-side helper
// handles cooldowns (6 ticks since last election, 2-tick guard on next scheduled),
// sets the government to caretaker, schedules the election at
// currentTick + EARLY_ELECTION_TICKS, and applies tiered momentum based on
// gov_approval. All we add here is a PM-party + confirm + lock guard.

let _callEarlyElectionsSubmitting = false;

async function triggerCallEarlyElections() {
    if (_callEarlyElectionsSubmitting) return;
    if (!_state?.faction?.id || !_state?.nation?.id) return;
    if (!hasParliamentaryPM(_state.nation)) { alert('Early elections are only available in parliamentary and semi-presidential systems.'); return; }
    if (isAbsoluteMonarchy(_state.nation)) { alert('Elections are not held under absolute monarchy.'); return; }
    const pmPartyId = _administration?.pm_party_id;
    if (!pmPartyId || pmPartyId !== _state.faction.id) { alert('Prime Minister\u2019s party only.'); return; }

    if (!confirm(
        '\u26A1 CALL EARLY ELECTIONS?\n\n' +
        'Dissolves the legislature and puts the government into caretaker status.\n' +
        'Election fires after a short formation window.\n\n' +
        'Momentum effect depends on Gov. Approval:\n' +
        '\u2022 >50  \u2192 PM party +3 Momentum (fresh mandate)\n' +
        '\u2022 35\u201350 \u2192 neutral\n' +
        '\u2022 <35  \u2192 opposition +5 Momentum each, +3 Stability\n\n' +
        'Proceed?'
    )) return;

    _callEarlyElectionsSubmitting = true;
    try {
        // Reuse the administration's coalition party list if present so the tiered
        // momentum code can target opposition correctly. Falls back to an empty
        // array if unknown (server-side logic still runs with the PM-party delta).
        const coalitionIds = Array.isArray(_administration?.party_ids)
            ? _administration.party_ids
            : (_administration?.pm_party_id ? [_administration.pm_party_id] : []);
        const result = await callEarlyElectionsAction(
            _supabase,
            _state.nation.id,
            pmPartyId,
            coalitionIds
        );
        if (result && result.success === false) {
            alert('Could not call early elections: ' + (result.error || 'unknown error'));
            return;
        }
        alert('\u26A1 Early elections called. Government is now in caretaker status.');
        window.location.reload();
    } catch (err) {
        console.error('[PartyActions] Call early elections failed:', err);
        alert('Failed to call early elections: ' + (err?.message || 'unknown error'));
    } finally {
        _callEarlyElectionsSubmitting = false;
    }
}

// ════════════════════════ RESIGN AS PM (PM-ONLY) ════════════════════════
// Thin wrapper around political-actions.resignPM. Server-side applies the
// fixed penalties (\u22123 momentum, \u22120.05 credibility, \u22123 stability, 12-tick
// PM ban), vacates the PM seat, puts the coalition into caretaker, and
// schedules a snap election at currentTick + FORMATION_DEADLINE_TICKS so
// the coalition has a window to nominate a successor before the fallback
// election fires.

// ════════════════════════ LEAVE COALITION ════════════════════════
// Walk out of the current governing coalition. Thin wrapper around
// the leave_coalition SECURITY DEFINER RPC — confirm dialog, RPC
// call, reload. All gating (parliamentary, not-opposition, not-PM,
// cooldown) is mirrored server-side so a bypass still fails.

let _leaveCoalitionSubmitting = false;
let _formMinorityGovSubmitting = false;

async function triggerFormMinorityGovernment() {
    if (_formMinorityGovSubmitting) return;
    if (!_state?.nation?.id) return;

    if (!confirm(
        'FORM MINORITY GOVERNMENT?\n\n' +
        'Consequences:\n' +
        '• Your party governs alone — no coalition partners\n' +
        '• Bills pass with -20% effective YES votes\n' +
        '• A snap election fires automatically in 36 ticks if a stable\n' +
        '  coalition isn\'t formed before then\n' +
        '• Other parties’ ministers are dismissed; only your PM remains\n\n' +
        'Proceed?'
    )) return;

    _formMinorityGovSubmitting = true;
    try {
        const r = await formMinorityGovernment(_supabase, _state.nation.id);
        if (!r?.success) {
            const reasonCopy = {
                invalid_nation:     'Nation context unavailable. Reload and try again.',
                not_parliamentary:  'This action only applies to parliamentary governments.',
                not_party_leader:   'Only a party leader can form a minority government.',
                no_shard:           'Game state unavailable.',
                no_election:        'No completed election to form a government from.',
                gate_not_elapsed:   'The coalition window has not yet closed.',
                majority_exists:    'A party already holds an outright majority — form a normal government instead.',
                coalition_exists:   'A government has already been formed for this cycle.',
                already_minority:   'A minority government is already in place.',
                no_active_parties:  'No active parties qualify to form a government.',
                not_largest_active: 'Only the largest active party may form a minority government.',
                rpc_failed:         r?.error || 'Server error — try again.',
            };
            const copy = reasonCopy[r?.reason] || (r?.reason || 'Unknown error');
            alert('Could not form minority government:\n\n' + copy);
            return;
        }
        alert('Minority government formed.');
        window.location.reload();
    } catch (err) {
        console.error('[PartyActions] Form Minority Government failed:', err);
        alert('Failed to form minority government: ' + (err?.message || err));
    } finally {
        _formMinorityGovSubmitting = false;
    }
}

async function triggerLeaveCoalition() {
    if (_leaveCoalitionSubmitting) return;
    if (!_state?.faction?.id) return;

    if (!confirm(
        'LEAVE COALITION?\n\n' +
        'Consequences:\n' +
        '• −3 Momentum to your party\n' +
        '• −5 Momentum to the Prime Minister’s party\n' +
        '• Any ministries you hold will be vacated\n' +
        '• Your party moves from governing to opposition\n' +
        '• Coalition flips to minority if your exit drops it below majority\n' +
        '• 12-tick cooldown before you can leave another coalition\n\n' +
        'Proceed?'
    )) return;

    _leaveCoalitionSubmitting = true;
    try {
        const { data, error } = await _supabase.rpc('leave_coalition', {
            p_faction_id: _state.faction.id,
        });
        if (error) throw error;
        if (data && data.success === false) throw new Error(data.error || 'Unknown error');

        const minorityNote = data?.became_minority
            ? '\n\nThe government is now a minority.'
            : '';
        const vacatedNote = (data?.ministries_vacated || 0) > 0
            ? `\n\n${data.ministries_vacated} ministr${data.ministries_vacated === 1 ? 'y' : 'ies'} vacated.`
            : '';
        alert('You have left the coalition.' + minorityNote + vacatedNote);
        window.location.reload();
    } catch (err) {
        console.error('[PartyActions] Leave Coalition failed:', err);
        alert('Failed to leave coalition: ' + (err?.message || err));
    } finally {
        _leaveCoalitionSubmitting = false;
    }
}

let _leadershipChallengeSubmitting = false;

async function triggerLeadershipChallenge(root, faction) {
    if (_leadershipChallengeSubmitting || _leadershipChallengeClaimed) return;
    if (!_state?.nation?.id || !faction?.id) return;

    if (!confirm(
        'LEADERSHIP CHALLENGE?\n\n' +
        'Claim the vacant Premiership for your party leader.\n' +
        'Resolves on the next tick. If multiple coalition parties claim, the\n' +
        'largest by seats wins (earliest claim breaks ties).\n\n' +
        'Winner gets +0.3 popularity across all voter sectors\n' +
        '(suppressed if your party held PM in the last 12 ticks).\n\n' +
        'Proceed?'
    )) return;

    _leadershipChallengeSubmitting = true;
    try {
        const { data: shard } = await _supabase.from('shard').select('current_tick').eq('name', 'Alpha Shard').single();
        const currentTick = Number(shard?.current_tick) || 0;
        const r = await claimLeadershipChallenge(_supabase, _state.nation, faction, currentTick);
        if (r?.success) {
            _leadershipChallengeClaimed = true;
            const msg = r.alreadyClaimed
                ? 'You already submitted this tick — sit tight, resolves next tick.'
                : 'Leadership Challenge submitted. Resolves on the next tick.';
            alert(msg);
            renderPage(root);
        } else {
            const reasonMap = {
                wrong_gov_type:        'Leadership Challenge is only available in parliamentary systems.',
                pm_already_installed:  'A Prime Minister is already serving — vacancy required.',
                no_coalition:          'No active coalition.',
                not_in_coalition:      'Your party is not in the governing coalition.',
                not_owner:             'This session is not authorized to act for that party. Refresh or re-select your faction; admins must deploy the admin-inspector Leadership Challenge migration.',
                no_leader:             'Your party has no leader to install.',
                no_seats:              'Your party holds no parliamentary seats.',
                rpc_failed:            'Server function call failed. The claim_leadership_challenge RPC may not be deployed yet — run migration 20260917_claim_leadership_challenge_rpc.sql.',
            };
            // Surface the SQL/RPC error message inline so future failures
            // are debuggable without diving into the console.
            const baseMsg = reasonMap[r?.reason] || ('Could not submit: ' + (r?.reason || 'unknown error'));
            const detail  = r?.error ? `\n\nDetail: ${r.error}` : '';
            alert(baseMsg + detail);
            console.warn('[LeadershipChallenge] failed:', r);
        }
    } catch (err) {
        console.error('[PartyActions] Leadership Challenge failed:', err);
        alert('Leadership Challenge failed: ' + (err?.message || err));
    } finally {
        _leadershipChallengeSubmitting = false;
    }
}

let _resignPMSubmitting = false;

async function triggerResignAsPM() {
    if (_resignPMSubmitting) return;
    if (!_state?.faction?.id || !_state?.nation?.id) return;
    if (!hasParliamentaryPM(_state.nation)) { alert('Resignation is only available in parliamentary and semi-presidential systems.'); return; }
    if (isAbsoluteMonarchy(_state.nation)) { alert('Prime Ministers serve at the Monarch’s pleasure. The Monarch must replace the PM via the Appoint Prime Minister royal action.'); return; }
    const pmPartyId = _administration?.pm_party_id;
    if (!pmPartyId || pmPartyId !== _state.faction.id) { alert('Prime Minister\u2019s party only.'); return; }

    if (!confirm(
        '\u26A0 RESIGN AS PRIME MINISTER?\n\n' +
        'The PM seat vacates immediately. Coalition enters caretaker status with\n' +
        `a ${FORMATION_DEADLINE_TICKS}-tick window to nominate a successor via the cabinet panel.\n` +
        'If a new PM is installed, the administration continues under new leadership.\n' +
        'If the window expires, a snap election is called.\n\n' +
        'Cost to your party:\n' +
        '\u2022 \u22123 Momentum\n' +
        '\u2022 \u22120.05 Skill\n' +
        '\u2022 Nation: \u22123 Stability\n' +
        '\u2022 12-tick bar from the PM seat on your party\n\n' +
        'Proceed?'
    )) return;

    _resignPMSubmitting = true;
    try {
        const { data: shard } = await _supabase.from('shard').select('current_tick').eq('name', 'Alpha Shard').single();
        const tick = shard?.current_tick || _state.shard?.current_tick || 0;
        const result = await resignPM(_supabase, _state.nation.id, _state.faction.id, tick);
        // resignPM returns { result: 'election_called'|'succession_window', ... }
        if (result?.result === 'election_called') {
            alert('You have resigned. Snap election scheduled as fallback if no successor is nominated.');
        } else {
            alert('You have resigned. Coalition has a short window to nominate a successor before a snap election fires.');
        }
        window.location.reload();
    } catch (err) {
        console.error('[PartyActions] Resign PM failed:', err);
        alert('Failed to resign: ' + (err?.message || 'unknown error'));
    } finally {
        _resignPMSubmitting = false;
    }
}

// ════════════════════════ DISBAND PARTY ════════════════════════
// Mirror of the corp bankruptcy flow — one destructive RPC call,
// double-confirm on the client (confirm dialog + typed string),
// then redirect to faction-select so the player can pick what to
// play next.

let _disbandPartySubmitting = false;

async function triggerDisbandParty() {
    if (_disbandPartySubmitting) return;
    if (!_state?.faction?.id) return;

    const faction = _state.faction;
    const partyName = faction.faction_name || 'this party';
    const seats = faction.seats || 0;
    const momentum = Number(faction.momentum || 0).toFixed(1);
    const funds = Math.round(Number(faction.party_funds || 0));
    const fundsFormatted = funds >= 1000 ? '$' + funds.toLocaleString() : '$' + funds;

    if (!confirm(
        'DISBAND ' + partyName.toUpperCase() + '?\n\n' +
        'This will permanently:\n' +
        '• Dissolve the party\n' +
        '• Vacate ' + seats + ' seat' + (seats === 1 ? '' : 's') + ' in parliament (empty until next election; no backfill)\n' +
        '• Forfeit ' + fundsFormatted + ' in party funds\n' +
        '• Forfeit ' + momentum + ' momentum\n' +
        '• Remove you from every nation chat\n' +
        '• Cascade-delete platforms, ideology, bloc membership,\n' +
        '  and any pending bloc invitations\n\n' +
        'You will need to found a new party.\n' +
        'There is a 24-tick cooldown on disbanding.\n\n' +
        'This action CANNOT be undone.'
    )) return;

    _disbandPartySubmitting = true;
    try {
        const { data, error } = await _supabase.rpc('disband_party', {
            p_faction_id: faction.id,
        });
        if (error) throw error;
        if (data && data.success === false) throw new Error(data.error || 'Unknown error');

        sessionStorage.removeItem('active_faction_id');
        sessionStorage.removeItem('nationhood_state');

        const { data: { user } } = await _supabase.auth.getUser();
        if (user) {
            // Pick the next faction to show. RLS gates this — only this
            // user's remaining factions come back.
            const { data: remaining } = await _supabase
                .from('factions')
                .select('id, faction_type')
                .or(`id.eq.${user.id},linked_user_id.eq.${user.id}`);
            const otherParty = (remaining || []).find(f => f.faction_type === 'party');
            if (otherParty) {
                sessionStorage.setItem('active_faction_id', otherParty.id);
                alert(partyName + ' has been disbanded.\n\nRedirecting to your other party.');
                window.location.href = 'dashboard.html';
                return;
            }
            // Legacy corporations are retired (corp-cull) — no corp to switch
            // to; fall through to the faction chooser.
        }

        alert(partyName + ' has been disbanded.\n\nYou have no remaining factions.');
        window.location.href = 'faction-select.html';
    } catch (err) {
        console.error('[PartyActions] Disband failed:', err);
        alert('Disband failed: ' + (err?.message || err));
    } finally {
        _disbandPartySubmitting = false;
    }
}

let _impeachSubmitting = false;

async function triggerImpeachPresident() {
    if (_impeachSubmitting) return;
    const faction = _state?.faction;
    const nation  = _state?.nation;
    if (!faction?.id || !nation?.id) return;
    if (!_activePresident) {
        alert('No sitting President to impeach.');
        return;
    }
    _impeachSubmitting = true;
    try {
        const currentTick = Number(_state?.shard?.current_tick) || 0;
        await openImpeachmentTrigger(_supabase, {
            faction,
            nation,
            president: _activePresident,
            isPresidentParty: _activePresident.faction_id === faction.id,
            mySeats: faction.seats || 0,
            currentTick,
        });
        // openImpeachmentTrigger redirects on success (window.location to
        // bill.html). Cancel / failure paths just return; the gate
        // re-renders next tick poll.
    } catch (err) {
        console.error('[party-actions] impeachment threw:', err?.message || err);
        alert('Impeachment failed — check console.');
    } finally {
        _impeachSubmitting = false;
    }
}

let _noConfidenceSubmitting = false;

async function triggerNoConfidence() {
    if (_noConfidenceSubmitting) return;
    if (!_state?.faction?.id || !_state?.nation?.id) return;

    const faction     = _state.faction;
    const nation      = _state.nation;
    const isSemiPres  = isSemiPresidential(nation);

    if (!hasParliamentaryPM(nation)) {
        alert('A vote of no confidence is only possible in a parliamentary or semi-presidential system.');
        return;
    }

    // Resolve the active PM's faction id and last name. The lock state already
    // checked the PM-party / cooldown / pending guards; we re-verify here in
    // case state drifted between render and click.
    const { data: hog } = await _supabase.from('head_of_government')
        .select('faction_id, last_name').eq('nation_id', nation.id).eq('active', true).maybeSingle();
    const pmFactionId = hog?.faction_id || nation.ruling_faction_id || null;
    const pmLastName  = hog?.last_name || null;

    if (!pmFactionId) { alert('No active Prime Minister to file against.'); return; }
    if (pmFactionId === faction.id) { alert('Your party is the Prime Minister — you cannot file a vote of no confidence against yourself.'); return; }

    const mySeats = (_state.faction?.seats != null ? Number(_state.faction.seats) : 0);
    if (mySeats < 1) { alert('Your party needs at least 1 seat in the legislature to file a motion.'); return; }

    const { data: shard } = await _supabase.from('shard').select('current_tick').eq('name', 'Alpha Shard').single();
    const tick = shard?.current_tick || _state.shard?.current_tick || 0;

    // Re-check pending + cooldown at click time (race with another opposition party).
    const { data: pendBills } = await _supabase.from('bills')
        .select('id').eq('nation_id', nation.id).eq('bill_type', 'no_confidence').in('status', ['committee', 'floor']).limit(1);
    if (pendBills && pendBills.length > 0) { alert('A motion of no confidence is already pending.'); return; }

    const { data: lastFiled } = await _supabase.from('campaign_actions')
        .select('tick_performed').eq('nation_id', nation.id).eq('action_type', 'no_confidence_filed').eq('target_id', pmFactionId)
        .order('tick_performed', { ascending: false }).limit(1).maybeSingle();
    if (lastFiled) {
        const elapsed = tick - Number(lastFiled.tick_performed || 0);
        if (elapsed < GAME_CONFIG.NO_CONFIDENCE_COOLDOWN_TICKS) {
            const remaining = GAME_CONFIG.NO_CONFIDENCE_COOLDOWN_TICKS - elapsed;
            alert(`Cooldown: ${remaining} tick${remaining !== 1 ? 's' : ''} remaining before another motion can be filed against this PM party.`);
            return;
        }
    }

    const motionName = pmLastName
        ? (isSemiPres ? `Motion of No Confidence in PM ${pmLastName}` : `Motion of No Confidence in the ${pmLastName} Government`)
        : `Motion of No Confidence in the Government`;

    const passConsequences = isSemiPres
        ? `IF IT PASSES:\n\u2022 PM removed \u2014 President must nominate a new PM\n\u2022 Your party: +15 Momentum\n\u2022 PM's party: -10 Momentum`
        : `IF IT PASSES:\n\u2022 Coalition dissolved, PM removed, all ministries vacated\n\u2022 Snap elections scheduled\n\u2022 Your party: +15 Momentum\n\u2022 PM's party: -10 Momentum`;

    if (!confirm(
        `\u26a1 FILE VOTE OF NO CONFIDENCE?\n\n"${motionName}"\n\n` +
        `Cost: $0 \u2014 free to file\n` +
        `Voting period: ${GAME_CONFIG.NO_CONFIDENCE_VOTING_TICKS} ticks\n` +
        `Needs simple majority (YES > NO) to pass.\n\n${passConsequences}\n\n` +
        `IF IT FAILS:\n\u2022 Your party: -10 Momentum\n` +
        `\u2022 ${GAME_CONFIG.NO_CONFIDENCE_COOLDOWN_TICKS}-tick cooldown on this PM party\n\nProceed?`
    )) return;

    _noConfidenceSubmitting = true;
    try {
        const result = await fileNoConfidenceMotion(_supabase, {
            faction,
            nation,
            pmFactionId,
            pmLastName,
            isSemiPres,
            tick,
            mySeats,
        });
        if (!result.ok) {
            alert('Failed to file motion: ' + result.error);
            return;
        }

        alert(`\u26a1 "${result.motionName}" has been filed!\n\nVoting is now open for ${GAME_CONFIG.NO_CONFIDENCE_VOTING_TICKS} ticks.`);
        window.location.href = `bill.html?id=${result.billId}`;
    } catch (e) {
        console.error('[PartyActions] No confidence file failed:', e);
        alert('Failed to file motion: ' + (e?.message || 'unknown error'));
    } finally {
        _noConfidenceSubmitting = false;
    }
}

// ════════════════════════ FUNDRAISE ════════════════════════

let _fundraiseSubmitting = false;
let _fundraiserEvents = []; // 12 themed events from fundraiser_events table
let _fundraiserSelected = null;

async function loadFundraiserEvents() {
    if (_fundraiserEvents.length > 0) return;
    const { data, error } = await _supabase
        .from('fundraiser_events')
        .select('event_key, name, icon, host_sector_key, opposition_sector_key, display_order')
        .order('display_order');
    if (error) {
        console.warn('[PartyActions] fundraiser_events load failed:', error.message);
        _fundraiserEvents = [];
        return;
    }
    _fundraiserEvents = data || [];
}

// Resolve sector_key → { id, name, weight, popularity_tenths } for the
// current nation + faction. Returns null when the bloc isn't seeded.
async function _resolveSectorState(sectorKey) {
    if (!sectorKey || !_state?.nation?.id || !_state?.faction?.id) return null;
    const { data: sec } = await _supabase
        .from('sectors')
        .select('id, name, weight')
        .eq('nation_id', _state.nation.id)
        .eq('sector_key', sectorKey)
        .eq('is_active', true)
        .maybeSingle();
    if (!sec?.id) return null;
    const { data: pop } = await _supabase
        .from('faction_sector_popularity')
        .select('popularity')
        .eq('faction_id', _state.faction.id)
        .eq('sector_id', sec.id)
        .maybeSingle();
    return {
        id: sec.id,
        name: sec.name,
        weight: Number(sec.weight) || 1,
        popularity_tenths: Number(pop?.popularity) || 0,
    };
}

async function executeFundraise(root) {
    if (_fundraiseSubmitting) return;

    if (_fundraiseUseCount >= 1) {
        alert('You have already hosted a fundraiser this tick. Try again next tick.');
        return;
    }

    await loadFundraiserEvents();
    if (_fundraiserEvents.length === 0) {
        alert('No fundraiser events configured. Run migration 20260728.');
        return;
    }

    _fundraiserSelected = null;
    await renderFundraiseModal(root);
}

async function renderFundraiseModal(root) {
    // Mount overlay (built lazily so we don't add unused HTML to every page).
    let overlay = document.getElementById('pa-fundraise-modal');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.id = 'pa-fundraise-modal';
        overlay.className = 'pa-modal-overlay';
        overlay.innerHTML = `
            <div class="pa-modal" style="width:min(880px, 96vw);max-height:90vh;display:flex;flex-direction:column;">
                <div class="pa-modal-header">
                    <div class="pa-modal-title">FUNDRAISE — Pick a Host</div>
                    <button type="button" class="pa-modal-close" data-act="fr-close">&times;</button>
                </div>
                <div class="pa-modal-subtitle" style="padding:0 20px 8px 20px;font-size:11px;color:var(--text-secondary);">
                    Once per tick · Yield = $25k × your popularity × bloc weight (Corporate Gala excluded). Costs popularity with both blocs.
                </div>
                <div id="pa-fundraise-body" style="flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0;border-top:1px solid var(--border-main);">
                </div>
            </div>`;
        document.body.appendChild(overlay);
        overlay.addEventListener('click', (e) => {
            if (e.target.matches('[data-act="fr-close"]') || e.target === overlay) {
                overlay.style.display = 'none';
            }
        });
    }
    overlay.style.display = 'flex';

    const body = overlay.querySelector('#pa-fundraise-body');
    body.innerHTML = '<div style="padding:14px;font-family:var(--font-mono);font-size:10px;color:var(--text-dim);">Loading sectors…</div>';

    // Resolve all hosts + oppositions in parallel.
    const sectorStates = {};
    const allKeys = new Set();
    for (const ev of _fundraiserEvents) {
        allKeys.add(ev.host_sector_key);
        allKeys.add(ev.opposition_sector_key);
    }
    await Promise.all(Array.from(allKeys).map(async (k) => {
        sectorStates[k] = await _resolveSectorState(k);
    }));

    const cardsHtml = _fundraiserEvents.map(ev => {
        const host = sectorStates[ev.host_sector_key];
        const popDisplay = host ? (host.popularity_tenths / 10).toFixed(1) : '—';
        const weight = host?.weight || 1;
        return `
            <div class="pa-fr-card" data-event-key="${esc(ev.event_key)}" style="padding:10px 14px;border-bottom:1px dashed var(--border-main);cursor:pointer;">
                <div style="display:flex;align-items:baseline;gap:8px;">
                    <span style="font-size:14px;">${ev.icon}</span>
                    <span style="font-family:var(--font-serif, 'IBM Plex Serif', serif);font-size:14px;font-weight:600;color:var(--text-bright);">${esc(ev.name)}</span>
                </div>
                <div style="font-family:var(--font-mono);font-size:9px;letter-spacing:0.06em;color:var(--text-dim);text-transform:uppercase;margin-top:2px;">
                    ${esc(host?.name || ev.host_sector_key)} · w${weight} · pop ${popDisplay}
                </div>
            </div>`;
    }).join('');

    body.innerHTML = `
        <div id="pa-fr-list" style="overflow-y:auto;border-right:1px solid var(--border-main);">
            ${cardsHtml}
        </div>
        <div id="pa-fr-detail" style="padding:14px 18px;overflow-y:auto;">
            <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-dim);font-style:italic;">Pick an event on the left to see details.</div>
        </div>`;

    body.querySelectorAll('.pa-fr-card').forEach(card => {
        card.addEventListener('click', () => {
            _fundraiserSelected = card.dataset.eventKey;
            body.querySelectorAll('.pa-fr-card').forEach(c => c.style.background = '');
            card.style.background = 'rgba(200,168,50,0.08)';
            renderFundraiseDetail(body, sectorStates, root);
        });
    });
}

function renderFundraiseDetail(body, sectorStates, root) {
    const detail = body.querySelector('#pa-fr-detail');
    const ev = _fundraiserEvents.find(e => e.event_key === _fundraiserSelected);
    if (!ev) return;
    const host = sectorStates[ev.host_sector_key];
    const opp  = sectorStates[ev.opposition_sector_key];
    const hostPop = host ? (host.popularity_tenths / 10).toFixed(1) : '—';
    const hostWeight = host?.weight || 1;
    const oppPop = opp ? (opp.popularity_tenths / 10).toFixed(1) : '—';

    const hostBlocked = !host;
    const oppMissing = !opp;

    // Projection only — the SQL is canonical (sql/migrations/20261215).
    // If the yield equation changes there, mirror it here too.
    // Corporate Gala is positioning-only (corps already donate via lobbyist actions).
    const yieldsCash = ev.event_key !== 'corporate_gala';
    const projectedYield = (yieldsCash && host)
        ? 1250 * (host.popularity_tenths || 0) * Math.max(1, host.weight || 1)
        : 0;

    detail.innerHTML = `
        <div style="display:flex;align-items:baseline;gap:8px;">
            <span style="font-size:18px;">${ev.icon}</span>
            <span style="font-family:var(--font-serif);font-size:18px;font-weight:600;color:var(--text-bright);">${esc(ev.name)}</span>
        </div>

        <div style="margin-top:14px;">
            <div style="font-family:var(--font-mono);font-size:9px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;">Host bloc</div>
            <div style="font-family:var(--font-serif);font-size:14px;color:var(--text-bright);margin-top:2px;">${esc(host?.name || ev.host_sector_key)}</div>
            <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);margin-top:2px;">Your popularity: <strong style="color:var(--text-bright);">${hostPop}</strong> · National weight: <strong style="color:var(--text-bright);">w${hostWeight}</strong></div>
        </div>

        <div style="margin-top:14px;">
            <div style="font-family:var(--font-mono);font-size:9px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;">Paired opposition</div>
            <div style="font-family:var(--font-serif);font-size:14px;color:var(--text-bright);margin-top:2px;">${esc(opp?.name || ev.opposition_sector_key)}</div>
            <div style="font-family:var(--font-mono);font-size:10px;color:var(--text-secondary);margin-top:2px;">Your popularity: <strong style="color:var(--text-bright);">${oppPop}</strong></div>
        </div>

        <div style="margin-top:18px;padding:10px 12px;background:var(--bg-card);border:1px solid var(--border-main);">
            <div style="font-family:var(--font-mono);font-size:9px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;margin-bottom:6px;">Costs (popularity)</div>
            <div style="display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:11px;color:var(--text-bright);padding:2px 0;">
                <span>↓ ${esc(host?.name || ev.host_sector_key)}</span><span style="color:#d44a4a;font-weight:700;">−0.3 (donor fatigue)</span>
            </div>
            <div style="display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:11px;color:var(--text-bright);padding:2px 0;">
                <span>↓ ${esc(opp?.name || ev.opposition_sector_key)}</span>
                ${oppMissing
                    ? '<span style="color:var(--text-dim);font-style:italic;">not in this nation — no cost</span>'
                    : '<span style="color:#d44a4a;font-weight:700;">−0.5 (optics)</span>'}
            </div>
        </div>

        <div style="margin-top:10px;padding:10px 12px;background:var(--bg-card);border:1px solid var(--border-main);">
            <div style="font-family:var(--font-mono);font-size:9px;letter-spacing:0.1em;color:var(--text-dim);text-transform:uppercase;margin-bottom:6px;">Projected yield</div>
            <div style="display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:11px;color:var(--text-bright);padding:2px 0;">
                <span>↑ Party funds</span>
                ${yieldsCash
                    ? `<span style="color:#5cb85c;font-weight:700;">+${hfFmtBig(projectedYield)}</span>`
                    : '<span style="color:var(--text-dim);font-style:italic;">positioning only — no yield</span>'}
            </div>
        </div>

        ${hostBlocked
            ? '<div style="margin-top:14px;font-family:var(--font-mono);font-size:10px;color:var(--red);">This nation does not have the host bloc seeded — pick a different event.</div>'
            : ''}

        <div style="margin-top:18px;text-align:right;">
            <button type="button" class="pa-modal-btn pa-modal-btn--primary"
                    id="pa-fr-confirm"
                    ${hostBlocked ? 'disabled' : ''}
                    style="padding:8px 18px;font-family:var(--font-mono);font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;background:rgba(200,168,50,0.08);border:1px solid var(--gold, #c8a832);color:var(--gold, #c8a832);cursor:pointer;${hostBlocked ? 'opacity:0.4;cursor:not-allowed;' : ''}">
                Host this fundraiser
            </button>
        </div>
    `;

    const confirmBtn = detail.querySelector('#pa-fr-confirm');
    if (confirmBtn) {
        confirmBtn.addEventListener('click', () => submitFundraise(root));
    }
}

async function submitFundraise(root) {
    if (_fundraiseSubmitting || !_fundraiserSelected) return;
    _fundraiseSubmitting = true;
    try {
        const tick = _state.shard?.current_tick || 0;
        const { data, error } = await _supabase.rpc('fundraise_themed', {
            p_faction_id: _state.faction.id,
            p_nation_id:  _state.nation.id,
            p_event_key:  _fundraiserSelected,
            p_tick:       tick,
        });
        if (error || !data?.success) {
            alert('Fundraise failed: ' + (error?.message || data?.error || 'unknown'));
            return;
        }
        const overlay = document.getElementById('pa-fundraise-modal');
        if (overlay) overlay.style.display = 'none';
        sessionStorage.removeItem('nationhood_state');
        _fundraiseUseCount++;
        const yieldAmt = Number(data?.yield) || 0;
        if (yieldAmt > 0) {
            alert('Fundraiser hosted. +' + hfFmtBig(yieldAmt) + ' to party funds.');
        }
        renderPage(root);
    } catch (err) {
        console.error('[PartyActions] Fundraise error:', err);
        alert('Fundraise failed.');
    } finally {
        _fundraiseSubmitting = false;
    }
}

